window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-24"]={"date":"2026-07-24","dateKR":"2026년 7월 24일","dateEN":"24 July 2026","total":176,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. 주요 뉴스","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"우크라이나 흑해 항만 선박 기항 중단, 러시아 공습 우려로 곡물 수출 마비","src":"gCaptain","date":"2026-07-23","kSum":"선주들이 러시아의 항만·상선 공습이 급증하자 우크라이나 흑해 항만 기항을 자발적으로 중단했다고 우크라이나 농업장관이 밝혔다. 7월 23일 성수기 수확기임에도 흑해 해상회랑을 통과한 선박은 전무했으며, 머스크(Maersk)와 하파크로이드(Hapag-Lloyd)는 초르노모르스크 운영을 중단했다.","eSum":"Shipowners have suspended calls at Ukraine's Black Sea ports amid a surge in Russian strikes on ports and merchant ships, the country's agriculture minister said. Zero vessels transited the corridor on July 23 at peak harvest, with Maersk and Hapag-Lloyd halting operations at Chornomorsk.","kImp":"세계 곡물 공급망과 전쟁위험보험료에 직접 타격을 주는 지정학적 리스크의 재확대다.","eImp":"A direct hit to global grain supply chains and war-risk insurance costs, reigniting geopolitical shipping risk.","url":"https://gcaptain.com/shipowners-halt-calls-at-ukraines-black-sea-ports-wary-of-russian-strikes/"},{"code":"TOP","title":"홍해서 사우디 유조선 엔셀리아(Encelia) 후티 피격 화재, 나포 봉쇄 격화","src":"Seatrade Maritime","date":"2026-07-23","kSum":"사우디 국적 정유운반선 엔셀리아(Encelia)가 얀부 출항 후 홍해에서 미확인 발사체에 피격돼 화재가 발생했다. 예멘 후티는 사우디 항만 봉쇄를 위반한 두 척의 유조선을 겨냥했다고 주장하며, 바흐리(Bahri) 소속 VLCC 라일라(Layla)도 피격했다고 밝혔다.","eSum":"The Saudi-flagged product tanker Encelia caught fire after being struck by an unknown projectile in the Red Sea following departure from Yanbu. The Houthis claimed they targeted two tankers that violated their blockade of Saudi ports, and said the Bahri VLCC Layla was also hit.","kImp":"홍해 항로 리스크가 사우디 원유 수출 동맥으로까지 확대되며 유가·해상보험에 파장을 준다.","eImp":"Red Sea risk now reaches Saudi oil export arteries, threatening crude prices and marine insurance.","url":"https://www.seatrade-maritime.com/security/saudi-tanker-on-fire-after-houthi-strike-in-red-sea"},{"code":"TOP","title":"컨테이너 현물운임 하락, 선복 증가와 수요 둔화로 2주 연속 약세","src":"gCaptain","date":"2026-07-23","kSum":"선복 공급 증가와 수요 둔화로 동서 주요 항로의 현물운임이 2주 연속 하락해 40피트 기준 4% 내린 4,374달러를 기록했다. 상하이-LA는 6% 하락한 5,878달러, 상하이-뉴욕은 4% 하락했으며 다음 주 태평양 항로에 6건의 결항이 예정돼 있다.","eSum":"Container spot rates fell for a second straight week as added capacity and softer demand pressured east-west lanes, with the benchmark down 4% to $4,374 per FEU. Shanghai-LA dropped 6% to $5,878 and Shanghai-New York fell 4%, with six blank sailings scheduled on the transpacific next week.","kImp":"정기선사 수익성과 4분기 성수기 전망에 대한 부정적 신호다.","eImp":"A bearish signal for liner profitability and the Q4 peak-season outlook.","url":"https://gcaptain.com/container-spot-rates-fall-as-capacity-growth-pressures-freight-rates/"},{"code":"TOP","title":"후티 봉쇄로 사우디 홍해 원유 수출 항로 위기, 얀부 의존도 75%","src":"Seatrade Maritime","date":"2026-07-21","kSum":"후티가 7월 20일 즉시 발효로 사우디 선박의 홍해 항행 금지를 선언하며 사우디행 화물선들이 잇달아 회항했다. 7월 상반기 사우디 원유·콘덴세이트 수출의 약 75%가 얀부를 통해 이뤄져 홍해 항로 마비의 타격이 특히 크다.","eSum":"The Houthis announced an immediate ban on Saudi maritime navigation in the Red Sea on July 20, prompting multiple Saudi-bound ships to reverse course. Around 75% of Saudi crude and condensate exports in early July moved via Yanbu, making the Red Sea route critically exposed.","kImp":"글로벌 원유 물류와 유가에 실질적 공급 차질 위험을 던진다.","eImp":"Raises the prospect of real supply disruption to global crude flows and oil prices.","url":"https://www.seatrade-maritime.com/security/houthi-embargo-puts-saudi-red-sea-oil-route-at-risk"},{"code":"TOP","title":"아시아 정유사, 아프리카 우회 위해 사우디 홍해 원유 재조정 협의","src":"gCaptain","date":"2026-07-23","kSum":"아시아 원유 구매자들이 홍해 유조선 공격 이후 아프리카 희망봉 우회를 위해 사우디 아람코와 물량 재조정을 논의 중이다. 항로 변경은 운송 시간과 비용을 크게 늘려 아시아 정유업계의 조달 구조에 부담을 준다.","eSum":"Asian crude buyers are in talks with Saudi Aramco to reroute flows around Africa after Houthi attacks on Red Sea tankers. Diverting around the Cape would sharply raise voyage times and costs, straining Asian refiners' sourcing.","kImp":"홍해 사태가 톤마일 급증과 유조선 운임 강세로 이어질 수 있음을 시사한다.","eImp":"Signals a possible surge in ton-miles and firmer tanker rates from the Red Sea crisis.","url":"https://gcaptain.com/asian-oil-buyers-in-talks-to-reroute-saudi-red-sea-flows/"},{"code":"TOP","title":"코스코(COSCO) 전용운반선, 청시조선에 6만DWT 중량물선 8척 3.86억달러 발주","src":"Seatrade Maritime","date":"2026-07-22","kSum":"코스코 전용운반선(COSCO Shipping Specialized Carriers)이 청시조선(Chengxi)에 6만DWT급 다목적 중량물선 8척을 최대 3.86억달러(26.24억위안)에 발주했다. 풍력설비 등 첨단제조 화물 운송 수요를 겨냥했으며 인도는 2029년 4월~2030년 6월 예정이다.","eSum":"COSCO Shipping Specialized Carriers approved up to $386m (CNY2.624bn) for eight 60,000-dwt multipurpose heavy-lift vessels at Chengxi Shipyard. The newbuilds target wind-power equipment and advanced-manufacturing cargo, with deliveries from April 2029 to June 2030.","kImp":"프로젝트·중량물 화물 시장의 성장 기대와 중국 조선 수주 랠리를 보여준다.","eImp":"Reflects growth bets on the project/heavy-lift segment and China's newbuilding order rally.","url":"https://www.seatrade-maritime.com/maritime-transportation/cosco-shipping-orders-eight-heavy-lift-vessels-from-chengxi-shipbuilding"},{"code":"TOP","title":"미국 롱비치항, 원자력 추진 선박 시험대로 소형모듈원자로(SMR) 검토","src":"Splash247","date":"2026-07-22","kSum":"미국 해사청(MARAD)이 롱비치항과 상선 및 항만용 소형모듈원자로(SMR) 도입을 모색하는 획기적 협약을 체결할 예정이다. 롱비치는 원자력 추진 상용선박의 미국 내 시험 무대로 부상하고 있다.","eSum":"The US Maritime Administration is set to sign a landmark agreement with the Port of Long Beach to explore small modular reactors for commercial ships and port applications. Long Beach is lining up as a US testbed for nuclear-powered shipping.","kImp":"해운 탈탄소 대안으로서 원자력 추진의 상용화 논의가 미국에서 본격화한다.","eImp":"Marks a serious US push toward nuclear propulsion as a shipping decarbonization option.","url":"https://splash247.com/long-beach-lined-up-as-us-testbed-for-nuclear-powered-shipping/"},{"code":"TOP","title":"중국 다롄(Dalian), 지역 화물 자립 노린 신설 원양해운사 다롄오션시핑 출범","src":"Splash247","date":"2026-07-22","kSum":"중국 다롄에서 CDIG 주도로 다롄오션시핑(Dalian Ocean Shipping Co)이 7월 22일 공식 출범해 '랴오닝 화물·랴오닝 선박·랴오닝 항만' 개념으로 지역 화물의 자체 통제를 추진한다. 등록자본 1.2억위안으로 심해 화물운송을 시작으로 선박투자·선박관리·물류로 확장할 계획이다.","eSum":"Dalian Ocean Shipping Co was inaugurated on July 22 under CDIG to retain more value from locally generated cargo via a 'Liaoning cargo, ships and ports' concept. Capitalized at RMB120m, it will start in deepsea transport before expanding into ship investment, management and logistics.","kImp":"중국 지방정부 주도의 해운 자립·통제 강화 흐름을 보여준다.","eImp":"Illustrates China's provincial drive to build self-controlled shipping capacity.","url":"https://splash247.com/dalian-launches-new-deepsea-shipping-platform/"},{"code":"TOP","title":"머스크(Maersk)·MSC, 산투스 신규 터미널 입찰 위해 BTP 지분 분리안 제출","src":"Splash247","date":"2026-07-22","kSum":"APM터미널스와 MSC계열 TIL이 브라질 경쟁당국에 산투스 Tecon 10 입찰을 앞두고 공동보유 BTP 터미널 구조조정안을 신고했다. 낙찰 결과에 따라 APM이 TIL 지분을 인수하거나 반대로 매각하는 방식으로, 기존 터미널 보유 선사의 입찰 자격 논란을 해소하려는 조치다.","eSum":"APM Terminals and MSC-backed TIL notified Brazil's regulator of a possible restructuring of their jointly owned BTP terminal ahead of the Tecon Santos 10 auction. Depending on the outcome, APM could buy or sell the BTP stake, aiming to resolve disputes over whether incumbent terminal owners may bid.","kImp":"세계 최대 정기선사들의 남미 터미널 지배력 경쟁 구도를 보여준다.","eImp":"Highlights the world's largest liners jockeying for terminal control in South America.","url":"https://splash247.com/maersk-and-msc-prepare-btp-split-for-santos-mega-terminal-auction/"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. 해양사고","eTitle":"Section 2. Accidents","items":[{"code":"ACC","title":"노후 벌커 '루니(Luni)' 반다르아바스 인근서 선체 절단·부분 침몰","src":"SAFETY4SEA","date":"2026-07-14","kSum":"1994년 건조된 32년 선령의 수프라막스 벌크선 루니(Luni)가 7월 14일 이란 반다르아바스 인근에서 선체 중앙부가 두 동강 나며 부분 침몰했다. 선체 중앙부가 침수되어 선수·선미만 급경사로 수면 위에 남았고 23명 전 선원은 무사히 대피했다.","eSum":"The 32-year-old supramax bulker Luni broke in two amidships and partially sank near Bandar Abbas, Iran on 14 July 2026. Her midships section flooded while bow and stern protruded at steep angles, and all 23 foreign crew were safely evacuated.","kCause":"선령 초과 노후 선체의 중앙부 손상 및 침수로 추정되며 충돌 가능성도 거론되나 정확한 원인은 조사 중.","eCause":"Suspected hull failure and water ingress in the aged midships section; a possible collision is cited but the exact cause is under investigation.","kLes":"정상 선령을 훨씬 넘긴 노후선의 구조 강도·부식 관리를 강화하고, 선체 절손 징후에 대한 조기 점검과 퇴선 준비가 필요하다.","eLes":"Structural integrity and corrosion control of vessels well past normal service life must be reinforced, with early detection of hull-girder weakness and readiness to abandon ship.","url":"https://safety4sea.com/bulk-carrier-splits-and-partially-sinks-off-bandar-abbas/"},{"code":"ACC","title":"화학제품운반선 '스톨트 마그네슘(Stolt Magnesium)' 오만 앞바다 폭발·기관실 화재","src":"SAFETY4SEA","date":"2026-07-14","kSum":"노르웨이 선사 스톨트닐센의 화학제품운반선 스톨트 마그네슘(Stolt Magnesium)이 7월 14일 오만 앞 아라비아해에서 미확인 외부 폭발물에 피격돼 기관실에서 화재가 발생했다. 사고는 현지시각 00:40경 발생했으며 전 선원은 무사히 대피해 인명피해는 없었다.","eSum":"Stolt-Nielsen's chemical tanker Stolt Magnesium was struck by what its manager called an unidentified external device in the Arabian Sea off Oman on 14 July 2026, igniting an engine-room fire. The explosion occurred around 00:40 local time and all crew were accounted for with no injuries.","kCause":"호르무즈 해협 인근 긴장 고조 속 외부 폭발 장치(미사일 또는 드론 추정)에 의한 피격으로 보이나 배후·장치 유형은 조사 중.","eCause":"Believed to be a strike by an external explosive device amid heightened Strait of Hormuz tensions; the type of device and responsible party remain under investigation.","kLes":"고위험 해역 통항 시 위협 정보 갱신, 기관실 화재 대응 훈련 및 신속 진화·격리 체계를 사전 점검해야 한다.","eLes":"Transit through high-risk waters demands updated threat intelligence and rehearsed engine-room firefighting and containment procedures.","url":"https://safety4sea.com/fire-breaks-out-on-chemical-tanker-stolt-magnesium-following-explosion-off-oman/"},{"code":"ACC","title":"ATSB 조사: 혼합화물선 '매튜 플린더스 III(Matthew Flinders III)' 배스해협서 8시간 조타 상실","src":"gCaptain","date":"2026-07-08","kSum":"44.6m 혼합화물선 매튜 플린더스 III(Matthew Flinders III)가 태즈메이니아 배스해협 항해 중 오토파일럿 러더 각도 피드백 고장으로 양현 러더가 좌현 최대타로 고착돼 조타를 상실했다. 승무원은 유압 조타장치를 분리하고 차동추력으로 해안을 피했으며 약 8시간 뒤 러더 각도 센서의 느슨한 링크암을 조여 조타를 회복했다.","eSum":"The 44.6 m mixed cargo vessel Matthew Flinders III lost steering in Bass Strait when a rudder-angle feedback failure locked both rudders hard to port. The crew disconnected the hydraulic gear and used differential thrust to stay clear of the coast, restoring control about eight hours later after tightening a loose linkage arm on the rudder-angle sensor.","kCause":"러더 각도 센서의 느슨한 링크암으로 오토파일럿 피드백이 상실됐고, 선장이 백업 토글 조타 조작에 익숙하지 않아 조기 복구에 실패한 것이 원인.","eCause":"A loose linkage arm on the rudder-angle sensor cut autopilot feedback, and the master's unfamiliarity with the backup non-follow-up (toggle) steering delayed recovery.","kLes":"백업 조타장치 사용법을 신규 승선자 교육과 SMS 절차에 명확히 포함하고 정기 훈련으로 숙달해야 한다.","eLes":"Use of backup steering must be clearly covered in induction training and the SMS, and drilled regularly so bridge teams can engage it under stress.","url":"https://gcaptain.com/atsb-crew-training-gaps-left-cargo-ship-without-steering-in-bass-strait/"},{"code":"ACC","title":"세계 최고령 여객선 '유노(Juno)' 트로사 군도서 좌초","src":"NT (Norrköpings Tidningar)","date":"2026-07-15","kSum":"1874년 건조된 세계 최고령 숙박 여객선 유노(Juno)가 7월 15일 19:25경 쇠데텔리에에서 예테보리로 항해 중 스웨덴 트로사 군도 보쾨 인근에서 좌초했다. 선원 11명과 승객 46명이 승선해 있었으나 부상자는 없었고 이후 전원 육상으로 대피했다.","eSum":"Juno, built in 1874 and the world's oldest overnight passenger ship, ran aground near Bokö in Sweden's Trosa archipelago at about 19:25 on 15 July 2026 while sailing from Sodertalje to Gothenburg. The 11 crew and 46 passengers were unhurt and later evacuated ashore.","kCause":"협수로 항해 중 좌초로, 항로 이탈 또는 견시·조선 오류 가능성이 있으나 정확한 원인은 조사 중.","eCause":"Grounding while navigating a narrow archipelago channel; possible track deviation or navigational error, but the exact cause is under investigation.","kLes":"좁고 얕은 군도 수로에서는 정밀 항로 계획, 조위 여유 확인, 견시 강화가 필수이며 노후 여객선의 신속 대피 절차도 점검해야 한다.","eLes":"Narrow, shallow archipelago channels require precise passage planning, tidal-clearance checks and enhanced lookout, plus rehearsed evacuation for aging passenger ships.","url":"https://www.nt.se/nyheter/trosa/artikel/passagerarfartyget-juno-pa-grund-i-trosa-skargard/r35z2z8j"},{"code":"ACC","title":"벌크선 '아로사(Arosa)' 초르노모르스크 항서 드론 피격 화재·3명 사망","src":"Kyiv Post","date":"2026-07-13","kSum":"벌크선 아로사(Arosa)가 7월 13일 우크라이나 초르노모르스크 항에서 광물비료를 하역하던 중 러시아 드론에 상부구조가 피격돼 화재가 발생했다. 이 공격으로 선원 3명이 사망하고 5명이 부상해 병원으로 이송됐다.","eSum":"The bulk carrier Arosa was struck in her superstructure by a Russian drone while discharging mineral fertilizer at the port of Chornomorsk, Ukraine on 13 July 2026, sparking a fire. Three crew members were killed and five others injured and taken to hospital.","kCause":"정박·하역 중 민간 상선에 대한 군사 드론 공격이 직접 원인.","eCause":"Direct military drone strike on a civilian merchant ship during berthing/cargo operations.","kLes":"분쟁 해역 항만 정박 시 위협 경보 체계, 대피·소화 대비, 선원 보호구역 확보 등 전시 리스크 관리가 필요하다.","eLes":"Ports in conflict zones require threat-alert systems, ready evacuation and firefighting, and protected crew muster arrangements as part of wartime risk management.","url":"https://www.kyivpost.com/post/78672"},{"code":"ACC","title":"화물선 '아틀라스 베이(Atlas Bey)' 오데사 인근 드론 피격 화재·선장 사망","src":"SAFETY4SEA","date":"2026-07-14","kSum":"식물성 기름을 싣고 초르노모르스크에서 튀르키예로 향하던 화물선 아틀라스 베이(Atlas Bey)가 7월 14일 오데사 인근에서 출항 직후 드론에 피격돼 화재가 발생했다. 이 공격으로 아제르바이잔 국적 선장이 사망하고 2명이 부상했으며 나머지 선원은 오데사로 이송됐다.","eSum":"The cargo ship Atlas Bey, carrying vegetable oil from Chornomorsk to Turkey, was struck by a drone off Odesa shortly after departure on 14 July 2026 and caught fire. Her Azerbaijani captain was killed and two crew injured, while the remaining crew were brought ashore at Odesa.","kCause":"흑해 상선 항로에 대한 드론 공격이 직접 원인으로, 배후는 조사 중.","eCause":"Direct drone attack on a commercial vessel on a Black Sea trade route; responsibility under investigation.","kLes":"흑해 곡물·식용유 항로의 상선 취약성을 재확인시키며, 출입항 시점의 위협 노출을 줄이는 항로·시간 조정과 방어 대책이 요구된다.","eLes":"Reaffirms the vulnerability of merchant traffic on Black Sea grain/oil routes, calling for route and timing adjustments and protective measures to reduce exposure during port transits.","url":"https://safety4sea.com/drone-strike-in-the-black-sea-leaves-one-seafarer-dead-and-two-injured/"},{"code":"ACC","title":"美 해사청 예비선박 '찰스 L. 길리랜드' 볼티모어항서 구명정 화재","src":"USNI News","date":"2026-07-14","kSum":"미국 해사청(MARAD)의 예비 선박 찰스 L. 길리랜드(Charles L. Gilliland) 선상 구명정 2척에서 7월 13일 볼티모어항 정박 중 화재가 발생했다. 볼티모어시 소방국이 오전 11시경 출동해 2경보(2-alarm) 화재로 대응했으며 인명피해는 없었다.","eSum":"Two lifeboats aboard the U.S. Maritime Administration reserve ship Charles L. Gilliland caught fire while berthed in the Port of Baltimore on 13 July 2026. Baltimore City Fire Department responded around 11 a.m. to the two-alarm fire, with no injuries reported.","kCause":"정박 중 구명정에서 발생한 화재로 발화 원인은 조사 중.","eCause":"Fire originating in lifeboats while alongside; ignition source under investigation.","kLes":"계선·예비 상태 선박의 구명설비 유지·정비, 배터리·유압장치 등 발화원 관리와 항만 정박 중 화재 감시 체계가 필요하다.","eLes":"Laid-up and reserve ships need ongoing maintenance of lifesaving appliances, control of ignition sources such as batteries and hydraulics, and fire watch while alongside.","url":"https://news.usni.org/2026/07/14/marad-ship-suffers-fire-in-baltimore"},{"code":"ACC","title":"어선 '허슬러(F/V Hustler)' 워싱턴 오션쇼어스 앞바다서 침몰","src":"The Daily Astorian","date":"2026-07-09","kSum":"48피트 어선 허슬러(F/V Hustler)가 7월 9일 미국 워싱턴주 오션쇼어스 서쪽 약 4마일 해상에서 침몰했다. 선원 2명은 침수 방수복(이머전 슈트)을 착용하고 구명뗏목을 전개해 미 해안경비대 구명정에 의해 구조됐다.","eSum":"The 48-foot fishing vessel Hustler sank about four miles west of Ocean Shores, Washington on 9 July 2026. Her two crew donned immersion suits and deployed a life raft before she went down and were rescued by a U.S. Coast Guard motor lifeboat crew.","kCause":"선체 침수로 침몰한 것으로 보이며 정확한 침수 원인은 조사 중.","eCause":"Vessel sank after taking on water; the source of flooding is under investigation.","kLes":"소형 어선의 이머전 슈트·구명뗏목 상시 비치와 신속한 조난 신호가 생존을 좌우함을 보여준다.","eLes":"Demonstrates that readily available immersion suits and life rafts, plus prompt distress alerting, are decisive for survival aboard small fishing vessels.","url":"https://dailyastorian.com/2026/07/12/fishing-vessel-sank-crew-rescued/"},{"code":"ACC","title":"터키 소유 벌크선, 오데사 인근서 러시아 드론 피격·다수 사망","src":"The Maritime Executive","date":"2026-07-20","kSum":"터키 소유 벌크선이 7월 20일 우크라이나 오데사 인근 해상에서 러시아 드론 공격을 받아 다수의 선원이 사망했다. 이는 러시아가 흑해 상선과 항만 인프라를 겨냥한 일련의 공격이 이어지는 가운데 발생한 사고다.","eSum":"A Turkish-owned bulk carrier was struck by a Russian drone attack off Odesa, Ukraine on 20 July 2026, killing multiple crew members. The strike came amid an intensifying series of Russian attacks on Black Sea merchant shipping and port infrastructure.","kCause":"흑해 상선·항만을 겨냥한 반복적 드론 공격이 직접 원인.","eCause":"Direct drone strike in a sustained campaign against Black Sea merchant shipping and ports.","kLes":"흑해 항로의 상선 위험이 지속 고조되고 있어 선원 보호, 항만 정박 리스크 평가, 전쟁위험 보험·회항 대책 등 종합 대응이 필요하다.","eLes":"Escalating risk to Black Sea shipping demands comprehensive measures: crew protection, port-call risk assessment, and war-risk insurance and rerouting contingencies.","url":"https://maritime-executive.com/article/multiple-crewmembers-killed-in-russian-strike-on-turkish-bulker"}]},{"code":"PSC","type":"news","kTitle":"Section 3. 항만국통제","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"RiSK4SEA, 2026년 7월판 PSC 우수 성과자 리스트 공개","src":"SAFETY4SEA","date":"2026-07-16","kSum":"RiSK4SEA가 원양 선대 16개 세그먼트를 대상으로 한 2026년 7월판 Top PSC Performers 리스트(제8판)를 발표했다. 2023년 7월 1일부터 2026년 6월 30일까지 전 세계 20만3천여 건의 항만국통제(PSC) 검사 데이터를 기반으로 산정됐다.","eSum":"RiSK4SEA has released its July 2026 edition (8th) of the Top PSC Performers List covering 16 segments of the ocean-going fleet. It draws on more than 203,000 PSC inspections worldwide over the 36-month period from 1 July 2023 to 30 June 2026.","kImp":"선박관리사의 PSC 성과를 동종 그룹과 비교해 투명하게 순위화하는 지표로, 우수 성과가 일관성에서 나온다는 점을 재확인시켜 준다. 규모가 작은 관리사도 강한 성과를 인정받을 수 있는 벤치마크로 활용된다.","eImp":"It provides a transparent, peer-benchmarked ranking of ship managers' PSC performance, reinforcing that strong results come from consistency rather than isolated inspections. Smaller managers gain visibility for strong performance that larger players might otherwise overshadow.","url":"https://safety4sea.com/cm-risk4sea-top-psc-performers-list-july-edition-now-available/"},{"code":"PSC","title":"ABS, 수동식 구조정 대빗의 PSC 결함 위험 경고","src":"SAFETY4SEA","date":"2026-07-13","kSum":"ABS는 최근 유럽 항만의 PSC 검사에서 한 컨테이너선이 구조정 진수장치 관련 결함코드 11113을 받은 사례를 소개했다. 수동식 구조정 대빗의 정비·작동 상태가 검사관의 주요 지적 대상이 되고 있다.","eSum":"ABS highlighted a case in which a container ship received deficiency Code 11113 (launching arrangements for rescue boats) during a recent PSC inspection at a European port. Manual rescue boat davits and their maintenance and operation are drawing PSCO scrutiny.","kImp":"구명설비 진수장치 결함은 억류로 이어질 수 있는 고위험 항목으로, 선사는 대빗 정비 이력과 작동 시험 기록을 상시 확인해야 한다. 승무원 훈련과 문서화가 미흡하면 통상 통과할 검사에서도 지적을 받을 수 있다.","eImp":"Life-saving launching-arrangement deficiencies are a high-risk item that can lead to detention, so operators must keep davit maintenance records and operational tests up to date. Gaps in crew drills or documentation can turn a routine inspection into a deficiency.","url":"https://safety4sea.com/abs-manual-rescue-boat-davits-raise-psc-compliance-concerns/"},{"code":"PSC","title":"화물 고박에 초점, 2026년 PSC 집중점검(CIC) 준비 안내","src":"SAFETY4SEA","date":"2026-07-09","kSum":"파리 및 도쿄 MoU는 2026년 9월 1일부터 11월 30일까지 화물 고박을 주제로 한 공동 집중점검캠페인(CIC)을 실시한다. 검사관은 통상 검사와 함께 전용 질문지를 적용해 선박별 화물고박매뉴얼(CSM) 승인·이행 상태를 점검한다.","eSum":"The Paris and Tokyo MoUs will run a joint Concentrated Inspection Campaign on cargo securing from 1 September to 30 November 2026. PSCOs will apply a dedicated questionnaire alongside routine inspections, checking each vessel's approved Cargo Securing Manual (CSM) and its practical implementation.","kImp":"CIC 기간에는 유럽·아태 항만에 기항하는 모든 선박이 대상이 되어 평소 통과하던 선박도 고박 서류·장비 미비 시 결함이나 억류를 받을 수 있다. 라싱 장비 상태와 승무원의 고박 절차 이해도가 핵심 점검 포인트다.","eImp":"During the campaign every vessel calling at European or Asia-Pacific ports is in scope, so ships that would normally pass can pick up deficiencies or detention if cargo-securing documentation or gear is deficient. Lashing gear condition and crew understanding of securing procedures are key checkpoints.","url":"https://safety4sea.com/cargo-securing-in-focus-preparing-for-the-2026-psc-cic/"},{"code":"PSC","title":"미국 해안경비대(USCG), 2025년 PSC 연차보고서 발표","src":"MaritimeCyprus","date":"2026-06-08","kSum":"USCG가 2025년 항만국통제 연차보고서를 공개했으며, 연간 억류율이 0.94%에서 0.85%로 하락하고 3년 이동 억류비율도 1.01%에서 1.00%로 낮아졌다. 바하마·코모로·쿠라사오·이탈리아·라트비아가 표적 기국 리스트에서 제외됐다.","eSum":"The USCG released its 2025 Port State Control annual report, showing the annual detention rate fell from 0.94% to 0.85% and the three-year rolling detention ratio dropped from 1.01% to 1.00%. The Bahamas, Comoros, Curacao, Italy and Latvia were removed from the targeted flag list.","kImp":"미국 항만에 기항하는 선박의 기국·선급 성과가 표적 검사 여부를 좌우하므로, 억류율 개선은 검사 부담 완화로 이어질 수 있다. 억류 이의신청 17건 중 2건만 인용된 점은 결함 관리의 선제 대응이 중요함을 보여준다.","eImp":"Flag and RO performance drives whether ships calling at U.S. ports face targeted exams, so improving detention rates can ease inspection burden. With only two of seventeen appeals granted, the report underscores the importance of proactive deficiency management.","url":"https://maritimecyprus.com/2026/06/08/uscg-releases-their-2025-port-state-control-annual-report/"},{"code":"PSC","title":"도쿄 MoU, 2025년 항만국통제 연차보고서 공개","src":"MaritimeCyprus","date":"2026-05-10","kSum":"도쿄 MoU가 2025년 아시아·태평양 지역 항만국통제 연차보고서를 발표했다. 2025년 35,546건의 검사(개별 선박 19,980척)가 수행됐으며, 73개 기국 1,255척이 억류돼 검사 대비 억류율은 3.53%를 기록했다.","eSum":"The Tokyo MoU published its 2025 annual report on port State control in the Asia-Pacific region. It carried out a record 35,546 inspections involving 19,980 individual ships, and 1,255 ships under 73 flags were detained, giving a detention rate of 3.53%.","kImp":"아태 지역 억류율은 감소 추세를 이어갔으나 팬데믹 이전 수준에는 아직 도달하지 못해 검사 강도는 여전히 높다. 지역 검사율이 약 66%에 이르는 만큼 이 지역 기항 선박은 지속적인 결함 관리가 요구된다.","eImp":"Regional detention rates continued a downward trend but have not yet returned to pre-pandemic levels, so inspection intensity remains high. With the region's inspection rate at about 66%, ships trading in Asia-Pacific must maintain continuous deficiency management.","url":"https://maritimecyprus.com/2026/05/10/tokyo-mou-releases-their-psc-annual-report-for-2025/"},{"code":"PSC","title":"호주 AMSA, 임금체불·식수요금 부과로 벌크선 FPMC B Forever 입항금지","src":"gCaptain","date":"2026-05-07","kSum":"AMSA는 4월 23일 뉴캐슬항 PSC 검사에서 라이베리아 선적 벌크선 FPMC B Forever의 선원 약 1만5천 호주달러 임금체불과 불법 식수요금 부과 등 MLC 위반을 적발해 억류했다. 이 선박은 7월 28일까지 호주 항만·해역 입항이 금지됐으며, 이는 2개월도 안 되는 기간에 나온 세 번째 입항금지 조치다.","eSum":"AMSA detained the Liberia-flagged bulk carrier FPMC B Forever after an April 23 PSC inspection at Newcastle found crew underpaid by nearly AUD 15,000 and unlawfully charged for potable water, breaching the MLC. The vessel is banned from Australian ports and waters until 28 July 2026, AMSA's third such ban in under two months.","kImp":"호주가 선원 복지·임금 위반에 대해 억류에 이어 즉시 입항금지까지 부과하는 강경 노선을 보여주는 사례다. 노동조건 미준수가 상업적 지연·평판 손상·검사 강화로 직결될 수 있음을 선사에 경고한다.","eImp":"The case shows Australia's escalating hard line, pairing detention with an immediate port ban for seafarer welfare and wage violations. It warns operators that labour non-compliance can translate directly into commercial delays, reputational damage and heightened inspection scrutiny.","url":"https://gcaptain.com/australia-bans-liberian-flagged-bulker-from-ports-amid-crackdown-on-crew-exploitation/"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. 자동차운반선","eTitle":"Section 4. PCTC / Car Carriers","items":[{"code":"PCTC","title":"회그 오토라이너스(Höegh Autoliners), 아시아 완성차업체와 3억 달러 규모 수송계약 연장","src":"Splash247","date":"2026-07-10","kSum":"오슬로 상장 자동차운반선사 회그 오토라이너스가 주요 아시아 완성차 제조사와의 기존 계약을 2029년 12월까지 연장하며 약 3억 달러의 추가 매출을 확보했다. 이번 계약은 물량 확대와 시장 요율을 반영한 상향된 상업 조건을 포함하며 중국 남부 샤오모(Xiaomo)항이 서비스에 추가됐다.","eSum":"Oslo-listed car carrier operator Höegh Autoliners extended an existing contract with a major Asian carmaker until December 2029, adding about $300m in revenue. The deal includes higher committed volumes and updated commercial terms in line with market rates, and adds Xiaomo port in southern China to its Asia offering.","kImp":"선복이 타이트한 가운데 주요 화주와의 장기계약 백로그를 늘려 수익 가시성을 강화하는 업계 흐름을 잘 보여준다.","eImp":"It illustrates carriers locking in long-term volume cover from major carmakers to boost earnings visibility while fleet supply stays tight.","url":"https://splash247.com/hoegh-autoliners-adds-300m-to-asian-carmaker-deal/"},{"code":"PCTC","title":"중국 수출 급증에 자동차운반선 부족…올해 200만 대 컨테이너선으로 운송 전망","src":"Splash247","date":"2026-07-21","kSum":"베슨 노티컬(Veson Nautical)에 따르면 올해 약 200만 대의 차량이 전용 자동차운반선이 아닌 주로 컨테이너선으로 운송될 전망으로, 지난해 100만 대에서 두 배로 늘어난다. 중국의 차량 수출이 로로(ro-ro) 선복 증가 속도를 앞지르며 컨테이너선 활용이 '구조적 현상'으로 자리잡고 있다.","eSum":"According to Veson Nautical, around 2m vehicles will move on non-dedicated tonnage, mainly containerships, this year, double last year's 1m. China's vehicle exports are outpacing ro-ro capacity growth, turning container use into a structural feature of the trade.","kImp":"PCTC 선복 증가율이 7.6%에 그쳐 수요를 못 따라가면서 컨테이너선이 자동차 물류의 상시 대체수단으로 부상하고 있음을 보여준다.","eImp":"With PCTC fleet growth at just 7.6%, the mismatch is turning containerships into a permanent overflow channel for automotive logistics.","url":"https://splash247.com/record-2m-cars-tipped-to-move-in-containers-as-china-outgrows-car-carrier-fleet/"},{"code":"PCTC","title":"차량운반선 용선료 급등…표준 PCTC 1년 정기용선 일당 5만2,200달러 (Veson)","src":"Hellenic Shipping News","date":"2026-07-09","kSum":"베슨 노티컬 분석에 따르면 2분기 표준 PCTC의 1년 정기용선료는 일당 5만2,200달러로 전분기 대비 14.1% 상승했고, 중형 PCTC는 3만5,700달러로 29.2% 급등했다. 중국 차량 수출이 1~5월 전년比 63% 증가하고 희망봉 우회로 아시아-유럽 항로가 약 25% 길어지면서 CEU-마일 수요가 높게 유지되고 있다.","eSum":"Per Veson Nautical, one-year TC rates for standard PCTCs averaged $52,200/day in Q2, up 14.1% QoQ, with midsize PCTCs at $35,700/day, up 29.2%. Chinese vehicle exports rose 63% YoY in Jan-May and Cape of Good Hope diversions stretch Asia-Europe voyages ~25%, keeping CEU-mile demand elevated.","kImp":"용선료·중고선가가 모두 강세인 가운데 2028년 수에즈 정상화 시 선복 과잉으로 요율이 조정될 수 있다는 전환점 리스크를 제시한다.","eImp":"Rates and secondhand values are firm, but the outlook flags 2028 as an inflection point when a return to Suez transits could unwind the tight balance.","url":"https://www.hellenicshippingnews.com/shipping-market-outlook-q3-2026/"},{"code":"PCTC","title":"중국 PCTC 인도 러시, 월 100만 대 수출과 맞물려…'글로비스 리더' 등 대형선 잇단 준공","src":"Xinde Marine News","date":"2026-07-14","kSum":"중국 조선소들이 대형·친환경 차량운반선을 대거 인도하는 가운데 6월 중국 차량 수출이 사상 처음 월 100만 대(103.78만 대, +75.1%)를 돌파했다. 6월 29일 광저우조선(GSI)이 1만800CEU LNG 이중연료 PCTC를 인도했고, 4월엔 HMM용·현대글로비스 운영 세계 최대 PCTC '글로비스 리더(Glovis Leader)'가 인도됐다.","eSum":"Chinese yards are delivering a wave of large, greener car carriers just as June vehicle exports topped 1m units (1.0378m, +75.1%) for the first time. GSI delivered a 10,800-ceu LNG dual-fuel PCTC on June 29, following the April delivery of Glovis Leader, the world's largest PCTC, for HMM and operated by Hyundai Glovis.","kImp":"인도 물량이 급증하지만 화물 기반도 빠르게 커지고 있어 경쟁의 초점이 '선박 보유'에서 '선복 채우기·물류망 효율'로 이동하고 있다.","eImp":"Deliveries are surging but the cargo base is expanding even faster, shifting competition from owning ships to filling them and running efficient logistics networks.","url":"https://www.xindemarinenews.com/news/2076938362079682561"},{"code":"PCTC","title":"2026년 PCTC 신조 발주 37척으로 반등…신조 활동 재점화","src":"Xinde Marine News","date":"2026-07-17","kSum":"2025년 신중했던 발주 흐름이 반전되며 2026년 들어 PCTC 신조 발주가 37척으로 급증했다. 강한 중국 차량 수출과 타이트한 선복을 배경으로 선주들이 다시 신조 시장에 적극 복귀하고 있다.","eSum":"Reversing a cautious 2025, PCTC newbuilding orders have rebounded to 37 vessels in 2026. Owners are returning to the newbuilding market amid strong Chinese vehicle exports and tight tonnage.","kImp":"신조 발주 재점화는 향후 선복 공급 확대와 2028년 이후 수급 균형 변화 가능성을 시사한다.","eImp":"The renewed ordering signals more capacity ahead and potential shifts in the supply-demand balance from 2028.","url":"https://www.xindemarinenews.com/news/2078046419924848641"},{"code":"PCTC","title":"살라움 라인(Sallaum Lines), 7,400CEU LNG 이중연료 PCTC 2척 동시 인도","src":"MarineLink","date":"2026-06-08","kSum":"살라움 라인이 중국 초상국진링조선(China Merchants Jinling)에서 건조한 7,400CEU LNG 이중연료 PCTC 'MV 오션 익스프레스'와 'MV 오션 내비게이터'를 같은 날 인도받았다. 두 선박은 오션클래스 함대 확장의 최대 단일 이정표로, 인도 즉시 상업 운항에 투입됐다.","eSum":"Sallaum Lines took delivery of two 7,400-ceu LNG dual-fuel PCTCs, MV Ocean Express and MV Ocean Navigator, built by China Merchants Jinling, on the same day. The pair, the largest single-day milestone of its Ocean Class expansion, entered commercial service immediately.","kImp":"살라움은 그간의 선복 부족을 해소하고 2027년 전용 중국-유럽 서비스 개설을 준비하며 극동-유럽 항로 확대에 나서고 있다.","eImp":"The additions ease capacity constraints and support Sallaum's push on the Far East-Europe corridor ahead of a dedicated China-Europe service in 2027.","url":"https://www.marinelink.com/news/sallaum-takes-delivery-lng-dualfueled-car-540038"},{"code":"PCTC","title":"2000년 건조 4,310CEU PCTC '창성훙(Chang Sheng Hong)', 경매서 4,200만 달러 낙찰","src":"Splash247","date":"2026-07-22","kSum":"2000년 크로아티아 울랴니크 조선소에서 건조된 26년 된 중형 PCTC '창성훙'(4,310CEU)이 화요일 경매에서 약 4,200만 달러에 낙찰됐다. 상하이연합자산거래소의 예정가 9,500만 위안(1,400만 달러)의 약 3배에 달하는 이례적 고가다.","eSum":"The 26-year-old midsize PCTC Chang Sheng Hong (4,310 ceu), built in 2000 at Croatia's Uljanik, sold at auction on Tuesday for around $42m. That is roughly three times the Shanghai United Assets and Equity Exchange's RMB95m ($14m) reserve, an exceptionally high price.","kImp":"노후 중형선까지 초고가에 팔릴 만큼 타이트한 시장을 방증하며, 자동차운반선 자산가치 강세를 뚜렷이 보여준다.","eImp":"Even an aged midsize vessel fetching such a premium underscores how tight the market is and how firm car-carrier asset values have become.","url":"https://splash247.com/2000-built-car-carrier-fetches-42m-at-auction/"},{"code":"PCTC","title":"발레니우스 빌헬름센(Wallenius Wilhelmsen), 유럽 완성차업체와 4억2,000만 달러 계약 조기 연장","src":"Baird Maritime","date":"2026-06-24","kSum":"발레니우스 빌헬름센이 익명의 유럽 완성차 제조사와 2028년 중반~2031년 중반 3년간의 계약을 조기 연장했으며 추정 가치는 약 4억2,000만 달러다. 기존 계약 잔여분 약 1억8,000만 달러에 더해지며 향후 5년간 수익 가시성을 제공한다.","eSum":"Wallenius Wilhelmsen agreed an early three-year extension with an unnamed European carmaker running mid-2028 to mid-2031, valued at about $420m. It adds to roughly $180m in remaining contract value and provides earnings visibility for the next five years.","kImp":"회그의 3억 달러 계약에 이어 대형 선사들이 지속가능한 요율 수준에서 장기 물량을 선점하는 흐름을 재확인시킨다.","eImp":"Following Höegh's $300m deal, it confirms major operators locking in long-term volumes at sustainable rate levels.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/wallenius-wilhelmsen-extends-shipping-contract-with-european-automotive-manufacturer"}]},{"code":"WW","type":"news","kTitle":"Section 5. 발레니우스 빌헬름센","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"발레니우스 빌헬름센, 2026년 1분기 순이익 1억7,700만 달러로 안정적 실적 발표","src":"AJOT","date":"2026-05-07","kSum":"발레니우스 빌헬름센은 2026년 1분기 조정 EBITDA 3억8,900만 달러, 순이익 1억7,700만 달러(주당 0.40달러)를 기록했다. 총매출은 12억5,300만 달러로 전분기 대비 1% 감소했으며, 계절적으로 낮은 해운 매출을 물류 매출 증가가 일부 상쇄했다.","eSum":"Wallenius Wilhelmsen reported Q1 2026 adjusted EBITDA of USD 389m and net profit of USD 177m (EPS USD 0.40). Total revenue of USD 1,253m was down 1% QoQ as seasonally lower shipping revenue was partly offset by higher logistics revenue.","kImp":"세계 최대 자동차운반선(PCTC) 선사의 분기 실적은 글로벌 자동차·중장비 물동량과 운임 흐름을 보여주는 핵심 지표다. 견조한 아시아 수요에도 연료비·용선비 상승이 마진을 압박하는 구도가 확인됐다.","eImp":"The quarterly results of the world's largest car-carrier operator are a key barometer of global auto and high-and-heavy volumes and freight rates. They confirmed robust Asian demand but margin pressure from rising fuel and charter costs.","url":"https://www.ajot.com/news/wallenius-wilhelmsen-delivers-stable-q1-performance-in-uncertain-markets"},{"code":"WW","title":"발레니우스 빌헬름센, 중동發 연료비 급등에 2026년 EBITDA 전망 16억 달러로 하향","src":"TipRanks","date":"2026-05-07","kSum":"회사는 지정학적 긴장에 따른 벙커유 가격 급등과 용선비 증가를 이유로 2026년 조정 EBITDA 전망을 기존 16.5억~17.5억 달러에서 약 16억 달러로 낮췄다. 중동 분쟁발 연료비 상승은 벙커조정 조항의 분기 시차로 인해 2분기에 본격 반영될 전망이다.","eSum":"The company trimmed its full-year 2026 adjusted EBITDA guidance to about USD 1.6bn from USD 1.65-1.75bn, citing higher bunker and capacity costs from geopolitical tensions. The Middle East-driven fuel cost surge will fully materialise in Q2 due to the quarterly lag in bunker adjustment clauses.","kImp":"가이던스 하향은 홍해·중동 리스크가 PCTC 선사 수익성에 미치는 직접적 타격을 보여준다. 벙커조정 조항의 시차 구조상 원가 회수까지 시간이 걸려 단기 마진 변동성이 커진다.","eImp":"The downgrade illustrates the direct hit that Red Sea and Middle East risks inflict on car-carrier profitability. The lag in bunker adjustment clauses delays cost recovery, raising near-term margin volatility.","url":"https://www.tipranks.com/news/company-announcements/wallenius-wilhelmsen-trims-2026-ebitda-outlook-as-geopolitics-drive-costs-higher"},{"code":"WW","title":"발레니우스 빌헬름센, 첫 셰이퍼(Shaper) 클래스 메탄올 이중연료선 '아틱 턴' 인도","src":"The Maritime Executive","date":"2026-07-09","kSum":"발레니우스 빌헬름센은 7월 9일 중국 진링조선소에서 셰이퍼 클래스 1번선 '아틱 턴'(9,300 CEU, 메탄올 이중연료)을 인도받았다. 이 선박은 EUKOR를 통해 아시아-유럽 항로에 곧바로 투입된다.","eSum":"Wallenius Wilhelmsen took delivery of Arctic Tern, the first Shaper Class dual-fuel methanol car carrier (9,300 CEU), on 9 July at China Merchants Jinling Shipyard. The vessel enters the Asia-Europe trade almost immediately, deployed via EUKOR.","kImp":"셰이퍼 클래스는 2027년 넷제로 엔드투엔드 서비스 목표의 핵심 축으로, 회사 선대 현대화와 탈탄소 전환의 상징적 이정표다. 공기윤활·배터리·태양광·육상전원 등 에너지효율 기술이 집약됐다.","eImp":"The Shaper Class is central to the company's 2027 net-zero end-to-end ambition and a landmark in its fleet renewal and decarbonisation. It packs efficiency tech including air lubrication, batteries, solar panels and shore power.","url":"https://maritime-executive.com/article/wallenius-wilhelmsen-takes-delivery-of-large-methanol-fueled-car-carrier"},{"code":"WW","title":"EUKOR·SIPG·월드퓨얼, 상하이항서 셰이퍼 클래스 '아틱 턴' 첫 그린메탄올 벙커링 완료","src":"Hellenic Shipping News","date":"2026-07-21","kSum":"EUKOR, SIPG 에너지, 월드퓨얼은 상하이항에서 '아틱 턴'에 약 2,800MT의 그린메탄올을 STS 방식으로 공급하며 첫 벙커링을 완료했다. 공급된 그린메탄올은 도시고형폐기물로 생산돼 ISCC-EU 인증을 받았으며 탄소집약도가 25 gCO2e/MJ 미만이다.","eSum":"EUKOR, SIPG Energy and World Fuel completed the first green methanol bunkering of Arctic Tern at the Port of Shanghai, delivering about 2,800 MT via ship-to-ship transfer. The ISCC-EU certified green methanol was produced from municipal solid waste with a carbon intensity below 25 gCO2e/MJ.","kImp":"상하이산 그린메탄올을 국제 PCTC 선사에 공급한 첫 사례로, 자동차운반선의 실제 저탄소 연료 공급망 구축 가능성을 입증했다. 메탄올 벙커링 인프라 확산의 신호탄이다.","eImp":"It marked the first bunkering at Shanghai of locally produced green methanol for an international PCTC operator, proving a viable low-carbon fuel supply chain for car carriers. It signals the spread of methanol bunkering infrastructure.","url":"https://www.hellenicshippingnews.com/eukor-sipg-energy-and-world-fuel-complete-first-green-methanol-bunkering-of-new-shaper-class-car-carrier-at-port-of-shanghai/"},{"code":"WW","title":"발레니우스 빌헬름센, 2025년 연차보고서 발간…'견조한 실적, 강화된 입지'","src":"Wallenius Wilhelmsen","date":"2026-03-19","kSum":"발레니우스 빌헬름센은 2025년 연차보고서를 발간하며 조정 EBITDA 18억1,100만 달러, 총매출 52억4,000만 달러, 순이익 11억400만 달러를 기록해 사이클 목표를 상회했다고 밝혔다. 2025년 주당 총 2.11달러(총 8억9,200만 달러)의 배당을 선언했다.","eSum":"Wallenius Wilhelmsen released its 2025 annual report, posting adjusted EBITDA of USD 1,811m, total revenue of USD 5,240m and net profit of USD 1,104m, exceeding its over-the-cycle targets. It declared a total 2025 dividend of USD 2.11 per share, worth USD 892m.","kImp":"연차보고서는 회사가 자동차 물류 통합 사업자로서의 수익성과 강한 주주환원 기조를 유지하고 있음을 확인시킨다. 넷제로 로드맵과 재무 건전성을 동시에 보여주는 핵심 문서다.","eImp":"The annual report confirms the company's sustained profitability as an integrated auto-logistics player and strong shareholder returns. It is a key document tying together its net-zero roadmap and financial strength.","url":"https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-2025-annual-report-steady-delivery-stronger-position"},{"code":"WW","title":"발레니우스 빌헬름센, 스칸디나비아 최대 예테보리 차량터미널 운영 개시","src":"Project Cargo Journal","date":"2026-02-02","kSum":"발레니우스 빌헬름센은 2월부터 스웨덴 최대 차량항인 예테보리항의 완성차 터미널 운영을 12년 컨세션으로 인수해 개시했다. 회사는 터미널 부지·건물·인프라 현대화에 약 610만 유로를 투자하기로 약속했다.","eSum":"Wallenius Wilhelmsen began operating the finished-vehicle terminal at the Port of Gothenburg, Sweden's largest vehicle port, under a 12-year concession from February. It committed to invest about EUR 6.1m to modernise terminal areas, buildings and infrastructure.","kImp":"해상운송에 이어 터미널 운영까지 확장하며 통합 공급망 파트너로서의 전략을 강화하는 행보다. 스칸디나비아 자동차 물류 허브 지배력을 높인다.","eImp":"The move extends the company from ocean transport into terminal operations, reinforcing its integrated supply-chain strategy. It deepens its grip on the Scandinavian vehicle-logistics hub.","url":"https://www.projectcargojournal.com/ports-and-terminals/2026/02/02/wallenius-wilhelmsen-begins-operations-at-gothenburg-roro-terminal/"},{"code":"WW","title":"발레니우스 빌헬름센, 유럽 완성차 업체와 약 4.2억 달러 규모 운송계약 조기 연장","src":"Splash247","date":"2026-06-24","kSum":"발레니우스 빌헬름센은 주요 유럽 완성차 업체와의 운송계약을 3년 조기 연장하며 약 4.2억 달러의 미래 매출을 확보했다. 연장 계약은 2028년 중반부터 2031년 중반까지 적용되며 저탄소 연료 사용도 포함한다.","eSum":"Wallenius Wilhelmsen extended a shipping contract with a major European carmaker in a deal worth around USD 420m, running from mid-2028 to mid-2031. The early extension includes the use of low-emission fuels as part of joint CO2-reduction efforts.","kImp":"장기 계약의 조기 확보는 향후 5년간 지속가능한 운임 수준의 물동량 커버리지를 제공한다. 자동차운반선 시장의 견조한 수요와 계약 파이프라인의 안정성을 보여준다.","eImp":"Locking in long-term cover early provides sustainable-rate volume coverage for the next five years. It underscores robust car-carrier demand and the stability of the contract pipeline.","url":"https://splash247.com/wallenius-wilhelmsen-adds-420m-to-car-shipping-contract/"},{"code":"WW","title":"발레니우스 빌헬름센, 아시아 완성차·중장비 제조사와 1.3억 달러 신규 계약","src":"Splash247","date":"2026-01-07","kSum":"발레니우스 빌헬름센은 아시아 주요 완성차·중장비 제조사와 2026년 개시하는 1년 해상운송 계약을 체결했으며, 물량 기준 추정가치는 약 1.3억 달러다. 회사는 이번 계약이 아시아 시장 확대 전략에 부합한다고 밝혔다.","eSum":"Wallenius Wilhelmsen signed a one-year ocean shipping contract commencing 2026 with a major Asian vehicle and heavy-equipment manufacturer, valued at an estimated USD 130m on agreed volumes. The company said the deal aligns with its ambition to expand its presence in Asia.","kImp":"이미 물류 부문에서 관계를 맺은 고객과의 해상운송 계약 확대로 아시아 사업 기반을 넓힌다. 지역·글로벌 RoRo 공급자로서의 입지를 강화한다.","eImp":"The deal broadens the company's Asian footprint by adding ocean transport to an existing logistics relationship. It strengthens its position as a regional and global RoRo provider.","url":"https://splash247.com/wallenius-wilhelmsen-adds-130m-asian-shipping-contract/"},{"code":"WW","title":"발레니우스 빌헬름센, 2026년 정기주총서 전 안건 승인","src":"TipRanks","date":"2026-04-29","kSum":"발레니우스 빌헬름센은 4월 29일 전자 방식으로 개최한 2026년 정기주주총회에서 상정된 모든 안건을 승인받았다. 지명위원회는 룬에 비에르케(전 DNB CEO)를 이사회 의장으로 제안했다.","eSum":"Wallenius Wilhelmsen's shareholders approved all agenda items at the fully digital 2026 AGM held on 29 April. The nomination committee proposed Rune Bjerke, former DNB CEO, as board chair for the 2026-2027 term.","kImp":"주총 안건 승인은 배당·이사회 구성 등 지배구조 관련 결정을 확정한다. 금융·에너지 분야 경력의 신임 의장 선임은 향후 자본배분 방향성을 시사한다.","eImp":"AGM approval finalises governance decisions on dividends and board composition. The incoming chair's finance and energy background signals the direction of future capital allocation.","url":"https://www.tipranks.com/news/company-announcements/wallenius-wilhelmsen-shareholders-approve-all-proposals-at-2026-virtual-agm"},{"code":"WW","title":"발레니우스 빌헬름센-현대차그룹, EUKOR 20% 지분 풋·콜옵션 조건 개정","src":"Wallenius Wilhelmsen","date":"2026-04-07","kSum":"발레니우스 빌헬름센과 현대차그룹은 4월 7일 HMG의 EUKOR 20% 지분에 걸린 풋·콜옵션 조건을 개정해, 오션캐리어계약(OCC)에 HMG 물량의 50% 이상 약정이 유지되는 한 옵션을 행사할 수 없도록 했다. 현 OCC는 2029년 말까지 유효하며 옵션 최조기 행사일은 2031년 1월 1일이 됐다.","eSum":"Wallenius Wilhelmsen and Hyundai Motor Group revised the put and call options on HMG's 20% EUKOR stake on 7 April, making them non-exercisable while the Ocean Carrier Contract includes a commitment of at least 50% of HMG's volumes. The current OCC runs to end-2029, pushing the earliest exercise date to 1 January 2031.","kImp":"약 8억9,700만 달러에 달하던 풋옵션 부채를 유동에서 비유동으로 재분류하고 순현재가치로 재측정해 단기 재무 부담을 크게 완화한다. 현대차그룹과의 장기 물량 파트너십을 재확인한 조치다.","eImp":"It reclassifies the roughly USD 897m put liability from current to non-current and remeasures it at net present value, easing near-term balance-sheet pressure. The move reaffirms the long-term volume partnership with Hyundai Motor Group.","url":"https://www.walleniuswilhelmsen.com/stock-exchange-notice/eukor-strengthens-long-term-partnership-with-hyundai-and-kia"},{"code":"WW","title":"오션버드, 발레니우스 빌헬름센 자동차운반선 '티라나'서 윙560 세일 시운전 완료","src":"PortNews","date":"2026-07-03","kSum":"오션버드는 발레니우스 빌헬름센의 230m급 자동차운반선 '티라나'에 설치한 첫 윙560 강성 세일의 항만·해상 인수시험을 7월 1일까지 완료했다. 세일은 6월 21~24일 로테르담 다멘조선소에서 장착됐으며, EU 지원 '오르셀 호라이즌' 프로그램의 일환으로 약 10%의 에너지효율 개선을 목표로 한다.","eSum":"Oceanbird completed harbour and sea acceptance tests of its first onboard Wing560 rigid sail on Wallenius Wilhelmsen's 230-metre car carrier Tirranna by 1 July. Fitted at Damen's Rotterdam yard on 21-24 June, the sail is part of the EU-funded Orcelle Horizon programme targeting about 10% energy-efficiency gains.","kImp":"실제 운항 중인 자동차운반선에 풍력보조추진을 적용한 실증으로, 회사의 다각적 탈탄소 전략에서 풍력 기술의 상업성을 검증하는 시험대다. 넷제로 목표 달성의 보조 수단으로 주목된다.","eImp":"It is a live demonstration of wind-assisted propulsion on an operating car carrier, testing the commercial viability of wind tech within the company's multi-pronged decarbonisation strategy. It is watched as a complementary lever toward net-zero.","url":"https://en.portnews.ru/news/393701/"}]},{"code":"EE","type":"news","kTitle":"Section 6. 에너지 효율·탈탄소","eTitle":"Section 6. Energy Efficiency","items":[{"code":"EE","title":"EUKOR·World Fuel, 상하이항에서 신조 PCTC '아틱 턴' 첫 그린메탄올 벙커링 완료","src":"gCaptain","date":"2026-07-21","kSum":"EUKOR, SIPG Energy, World Fuel이 신형 셰이퍼급 자동차운반선 '아틱 턴'에 약 2,800MT의 그린메탄올을 STS 방식으로 공급했다. 이 그린메탄올은 도시고형폐기물로 생산되고 ISCC-EU 인증을 받았으며 탄소집약도가 25gCO2e/MJ 미만이다.","eSum":"EUKOR, SIPG Energy and World Fuel delivered about 2,800 MT of green methanol via ship-to-ship transfer to the new Shaper-class car carrier Arctic Tern at Shanghai. The fuel was made from municipal solid waste, ISCC-EU certified, with a carbon intensity below 25 gCO2e/MJ.","kImp":"국제 PCTC 운항선사를 대상으로 상하이 현지 생산 그린메탄올을 처음 공급한 사례로, 자동차운반선 부문의 메탄올 연료 공급망이 실제 상업 운항 단계로 진입했음을 보여준다.","eImp":"It marks the first supply of locally produced green methanol in Shanghai to an international PCTC operator, showing that methanol supply chains for car carriers have moved into commercial operation.","url":"https://gcaptain.com/eukor-completes-first-green-methanol-bunkering-for-new-shaper-class-car-carrier-in-shanghai/"},{"code":"EE","title":"함부르크항, MB Energy와 STS 암모니아 벙커링 안전개념 완성","src":"Manifold Times","date":"2026-07-21","kSum":"함부르크항만청(HPA)과 통합에너지기업 MB Energy가 선박 간(STS) 암모니아 벙커링에 대한 종합 위험분석을 마치고 전용 안전개념을 개발했다. 이를 통해 함부르크항은 향후 안전하고 신뢰성 있는 암모니아 벙커링을 위한 '벙커 준비(bunker ready)' 상태를 갖추게 된다.","eSum":"The Hamburg Port Authority (HPA) and integrated energy firm MB Energy completed a comprehensive risk analysis and developed a dedicated safety concept for ship-to-ship ammonia bunkering. This lays the groundwork for the Port of Hamburg to become 'bunker ready' for safe and reliable future ammonia bunkering.","kImp":"무탄소 연료로 주목받는 암모니아의 최대 걸림돌인 독성·안전 문제를 유럽 주요 허브항이 선제적으로 해소하는 조치로, 암모니아 추진선 상용화의 인프라 기반을 넓힌다.","eImp":"A major European hub port is proactively addressing ammonia's toxicity and safety hurdles, expanding the infrastructure base needed to commercialize ammonia-fuelled ships.","url":"https://www.manifoldtimes.com/news/hpa-and-mb-energy-develop-safety-concept-for-sts-ammonia-bunkering"},{"code":"EE","title":"Capital·K조선·로이드선급, MR 탱커용 풍력보조추진 공동개발 착수","src":"Marine Log","date":"2026-07-21","kSum":"Capital Ship Management, K조선, 로이드선급(LR)이 5만dwt MR 탱커에 풍력보조추진시스템(WAPS)을 적용하는 공동개발프로젝트(JDP)를 시작했다. 벌크선에 비해 도입이 저조했던 프로덕트 탱커 부문에서 WAPS의 상업적 타당성과 연료·배출 저감 효과를 검증한다.","eSum":"Capital Ship Management, K Shipbuilding and Lloyd's Register launched a Joint Development Project to apply wind-assisted propulsion (WAPS) to a 50,000 dwt MR tanker. It will assess the commercial viability and fuel and emissions savings of WAPS in the product tanker segment, where uptake has lagged bulkers.","kImp":"미개척 영역이던 MR 탱커에 풍력보조추진을 확장하려는 시도로, 성공 시 표준 프로덕트 탱커 선대 전반의 CII 개선과 연료비 절감 경로를 제시한다.","eImp":"By extending wind-assist into the largely unexplored MR tanker market, a successful outcome could open a CII-improvement and fuel-saving pathway across the standard product tanker fleet.","url":"https://www.marinelog.com/news/new-project-targets-wind-assisted-propulsion-for-mr-tanker-sector/"},{"code":"EE","title":"SunRui, 노르웨이 Halten Bulk 자가하역 벌크선 2척에 로터세일 공급 계약","src":"Xinde Maritime","date":"2026-07-09","kSum":"칭다오 SunRui가 장쑤 Suhao조선·China Shipbuilding Trading과 7,100dwt 자가하역 벌크선 2척용 풍력보조 로터세일 공급 계약을 체결했다. 각 선박에는 직경 4m·높이 28m 틸팅형 로터세일 2기가 설치되며 최대 225rpm 회전으로 기당 215kN의 추력을 낸다.","eSum":"Qingdao SunRui signed a contract with Jiangsu Suhao Shipbuilding and China Shipbuilding Trading to supply wind-assisted rotor sails for two 7,100 dwt self-unloading bulk carriers. Each vessel gets two 4m-diameter, 28m-tall tilting rotor sails spinning up to 225 rpm and delivering up to 215 kN of thrust each.","kImp":"노르웨이 근해 벌크선주 Halten Bulk 발주로, 중국산 로터세일 기술이 유럽 근해 상선 시장으로 확산되며 풍력보조추진 채택이 소형 벌크선까지 넓어지고 있음을 보여준다.","eImp":"Ordered by Norwegian short-sea owner Halten Bulk, the deal shows Chinese rotor-sail technology spreading into the European short-sea market and wind-assist adoption reaching smaller bulk carriers.","url":"https://xindemarinenews.com/news/2075970286551048194"},{"code":"EE","title":"에쓰오일, 울산항에서 B30 바이오선박연료 공급 개시","src":"Ship & Bunker","date":"2026-07-22","kSum":"에쓰오일이 지속가능 바이오연료 30%를 VLSFO에 혼합한 B30-VLSFO 선박연료 공급을 국내에서 시작했다. 온산정유공장 초저유황유와 울산권 바이오연료 생산·저장 인프라를 연계해 원료조달부터 혼합·저장·공급까지 단일 지역에서 처리한다.","eSum":"S-Oil has begun supplying B30-VLSFO, a marine fuel blending 30% sustainable biofuel with VLSFO, in South Korea. It links ultra-low sulphur fuel from its Onsan refinery with biofuel production and storage in the Ulsan area to handle feedstock, blending, storage and delivery within one region.","kImp":"드롭인 연료로 개조 없이 배출을 낮출 수 있는 바이오연료를 자동차운반선 수요가 강한 울산항에서 공급함으로써, IMO·EU 규제 대응용 저탄소 연료 선택지가 국내에서 확대된다.","eImp":"By offering a drop-in fuel that cuts emissions without retrofits at Ulsan, where car-carrier demand is strong, it broadens low-carbon fuel options in Korea for meeting IMO and EU rules.","url":"https://shipandbunker.com/news/apac/864686-s-oil-starts-b30-marine-biofuel-supply-in-south-korea"},{"code":"EE","title":"엑슨모빌, 발레니우스 빌헬름센과 FAME 잔사 기반 B30 바이오연료 해상시험 완료","src":"SAFETY4SEA","date":"2026-06-23","kSum":"엑슨모빌이 지방산메틸에스테르(FAME) 증류잔사로 만든 B30 0.50% 황 선박연료를 발레니우스 빌헬름센에 공급해 해상시험을 성공적으로 마쳤다. 벨기에 제브뤼헤에서 자동차운반선 '타이터스'가 벙커링했으며 여과·정제 문제 없이 엔진 성능이 안정적으로 유지됐다.","eSum":"ExxonMobil supplied a B30 0.50% sulphur marine fuel made from FAME distillation residue to Wallenius Wilhelmsen and completed a successful sea trial. Bunkered by the car carrier Titus in Zeebrugge, the blend caused no filtration or purification issues and engine performance stayed stable.","kImp":"폐기물성 FAME 잔사를 활용한 바이오연료가 별도 개조 없이 안정 운항 가능함을 입증해, 자동차운반선 부문의 저탄소 드롭인 연료 상용화 가능성을 높였다.","eImp":"Demonstrating that waste-derived FAME-residue biofuel runs reliably without modifications strengthens the case for commercial low-carbon drop-in fuels in the car-carrier segment.","url":"https://safety4sea.com/exxonmobil-completes-b30-biofuel-trial-with-wallenius-wilhelmsen/"},{"code":"EE","title":"Avenir LNG, 신조 LNG 벙커링선 '아베니르 앰비션' 진수","src":"Offshore Energy","date":"2026-07-20","kSum":"Avenir LNG가 중국 CIMC SOE 조선소에서 신조 LNG 벙커링선 '아베니르 앰비션'을 진수했으며 연내 인도가 예상된다. 2026년 상반기 대체연료 발주에서 LNG는 137척 중 73척으로 여전히 최대 비중을 차지했고 LNG 벙커링선은 운항 67척에 42척이 추가 발주됐다.","eSum":"Avenir LNG launched its newbuild LNG bunkering vessel Avenir Ambition at CIMC SOE's yard in China, with delivery expected by year-end. In H1 2026 LNG remained the dominant alternative fuel with 73 of 137 orders, and the LNG bunker fleet stood at 67 in operation plus 42 on order.","kImp":"LNG 이중연료선 발주가 견조한 가운데 벙커링 인프라가 계속 확충되면서, LNG가 당분간 실질적 전환 연료로서 해운 탈탄소 경로의 핵심 축을 유지하고 있음을 보여준다.","eImp":"With robust LNG dual-fuel ordering and continued bunkering infrastructure growth, it shows LNG remaining a key pillar of shipping's decarbonization path as a practical transition fuel for now.","url":"https://www.offshore-energy.biz/watch-avenirs-newbuild-lng-bunkering-vessel-hits-the-water/"}]},{"code":"DIG","type":"news","kTitle":"Section 7. 디지털라이제이션","eTitle":"Section 7. Digitalization","items":[{"code":"DIG","title":"ISO 5909, 전자선하증권(eBL) 국제 표준으로 무역 디지털화 가속","src":"Smart Maritime Network","date":"2026-07-20","kSum":"ISO/TC154 작업반9와 UN/CEFACT가 공동 개발한 ISO 5909가 전자선하증권의 업무 프로세스, 데이터 의미체계, 플랫폼 기능 요건을 규정하는 국제 표준으로 자리잡았다. 표준화된 eBL은 화물 인도 속도를 높이고 분쟁을 줄이며 무역금융 접근성과 플랫폼 간 이동성을 보장한다.","eSum":"ISO 5909, jointly developed by ISO/TC154 Working Group 9 and UN/CEFACT, now defines the business processes, data semantics and platform requirements for lawful, interoperable electronic bills of lading. A standardised eBL enables faster cargo release, fewer disputes and full portability across digital trade platforms.","kImp":"종이 선하증권에 의존해온 무역 문서를 검증 가능한 디지털 형태로 전환하는 법적·기술적 기반이 마련돼 해운·무역금융 전반의 디지털 전환이 가속된다.","eImp":"A single international standard gives eBL the legal and technical foundation to replace paper documentation, accelerating digitalisation across shipping and trade finance.","url":"https://smartmaritimenetwork.com/2026/07/20/an-international-standard-for-electronic-bills-of-lading/"},{"code":"DIG","title":"MagicPort, 항만 콜 디지털화 위해 300만 달러 투자 유치","src":"Splash247","date":"2026-07-10","kSum":"해운 소프트웨어 스타트업 MagicPort가 프리시드 라운드에서 300만 달러를 유치해 항만 콜 관리용 AI 플랫폼을 확장한다. 80개국 300여 개 기업이 이미 이 플랫폼으로 항만 콜 조율과 수작업 행정을 자동화하고 있다.","eSum":"Maritime software startup MagicPort has raised $3m in a pre-seed round to expand its AI platform for port call management. More than 300 companies across 80 countries already use it to automate routine tasks and coordinate vessel calls.","kImp":"항만 콜은 여전히 이메일과 스프레드시트에 의존하는 해운업의 가장 비(非)디지털화된 영역으로, 이 부문 최적화 투자가 지연 감소와 자산 활용도 향상으로 이어진다.","eImp":"Port calls remain one of shipping's least digitalised processes, so investment in this area targets fewer delays, better asset utilisation and lower administrative costs.","url":"https://splash247.com/magicport-lands-3m-to-accelerate-port-call-digitalisation/"},{"code":"DIG","title":"Veson Nautical, AI·데이터·협업을 단일 해운 플랫폼으로 통합","src":"Digital Ship","date":"2026-07-01","kSum":"Veson Nautical이 IMOS 소프트웨어와 AI 비서 CoCaptain, AI 메일, 신규 선박·벙커 인텔리전스를 하나의 환경으로 결합한 Veson Platform을 출시했다. 사용자는 계약, 항해 정보, 통신, 시장 정보를 동일한 인터페이스에서 자연어로 조회할 수 있다.","eSum":"Veson Nautical has launched the Veson Platform, combining its IMOS software with AI assistant CoCaptain, AI-powered Mail and new vessel and bunker intelligence in one environment. Users can access contracts, voyage data, communications and market intelligence from a single interface using natural language.","kImp":"AI를 별도 앱이 아닌 기존 해운 업무 흐름에 내장하는 방식으로, 정보 검색 시간을 줄이면서 운영 판단의 신뢰성을 유지하려는 업계 흐름을 보여준다.","eImp":"It shows how vendors are embedding AI inside established maritime workflows rather than as standalone tools, cutting search time while preserving trust in operational data.","url":"https://thedigitalship.com/news/maritime-software/veson-nautical-brings-ai-data-and-collaboration-into-single-maritime-platform/"},{"code":"DIG","title":"Lloyd's Register, 디지털 경보 피로 연구를 영국 의회에 제출","src":"Digital Ship","date":"2026-07-21","kSum":"선박이 더 많은 디지털 경보와 운영 데이터를 생성함에 따라 Lloyd's Register가 경보 피로(alarm fatigue) 연구를 영국 의회에 제출했다. LR은 디지털 안전 시스템이 선원에게 미치는 영향을 정책적으로 고려할 것을 촉구했다.","eSum":"As ships generate more digital alerts and operational data, Lloyd's Register has taken its research on alarm fatigue to the UK Parliament. LR is urging policymakers to consider how these digital safety systems affect seafarers.","kImp":"선박 디지털화가 오히려 과도한 경보로 인적 안전을 위협할 수 있음을 규제 차원에서 다루기 시작한 사례로, 인간중심 디지털 설계의 중요성을 부각한다.","eImp":"It marks a regulatory move to address how digitalisation can overwhelm crews with alerts, highlighting the need for human-centred design in shipboard digital systems.","url":"https://thedigitalship.com/news/maritime-software/lloyds-register-takes-maritime-digital-safety-research-on-alarm-fatigue-to-uk-parliament/"},{"code":"DIG","title":"Attica Group, ABB와 함께 33척 페리를 단일 대시보드로 디지털화","src":"Digital Ship","date":"2026-07-16","kSum":"그리스 페리 운영사 Attica Group이 ABB Ability OneBox Marine Signals를 도입해 33척 규모 선대의 디지털화 프로그램을 확장한다. 선대 전체 성능 데이터를 하나의 대시보드로 통합해 운영 가시성을 높인다.","eSum":"Greek ferry operator Attica Group is expanding its fleet digitalisation programme by deploying ABB Ability OneBox Marine Signals across 33 ferries. The system consolidates fleet-wide performance data into a single dashboard for improved operational visibility.","kImp":"선내 센서·IoT 데이터를 표준화된 대시보드로 집약하는 선대 단위 디지털화가 여객선 부문에서도 본격화되고 있음을 보여준다.","eImp":"It shows fleet-scale digitalisation - aggregating onboard sensor and IoT data into a standardised dashboard - taking hold in the passenger ship segment.","url":"https://thedigitalship.com/news/maritime-software/33-ferries-one-dashboard-attica-group-expands-fleet-digitalisation-with-abb/"},{"code":"DIG","title":"미 해안경비대, 해양 사이버 사고 17% 증가…피싱·AI·OT 위협 부상","src":"SAFETY4SEA","date":"2026-07-08","kSum":"미 해안경비대(USCG)는 해양 사이버 사고가 전년 대비 17% 증가했으며 피싱, AI 악용, 운영기술(OT) 위험이 위협 지형을 재편하고 있다고 밝혔다. 공격자들은 데이터 탈취를 넘어 선박·항만 운영을 지탱하는 실제 시스템을 겨냥하고 있다.","eSum":"The US Coast Guard reports maritime cyber incidents rose 17% as phishing, AI abuse and operational technology (OT) risks reshape the threat landscape. Attackers are moving beyond data theft to target the systems that keep ships moving and ports functioning.","kImp":"선박·항만이 위성 연결과 자동화로 초연결화될수록 OT 사이버 위험이 커져, 2026년 발효되는 신규 사이버 규정 준수와 방어 태세 강화가 시급해진다.","eImp":"As vessels and ports become hyper-connected through satellite links and automation, OT cyber risk grows, making compliance with new 2026 cyber rules and stronger defences urgent.","url":"https://safety4sea.com/uscg-maritime-cyber-incidents-rise-17-as-phishing-ai-and-ot-risks-reshape-the-threat-landscape/"},{"code":"DIG","title":"선원 복지와 멀티네트워크가 여는 해양 연결성의 다음 시대","src":"Seatrade Maritime","date":"2026-07-14","kSum":"Seatrade가 선원 복지와 멀티네트워크 솔루션을 중심으로 해양 연결성의 다음 국면을 조명했다. 선사들은 Starlink 등 LEO 광대역을 VSAT·L밴드와 결합한 하이브리드 구성으로 운영과 선원 후생을 동시에 지원하고 있다.","eSum":"Seatrade examines the next era of maritime connectivity centred on crew welfare and multi-network solutions. Operators are combining LEO broadband such as Starlink with VSAT and L-band into hybrid architectures that serve both operations and crew wellbeing.","kImp":"저지연 LEO 연결성은 실시간 데이터 전송과 원격 지원, 선원 복지의 기반으로, 선박 디지털화와 인재 확보 경쟁의 핵심 인프라로 부상하고 있다.","eImp":"Low-latency LEO connectivity underpins real-time data, remote support and crew welfare, emerging as core infrastructure for both vessel digitalisation and talent retention.","url":"https://www.seatrade-maritime.com/maritime-technology/crew-welfare-multi-network-solutions-and-the-next-era-of-maritime-connectivity"},{"code":"DIG","title":"30억 달러 규모 'Port Alpha', 소프트웨어 주도 조선으로 美 조선업 재편 추진","src":"Digital Ship","date":"2026-07-21","kSum":"Saronic가 텍사스 브라운스빌을 첨단 제조와 소프트웨어 주도 생산을 결합한 차세대 조선소 'Port Alpha' 부지로 선정했다. 30억 달러 규모의 이 프로젝트는 조선 공정 자체를 디지털·자동화 중심으로 재정의하는 것을 목표로 한다.","eSum":"Saronic has selected Brownsville, Texas, as the site for Port Alpha, a next-generation shipyard combining advanced manufacturing with software-driven production. The $3bn project aims to redefine US shipbuilding around digital and automated processes.","kImp":"설계·건조 전 과정을 소프트웨어로 제어하는 '디지털 조선소' 모델은 디지털 트윈과 자동화를 조선 산업의 핵심 경쟁력으로 끌어올린다.","eImp":"A software-controlled 'digital shipyard' model elevates digital twins and automation into core competitive factors for the shipbuilding industry.","url":"https://thedigitalship.com/news/maritime-software/3bn-port-alpha-project-aims-to-redefine-us-shipbuilding-through-software-driven-production/"}]},{"code":"TECH","type":"news","kTitle":"Section 8. 선박관리 기술","eTitle":"Section 8. Ship Manager Technical","items":[{"code":"TECH","title":"2026년 선박 탑재형 탄소포집(OCCS) 현주소: LR·ICS 종합 보고서","src":"gCaptain","date":"2026-07-01","kSum":"로이드선급 자문부문이 국제해운회의소(ICS) 의뢰로 작성한 보고서에 따르면 선박 탑재형 탄소포집(OCCS)은 여러 선종에서 실증됐으며 성숙한 시스템은 70~95%의 포집률을 달성할 수 있다. 다만 상업적 확대는 선박 설계 통합, 항만의 CO2 인수 인프라, 실효성 있는 규제 프레임워크라는 세 가지 과제 해결에 달려 있다.","eSum":"A Lloyd's Register Advisory report commissioned by the ICS finds onboard carbon capture (OCCS) is feasible and demonstrated across multiple ship types, with mature systems achieving 70-95% capture rates. Commercial scale-up, however, hinges on solving ship-design integration, port CO2 reception infrastructure and a workable regulatory framework.","kImp":"OCCS는 저탄소 연료가 충분히 확대되기 전까지의 유력한 가교 기술로 부상하고 있어, 선박관리 기술팀은 스크러버·폐열회수 등과 연계한 개조 가능성을 미리 검토할 필요가 있다.","eImp":"OCCS is emerging as a credible near-term bridge until low-carbon fuels scale, so ship-management technical teams should assess retrofit potential alongside scrubbers and waste-heat recovery.","url":"https://gcaptain.com/the-state-of-onboard-carbon-capture-at-sea-in-2026/"},{"code":"TECH","title":"WinGD·EXMAR, 세계 최초 암모니아 추진 외항선 '앤트워펜' 인도","src":"gCaptain","date":"2026-06-10","kSum":"WinGD와 EXMAR가 세계 최초로 암모니아 연료로 운항하도록 설계된 외항선 '앤트워펜(Antwerpen)'을 인도했다. 벨기에 도시명을 딴 중형 가스운반선 4척 시리즈의 첫 선박으로, WinGD의 X-DF-A 2행정 암모니아 엔진을 탑재했다.","eSum":"WinGD and EXMAR have delivered Antwerpen, described as the world's first ocean-going vessel designed to operate on ammonia fuel. It is the first of a four-ship series of midsize gas carriers named after Belgian cities, powered by WinGD's X-DF-A two-stroke ammonia engine.","kImp":"무탄소 연료 암모니아의 첫 상용 외항 적용으로, 후속 암모니아 추진선 발주와 엔진·연료공급 기술의 성숙도를 가늠하는 이정표가 된다.","eImp":"The first commercial ocean-going use of zero-carbon ammonia is a milestone for gauging follow-on ammonia newbuild orders and the maturity of engine and fuel-supply technology.","url":"https://gcaptain.com/shippings-ammonia-era-begins-as-exmar-receives-landmark-newbuild/"},{"code":"TECH","title":"포테스큐, CMB.TECH와 암모니아 추진 뉴캐슬막스 벌커 최대 12척 계약","src":"gCaptain","date":"2026-06-23","kSum":"호주 광산기업 포테스큐가 벨기에 CMB.TECH와 암모니아 대응 뉴캐슬막스 벌크선 최대 12척을 용선하는 계약을 체결했다. 암모니아를 선박 연료로 채택한 가장 큰 규모의 상업적 약정 중 하나다.","eSum":"Australian miner Fortescue has signed a deal to charter up to 12 ammonia-capable Newcastlemax bulk carriers from Belgium's CMB.TECH. It is one of the largest commercial commitments to date for ammonia as a marine fuel.","kImp":"대형 화주가 암모니아 추진 벌커를 대량 도입하면서 무탄소 벌크 운송의 상용화가 가속되고, 조선·엔진 업계의 관련 기술 수요를 자극한다.","eImp":"A major cargo owner adopting ammonia-powered bulkers at scale accelerates commercialization of zero-carbon bulk transport and stimulates shipyard and engine technology demand.","url":"https://gcaptain.com/fortescue-cmb-tech-sign-deal-for-up-to-12-ammonia-capable-bulk-carriers/"},{"code":"TECH","title":"밸류마리타임, 넵튠라인즈 자동차운반선에 탄소포집 대응 스크러버 개조","src":"SWZ Maritime","date":"2026-07-17","kSum":"밸류마리타임이 넵튠라인즈의 자매 PCTC '넵튠 타로스'와 '넵튠 에토스'에 15MW급 Filtree 시스템 2기를 개조 설치한다. Filtree는 SOx 저감 스크러버로, 향후 탄소포집 기능으로 업그레이드할 수 있도록 설계됐다.","eSum":"Value Maritime will retrofit Neptune Lines' sister PCTCs Neptune Tharros and Neptune Ethos with two 15-MW Filtree systems. Filtree is a SOx-reducing scrubber built carbon-capture-ready for future upgrade.","kImp":"PCTC 선종 최초의 탄소포집 대응 스크러버 적용 사례로, 자동차운반선 부문에서도 배출 저감 개조가 확산되는 흐름을 보여준다.","eImp":"The first carbon-capture-ready scrubber installation in the PCTC segment signals a spreading emissions-retrofit trend for car carriers.","url":"https://swzmaritime.nl/news/2026/07/17/value-maritime-carbon-capture-ready-system-for-car-carriers/"},{"code":"TECH","title":"완하이, 메탄올 추진 신조 컨테이너선에 닛폰페인트 선체 도료 채택","src":"Dry Bulk Magazine","date":"2026-07-20","kSum":"완하이가 메탄올 이중연료 신조 컨테이너선(8,700TEU·16,000TEU급)에 닛폰페인트마린의 FASTAR XI 선체 도료와 EVER COOL 열반사 도료를 적용한다. 에너지 소비를 낮추기 위한 조치다.","eSum":"Wan Hai will apply Nippon Paint Marine's FASTAR XI hull coating and EVER COOL heat-reflective coating to its methanol dual-fuel newbuild containerships of 8,700 TEU and 16,000 TEU. The move is aimed at lowering energy consumption.","kImp":"선체 도료는 저비용으로 연료소모를 5% 안팎 줄일 수 있는 에너지효율 수단으로, 신조 사양에 표준적으로 채택되는 흐름을 보여준다.","eImp":"Hull coatings are a low-cost efficiency measure that can cut fuel burn by around 5%, and their standard adoption in newbuild specs reflects a broader efficiency trend.","url":"https://www.drybulkmagazine.com/product-news/20072026/wan-hai-adopts-nippon-paint-marine-hull-and-surface-coatings-in-newbuild-projects/"},{"code":"TECH","title":"ABS, 한국 원자력 추진 1만5,000TEU 컨테이너선 개념설계 승인","src":"Splash247","date":"2026-07-23","kSum":"미국선급(ABS)이 한국에서 개발한 1만5,000TEU급 원자력 추진 컨테이너선 개념설계에 대해 승인을 부여했다. 차세대 무탄소 추진 옵션으로서 원자력 상선의 기술적 타당성 검토가 진전됐다.","eSum":"ABS has granted approval to a Korean-developed 15,000 TEU nuclear-powered containership concept design. It advances technical feasibility work on nuclear merchant ships as a next-generation zero-carbon propulsion option.","kImp":"원자력 추진은 장거리 무탄소 운항의 대안으로 주목받고 있어, 선급의 개념설계 승인은 규제·설계 논의를 앞당기는 신호다.","eImp":"Nuclear propulsion is drawing attention as a zero-carbon option for long-haul trades, and class concept approval signals accelerating regulatory and design discussion.","url":"https://splash247.com/abs-clears-korean-nuclear-powered-boxship-concept/"},{"code":"TECH","title":"노르스파워, 올덴도르프 벌커서 로터세일 연료절감 성능 검증","src":"Splash247","date":"2026-07-23","kSum":"노르스파워가 올덴도르프의 벌크선에 설치된 로터세일의 연료 절감 효과를 실측 운항 데이터로 검증했다. 실선 데이터가 풍력보조추진의 상업적 타당성을 뒷받침하고 있다.","eSum":"Norsepower has validated the fuel-saving performance of rotor sails fitted on an Oldendorff bulk carrier using measured operational data. Real-world voyage data is reinforcing the commercial case for wind-assisted propulsion.","kImp":"검증된 실선 절감 데이터는 풍력보조추진 장치의 투자 회수 기간을 명확히 해 채택 확대의 근거를 제공한다.","eImp":"Verified in-service savings data clarifies payback periods for wind-assist systems and underpins wider adoption.","url":"https://splash247.com/norsepower-validates-rotor-sail-savings-on-oldendorff-bulker/"},{"code":"TECH","title":"DNV, 에코윈드 벤토포일 윈드윙 승인… 광범위한 적용 길 열려","src":"Splash247","date":"2026-07-17","kSum":"DNV가 에코윈드의 VentoFoil 흡입식 윙세일에 대한 승인을 부여해 더 광범위한 상용 적용의 길이 열렸다. 표준화된 선급 승인은 다양한 선종에 걸친 설치를 촉진한다.","eSum":"DNV has granted approval for Econowind's VentoFoil suction wing sails, clearing the path for wider commercial rollout. Standardised class approval facilitates installation across a range of ship types.","kImp":"선급 승인은 풍력보조추진 장치의 설치 승인 절차를 간소화해 개조와 신조 양쪽에서 채택을 가속한다.","eImp":"Class approval streamlines installation sign-off for wind-assist devices, accelerating uptake in both retrofit and newbuild.","url":"https://splash247.com/dnv-approval-clears-path-for-wider-ventofoil-rollout/"}]},{"code":"HR","type":"news","kTitle":"Section 9. 해기인력·선원","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"크루 웰페어 위크 2026: 피로 해소가 건강한 해상 생활의 핵심","src":"SAFETY4SEA","date":"2026-07-21","kSum":"2026 크루 웰페어 위크 패널에서 전문가들은 해상 신체 건강이 개별 캠페인이 아니라 충분한 휴식, 영양가 있는 식사, 운동 기회, 적절한 거주환경 등 구조적 요소에 달려 있다고 강조했다. 특히 피로와 근로·휴식시간 위반이 심혈관 건강과 정신건강, 사고 위험과 직결되는 최우선 과제로 지목됐다.","eSum":"At a panel during 2026 Crew Welfare Week, experts stressed that physical wellness at sea cannot be fixed by isolated health campaigns but requires adequate rest, nutritious food, exercise and proper living conditions across the maritime value chain. Fatigue and work/rest-hour violations were flagged as a priority issue linked to cardiovascular health, mental wellbeing and accident risk.","kImp":"피로 관리는 선원 유지율과 안전에 직결되는 문제로, 선사가 개인 책임이 아닌 조직 차원의 해결과제로 접근해야 함을 보여준다.","eImp":"Fatigue is a retention and safety issue that owners must treat as an organisational responsibility rather than an individual lifestyle choice.","url":"https://safety4sea.com/cm-crew-welfare-week-2026-tackling-fatigue-is-key-to-a-healthier-life-at-sea/"},{"code":"HR","title":"선원은 지정학적 리스크의 완충재가 되어선 안 된다","src":"Seatrade Maritime","date":"2026-07-22","kSum":"시트레이드 기고에서 전문가는 호르무즈 등 분쟁 해역에서 공격 위험을 떠안는 선원들이 지정학적 리스크의 완충재 역할을 강요받고 있다고 지적했다. 선원 보호를 위한 명확한 기준과 책임 분담이 필요하다는 주장이다.","eSum":"A Seatrade Maritime opinion piece argues that seafarers are being forced to act as the 'shock absorbers' of geopolitical risk, bearing the danger of transiting conflict zones such as the Strait of Hormuz. It calls for clearer standards and shared responsibility to protect crews.","kImp":"홍해·호르무즈 긴장이 이어지는 가운데 선원 안전과 항행 거부권, 위험수당 등 인사·복지 이슈가 부각되고 있다.","eImp":"As Red Sea and Hormuz tensions persist, seafarer safety, the right to refuse transit and risk pay are becoming central crewing and welfare issues.","url":"https://www.seatrade-maritime.com/crewing/seafarers-cannot-remain-the-shock-absorbers-of-geopolitical-risk"},{"code":"HR","title":"ITF, 라스팔마스서 선원 유기 사례 보고… 체불임금 6만8천 달러","src":"The Maritime Executive","date":"2026-07-09","kSum":"ITF는 라스팔마스항에 억류된 일반화물선 Lady Mina호에서 6명의 선원이 유기됐으며 체불임금이 6만8천 달러에 이른다고 보고했다. 일부 선원은 계약 만료 후에도 송환되지 못했고 기관장은 2026년 1월부터 무급으로 근무해 왔다.","eSum":"The ITF reported six seafarers abandoned aboard the general cargo ship Lady Mina, detained in Las Palmas, with unpaid wages reaching $68,000. Some had served well beyond the 11-month MLC limit, and the chief engineer had gone unpaid since January 2026.","kImp":"선원 유기가 사상 최고치를 경신하는 가운데 MLC 재정보증 위조 의혹까지 제기돼 집행 강화 필요성이 커지고 있다.","eImp":"With abandonment cases at record highs and allegations of fraudulent MLC financial security, the case underscores the need for stronger enforcement.","url":"https://maritime-executive.com/article/itf-reports-shipowner-abandoned-seafarers-in-las-palmas-due-68-000"},{"code":"HR","title":"2030년까지 사관 부족 10만 명 넘어설 위험… BIMCO/ICS 보고서","src":"Splash247","date":"2026-06-25","kSum":"BIMCO와 ICS의 '2026 선원 인력 보고서'는 확대되는 세계 선대 운영을 위해 2030년까지 STCW 자격 사관 11만3천 명 이상이 추가로 필요하다고 밝혔다. 현재 사관은 3만9천 명 부족한 반면 부원은 5만6천여 명 초과 상태다.","eSum":"The BIMCO/ICS Seafarer Workforce Report 2026 warns the industry needs more than 113,000 additional STCW-certified officers by 2030 to crew the growing fleet. It estimates a current shortfall of 39,100 officers alongside a surplus of 56,890 ratings.","kImp":"기관·항해 사관 채용난이 가장 심각해 신규 연료·디지털 전환기에 구조적 인력난이 심화될 전망이다.","eImp":"Recruitment is hardest for engineering and deck officers, pointing to a deepening structural labour gap as ships adopt new fuels and digital systems.","url":"https://splash247.com/officer-shortage-risks-exceeding-100000-by-2030/"},{"code":"HR","title":"IMO, 세계 해양여성의 날에 젠더 주류화 핸드북 발간","src":"Seatrade Maritime","date":"2026-05-18","kSum":"IMO는 5월 18일 세계 해양여성의 날을 맞아 '정책에서 실천으로'를 주제로 젠더 주류화 핸드북을 발간했다. 이 핸드북은 해사행정청, 선사, 항만, 교육기관이 정책과 운영에 성인지 관점을 통합하도록 지원하는 실무 자료다.","eSum":"On the 18 May International Day for Women in Maritime, the IMO launched a Handbook on Gender Mainstreaming under the theme 'From Policy to Practice.' It is designed to help maritime administrations, shipping companies, ports and training institutions embed gender perspectives into their operations.","kImp":"여성 선원이 전체의 2%에 그치는 현실에서 다양성 확대는 선원 부족 완화와 인력 저변 확대의 핵심 과제다.","eImp":"With women making up just 2% of seafarers, advancing diversity is key to easing shortages and broadening the talent pool.","url":"https://www.seatrade-maritime.com/crewing/imo-to-launch-gender-mainstreaming-handbook-on-women-in-maritime-day"},{"code":"HR","title":"해사노동협약(MLC) 채택 20주년… 선원 보호 강화 재다짐","src":"gCaptain","date":"2026-02-23","kSum":"ILO, ICS, ITF는 2006년 채택된 해사노동협약(MLC)의 20주년을 맞아 선원 보호 강화와 선원의 '필수노동자' 공식 인정을 촉구했다. MLC는 약 70개 노동협약을 통합해 임금, 휴식시간, 의료, 송환, 복지에 관한 글로벌 최저기준을 세웠다.","eSum":"The ILO, ICS and ITF marked the 20th anniversary of the Maritime Labour Convention, adopted in 2006, with a renewed push to strengthen protections and formally recognise seafarers as key workers. The MLC consolidated some 70 instruments into a single global baseline covering wages, rest hours, medical care, repatriation and welfare.","kImp":"유기, 피로, 체불임금, 상륙 거부 등 잔존 과제가 지적돼 협약의 실효적 집행이 관건임을 확인시켰다.","eImp":"Persisting problems such as abandonment, fatigue, unpaid wages and denial of shore leave show enforcement remains the decisive factor.","url":"https://gcaptain.com/twenty-years-of-seafarer-protections-maritime-labour-convention-marks-historic-milestone/"},{"code":"HR","title":"WMU '심각한 위기' 경고… 선원 절반이 5년 내 이직 고려","src":"Splash247","date":"2026-01-30","kSum":"세계해사대학(WMU)의 대규모 설문조사에서 과도한 업무량, 만성 스트레스, 열악한 정신건강이 다수 선원을 이탈로 내몰고 있는 것으로 나타났다. 응답자의 약 절반이 향후 5년 내 승선을 그만둘 의향을 밝혔고, 3분의 1은 '심각하고 위험한' 수준의 스트레스를 보였다.","eSum":"A major World Maritime University survey found that excessive workloads, chronic stress and poor mental health are pushing many seafarers toward the exit. Nearly half of respondents said they intend to quit seafaring within five years, and about a third showed 'severe and potentially dangerous' stress levels.","kImp":"정신건강과 이직 의향의 상관관계가 뚜렷해, 근로·휴식 기준 준수와 행정부담 경감이 유지율의 관건으로 부상했다.","eImp":"The strong link between mental health and attrition makes realistic rest standards and reduced admin burden central to retention.","url":"https://splash247.com/world-maritime-university-warns-of-severe-crisis-as-half-of-seafarers-eye-exit-within-five-years/"},{"code":"HR","title":"FrontM, 선원·해양 전문가용 온십 앱 업그레이드","src":"Seatrade Maritime","date":"2026-06-29","kSum":"디지털 플랫폼 FrontM이 선원과 해양 전문가를 위한 온십(onship) 앱을 업그레이드해 선상 통신과 복지 서비스 접근성을 확대했다. 이번 개선은 연결성이 선원 유지와 웰빙의 핵심 요소로 부상하고 있음을 반영한다.","eSum":"Digital platform FrontM has upgraded its onship app for seafarers and maritime professionals, expanding onboard communication and access to welfare services. The update reflects growing recognition that connectivity is a key driver of crew retention and wellbeing.","kImp":"가족과의 소통과 디지털 복지 서비스는 신세대 선원 확보·유지에서 임금 못지않게 중요한 요인으로 자리잡고 있다.","eImp":"Connectivity with family and digital welfare services are becoming as important as pay in attracting and retaining a new generation of seafarers.","url":"https://www.seatrade-maritime.com/crewing/frontm-upgrades-onship-app-for-seafarers-and-maritime-professionals"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ·손해방지","eTitle":"Section 10. HSEQ","items":[{"code":"HSEQ","title":"NorthStandard, 배출통제구역(ECA) 진입 선박 운항 지침 발표","src":"NorthStandard","date":"2026-07-02","kSum":"NorthStandard 손실예방 담당자가 MARPOL Annex VI에 따른 ECA 운항 지침을 발표했다. ECA 진입 전 0.10% 황 함유 연료로의 전환 계산·기록, NOx 인증 유지, 스크러버 사용 요건, 그리고 지중해·캐나다 북극·노르웨이해·북동대서양 등 확대되는 ECA를 정리했다.","eSum":"A NorthStandard Loss Prevention Executive issued operational guidance for vessels entering Emission Control Areas under MARPOL Annex VI. It covers fuel changeover calculations and logging to 0.10% sulphur before entry, NOx certification, scrubber requirements, and the expanding ECAs including the Mediterranean, Canadian Arctic, Norwegian Sea and North-East Atlantic.","kImp":"ECA가 유럽·북미 해역 대부분으로 확대되면서 연료 조달·전환·기록 절차의 사소한 누락도 항만국통제(PSC) 지적과 상당한 벌금으로 이어질 수 있다. 선사는 지역별 추가 규제까지 사전 확인해 규정 위반 리스크를 선제 관리해야 한다.","eImp":"As ECAs expand to cover most European and North American waters, even minor lapses in fuel procurement, changeover or logging can trigger Port State Control findings and substantial fines. Operators must check additional local requirements in advance to pre-empt compliance risk.","url":"https://www.manifoldtimes.com/news/northstandard-issues-operational-guidance-for-vessels-entering-ecas/"},{"code":"HSEQ","title":"IMCA, 호르무즈 해협 재개통에 잠수부 안전 경고… 선체 청소 수요 급증","src":"IMCA","date":"2026-06-24","kSum":"호르무즈 해협 재개통으로 걸프에 발이 묶였던 약 600척의 선체 청소·검사 수요가 30배 이상 급증하자, IMCA가 수중 선체 관리(UWSH) 작업의 위험을 경고했다. UWSH는 잠수 산업에서 사망률이 가장 높은 분야 중 하나로, SCUBA가 아닌 표면공급식 장비와 유자격 인력 사용이 핵심이라고 강조했다.","eSum":"With the reopening of the Strait of Hormuz driving a more than 30-fold jump in demand to clean and inspect around 600 idled vessels, IMCA has warned of the risks of underwater ship husbandry (UWSH) work. UWSH has one of the highest fatality rates in commercial diving, and IMCA stresses using surface-supplied equipment and competent teams rather than SCUBA.","kImp":"장기 정박 후 대량의 선체 오손 제거 작업이 몰리면서 무자격 팀·부적절 장비 사용으로 인한 잠수 사고 위험이 커지고 있다. 선주는 IMCA D082 지침에 따라 유능한 계약자·적정 장비·적절한 감독을 확보해 사망 사고를 예방해야 한다.","eImp":"A surge of hull-fouling removal after prolonged anchorage raises the risk of diving fatalities from unqualified teams and inappropriate equipment. Owners should follow IMCA D082 guidance to ensure competent contractors, suitable equipment and proper supervision to prevent fatal incidents.","url":"https://www.imca-int.com/news-events/imca-news/news/imca-urges-focus-on-diver-safety-amid-rising-demand-for-vessel-maintenance-as-strait-of-hormuz-reopens/"},{"code":"HSEQ","title":"IMCA, 해양구조물 해체 가속에 잠수부 안전 지침(D090) 발표","src":"IMCA","date":"2026-06-03","kSum":"IMCA가 노후 해양구조물 해체·철거 작업의 위험 증가를 경고하며 신규 지침 D090을 발표했다. 애초에 철거를 염두에 두지 않고 설계된 구조물, 부정확한 기록, 변화하는 현장 조건이 상용 잠수에 고위험 환경을 만든다고 지적했다.","eSum":"IMCA has published new guidance (D090) warning that ageing offshore infrastructure is making subsea decommissioning and dismantlement increasingly hazardous. Structures never designed to be removed, incomplete records and changing site conditions create a high-risk environment for commercial diving.","kImp":"2025~2035년 전 세계 해체 비용이 약 810억 달러로 전망되는 가운데, 사고의 상당수가 자산 상태에 대한 '가정'과 낡은 정보 의존에서 비롯된다. '실제 발견된' 조건의 검증과 엄격한 변경관리(MOC)가 고위험 사고 예방의 핵심이다.","eImp":"With global decommissioning spend forecast at around $81bn over 2025-2035, many incidents stem from assumptions about asset condition and reliance on outdated information. Verifying 'as found' conditions and disciplined Management of Change (MOC) are central to preventing high-potential incidents.","url":"https://www.imca-int.com/news-events/imca-news/news/imca-issues-diver-safety-warning-as-global-subsea-decommissioning-accelerates/"},{"code":"HSEQ","title":"Skuld, 점토(clay) 화물의 손실예방 팁… 'Group C지만 액상화 주의'","src":"Skuld (SAFETY4SEA)","date":"2026-05-04","kSum":"Skuld는 IMSBC 코드상 액상화 위험이 없는 Group C로 분류된 점토 화물이 실제로는 위험 거동을 보인 여러 중대 사고와 연관됐다고 경고했다. 수분이 높은 점토는 거친 해상에서 액상화되는 Group A 화물과 유사한 유동 특성을 나타낼 수 있다.","eSum":"Skuld warns that clay cargoes, classified as non-liquefiable Group C under the IMSBC Code, have been linked to several serious incidents where they behaved otherwise. Clay with excessive moisture can exhibit flow characteristics similar to liquefiable Group A cargoes in rough seas.","kImp":"이론적 분류와 실제 거동 간 괴리는 선박 복원성 상실과 전복으로 이어질 수 있는 실질적 위협이다. Skuld는 점토를 잠재적 액상화 화물로 취급하고, 몬순기 강우 중·후 적재를 피하며 수분 함량을 면밀히 관리하도록 권고한다.","eImp":"The gap between theoretical classification and real behaviour is a genuine threat that can lead to loss of stability and capsize. Skuld recommends treating clay as potentially liquefiable, avoiding loading during or after monsoon rain and closely monitoring moisture content.","url":"https://safety4sea.com/skuld-key-loss-prevention-tips-for-clay-cargoes/"},{"code":"HSEQ","title":"NorthStandard: 선원 복지, 지속 개선 위해 '명확한 지표'가 필요하다","src":"NorthStandard (SAFETY4SEA)","date":"2026-06-04","kSum":"NorthStandard는 선원 복지가 실질적으로 개선되려면 성과를 측정할 더 명확한 지표가 필요하다고 지적했다. 정신건강 관련 중대 사건이 업계 전반에서 이어지는 가운데, 정신건강 응급처치 교육 등 조기 개입 수단의 중요성을 강조했다.","eSum":"NorthStandard argues that lasting improvement in crew welfare requires clearer metrics to measure progress. With serious mental-health incidents continuing across the industry, it highlights early-intervention tools such as mental health first-aid training.","kImp":"선원 복지·정신건강은 사고와 이직에 직접 영향을 주는 손실예방 이슈이나, 측정 가능한 지표가 없으면 개선 여부를 검증하기 어렵다. 데이터 기반 지표 도입은 복지 투자의 실효성을 담보하고 인적 리스크를 줄이는 출발점이 된다.","eImp":"Crew welfare and mental health are loss-prevention issues that directly affect incidents and retention, yet without measurable metrics improvement cannot be verified. Adopting data-driven indicators is a starting point to ensure welfare investment works and to reduce human-factor risk.","url":"https://safety4sea.com/cm-northstandard-crew-welfare-needs-clearer-metrics-to-drive-lasting-change/"},{"code":"HSEQ","title":"Britannia P&I, 리스크워치: '육상 작업자의 밀폐구역 진입' 위험 경고","src":"Britannia P&I","date":"2026-03-01","kSum":"Britannia P&I는 리스크워치에서 항만 하역인부·검수원 등 육상 작업자가 선상 밀폐구역에 진입할 때의 위험을 다뤘다. 선원뿐 아니라 방문 육상 인력도 산소 결핍·유독 가스에 노출될 수 있어 진입 통제가 필요하다고 강조했다.","eSum":"In its Risk Watch, Britannia P&I addresses the dangers of shore workers such as stevedores and surveyors entering enclosed spaces on board. It stresses that visiting shore personnel, not only crew, can be exposed to oxygen deficiency and toxic gases and that entry must be controlled.","kImp":"밀폐구역 진입 사고는 반복되는 치명적 위험으로, 특히 절차에 익숙하지 않은 외부 인력이 취약하다. 선박은 대기 측정, 진입허가서, 감시원 배치 등 표준 절차를 방문자에게도 동일하게 적용해 다수 인명 사고를 예방해야 한다.","eImp":"Enclosed-space entry remains a recurring fatal hazard, with external personnel unfamiliar with procedures especially vulnerable. Vessels must apply standard controls -- atmosphere testing, permits-to-work and posted attendants -- equally to visitors to prevent multiple-fatality incidents.","url":"https://britanniapandi.com/wp-content/uploads/2026/03/Risk-Watch-03-2026.pdf"},{"code":"HSEQ","title":"국제 P&I 그룹, 자율운항 선박에 보험 풀링 경로 개방","src":"International Group of P&I Clubs (SAFETY4SEA)","date":"2026-07-16","kSum":"국제 P&I 그룹(IG)이 완전 무인선을 포함한 자율운항 선박에서 발생하는 책임도 그룹의 공동 재보험 풀링 체계에 포함될 수 있음을 확인했다. 이는 신기술 선박에 대한 P&I 보장 경로를 공식적으로 연 조치다.","eSum":"The International Group of P&I Clubs has confirmed that liabilities arising from autonomous vessels, including fully unmanned ships, can now be included within its shared reinsurance pooling arrangements. This formally opens a P&I coverage pathway for these emerging-technology vessels.","kImp":"자율운항선의 책임을 기존 풀링에 편입하면 선주는 보장 공백 없이 신기술을 도입할 수 있으나, 사고 시 책임·인적 개입 부재에 따른 새로운 손실예방 쟁점이 부각된다. 클럽·선사는 자율선의 리스크 평가와 안전 요건 정비를 병행해야 한다.","eImp":"Folding autonomous-vessel liabilities into existing pooling lets owners adopt the technology without coverage gaps, but it surfaces new loss-prevention questions around liability and the absence of human intervention in incidents. Clubs and operators must pair this with robust risk assessment and safety requirements for autonomous ships.","url":"https://safety4sea.com/pi-clubs-open-insurance-pathway-for-autonomous-vessels/"}]},{"code":"KR","type":"news","kTitle":"Section 11. 한국 해운시장","eTitle":"Section 11. Korean Shipping Market","items":[{"code":"KR","title":"양밍, 한화오션에 최대 12억 달러 규모 13,000TEU급 LNG 이중연료 컨선 6척 발주","src":"쉬핑뉴스넷","date":"2026-07-21","kSum":"메리츠증권이 트레이드윈즈를 인용해 대만 선사 양밍해운이 한화오션에 최대 12억 달러 규모의 13,000TEU급 LNG 이중연료 네오파나막스급 컨테이너선 6척을 발주했다고 전했다. 이번 발주는 탄소 배출 절감과 선대 현대화를 위한 것으로, 선박은 동서 항로 주력 노선에 투입될 전망이다.","eSum":"Citing TradeWinds, Meritz Securities reported that Taiwan's Yang Ming ordered six 13,000-TEU LNG dual-fuel neo-panamax containerships from Hanwha Ocean worth up to USD 1.2bn. The order supports emissions reduction and fleet modernization, with the vessels set for main east-west trade lanes.","kImp":"한화오션이 대형 친환경 컨테이너선 수주를 이어가며 상선 부문 수주 모멘텀을 확인시켰다.","eImp":"Confirms Hanwha Ocean's ongoing momentum in large eco-friendly containership orders.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=71244"},{"code":"KR","title":"항만공사 통폐합 본격 가시권...재경부, 빠르면 7월말 통폐합(안) 발표","src":"쉬핑뉴스넷","date":"2026-07-20","kSum":"이재명 정부의 공공기관 통폐합 기조 속에서 재경부가 빠르면 7월말 부산·인천·울산·여수광양 4대 항만공사 통폐합(안)을 발표할 것으로 알려졌다. 항만공사법 개정 등을 고려하면 실제 확정은 빨라야 내년 말로 예상되며, 5개 지역 시민사회단체는 통합 중단과 자율성 강화를 촉구하는 기자회견을 열었다.","eSum":"Amid the Lee Jae-myung administration's push to consolidate public agencies, the finance ministry is reportedly set to unveil a merger plan for the four port authorities (Busan, Incheon, Ulsan, Yeosu-Gwangyang) as early as end-July. Full confirmation is expected no sooner than end-2027 given required legal amendments, while civic groups from five regions held a press conference urging a halt and greater autonomy.","kImp":"국내 항만 거버넌스 구조를 바꿀 수 있는 4대 항만공사 통폐합 논의가 실행 국면에 진입했다.","eImp":"A potential reshaping of Korea's port governance as the four-port-authority merger debate enters an execution phase.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=71231"},{"code":"KR","title":"현대글로비스, 2분기 역대 최대 매출...유가 상승에 영업익은 감소","src":"머니투데이","date":"2026-07-23","kSum":"현대글로비스는 2분기 매출액이 전년 대비 15.8% 증가한 8조7,054억원으로 분기 역대 최대를 기록했다고 밝혔으나, 유가 상승과 운임 하락 영향으로 영업이익은 8.1% 감소한 4,950억원에 그쳤다. 해운 부문 매출은 20.9% 늘었지만 중동 리스크에 따른 유가 상승으로 영업이익은 34.6% 감소했다.","eSum":"Hyundai Glovis posted record quarterly revenue of KRW 8.71tn in Q2, up 15.8% year-on-year, but operating profit fell 8.1% to KRW 495bn on higher fuel costs and softer freight rates. Shipping revenue rose 20.9% while its operating profit dropped 34.6% due to oil price gains tied to Middle East risk.","kImp":"PCTC 대형 선사의 외형 성장에도 유가 변수로 수익성이 흔들리는 국면을 보여준다.","eImp":"Shows how oil price volatility pressures margins even as the major PCTC carrier grows revenue.","url":"https://www.mt.co.kr/industry/2026/07/23/2026072315470565965"},{"code":"KR","title":"현대글로비스 \"중국차 수출 증가에 선복 부족 계속...3분기 수익성 개선\"","src":"헤럴드경제","date":"2026-07-23","kSum":"현대글로비스는 2분기 실적 컨퍼런스콜에서 중국 완성차 수출 급증과 신조선 인도까지 3~5년이 걸리는 점을 감안하면 자동차운반선(PCTC) 선복 부족이 당분간 이어질 것이라고 전망했다. 유가 영향에 따른 비용 반영 시차로 3분기부터 수익성이 회복될 것이며, 연내 1만 CEU급 초대형 PCTC 6척 확보로 선대를 110척 이상으로 확대할 계획이라고 밝혔다.","eSum":"On its Q2 earnings call, Hyundai Glovis said the PCTC tonnage shortage will persist given surging Chinese car exports and 3-5 year newbuilding lead times. Profitability should recover from Q3 as fuel costs feed into rates, and the company plans to expand its fleet beyond 110 vessels this year with six ultra-large 10,000-CEU car carriers.","kImp":"PCTC 시장의 구조적 선복 부족 지속 전망은 자동차운반선 운임 강세를 뒷받침한다.","eImp":"A structural PCTC tonnage shortfall outlook underpins continued firmness in car-carrier rates.","url":"https://biz.heraldcorp.com/article/10818188"},{"code":"KR","title":"조선3사, 2분기 영업이익 2조원 육박 전망...고선가 효과에 전년비 80%↑","src":"디지털데일리","date":"2026-07-14","kSum":"에프앤가이드에 따르면 HD현대중공업·한화오션·삼성중공업의 2분기 합산 영업이익은 1조8,929억원으로 전년 동기 대비 80.6% 증가할 것으로 전망된다. 고선가 선박 매출 반영과 LNG선 중심의 선종 개선, 생산성 향상이 실적을 견인하며 연간 합산 영업이익도 7조1,880억원으로 76.7% 증가가 예상된다.","eSum":"Per FnGuide, the combined Q2 operating profit of HD Hyundai Heavy, Hanwha Ocean and Samsung Heavy is projected at KRW 1.89tn, up 80.6% year-on-year. High-priced newbuilding deliveries, an LNG-carrier-heavy mix and productivity gains drive the surge, with full-year combined operating profit seen up 76.7% at KRW 7.19tn.","kImp":"국내 조선 빅3의 고선가 슈퍼사이클 수익성이 실적으로 본격 확인되는 국면이다.","eImp":"Korea's big-three shipbuilders' high-price supercycle profitability is now showing up in earnings.","url":"https://www.ddaily.co.kr/page/view/2026071416180738786"},{"code":"KR","title":"해수부, 닻 올리는 북극항로 운항·해양수도 육성에 '다 걸었다'","src":"머니투데이","date":"2026-07-16","kSum":"해양수산부가 하반기 주요 업무계획에서 올해 첫 시범운항에 나서는 북극항로 개척과 해양수도 육성 투자에 집중하겠다고 밝혔다. 상반기 성과를 기반으로 북극항로 개척, 민생 안정, 미래 해양산업 발굴, 해양수산 인공지능 전환(AX)과 청년 대책에 정책 역량을 집중할 계획이다.","eSum":"In its H2 work plan, the Ministry of Oceans and Fisheries said it will concentrate on opening the Arctic route, which starts its first pilot voyage this year, and on nurturing a 'maritime capital.' Building on first-half results, it will focus policy capacity on the Arctic route, livelihood stability, future ocean industries, maritime AI transformation and youth measures.","kImp":"북극항로 시범운항 등 정부의 해양·해운 정책 방향이 하반기 국적선사 전략에 영향을 준다.","eImp":"Government maritime policy direction, including the Arctic route pilot, shapes Korean carriers' H2 strategy.","url":"https://www.mt.co.kr/economy/2026/07/16/2026071609564398712"},{"code":"KR","title":"삼성중공업, 원유운반선 2척 2849억원 수주...5년 만에 연간 수주 '100억달러' 돌파","src":"디지털데일리","date":"2026-07-08","kSum":"삼성중공업이 원유운반선 2척을 2,849억원에 수주하며 5년 만에 연간 수주액 100억 달러를 돌파했다. LNG선과 FLNG 중심의 고부가 선종 수주가 이어지면서 올해 연간 수주 목표 달성에 근접했다.","eSum":"Samsung Heavy Industries won an order for two crude oil tankers worth KRW 284.9bn, pushing its annual order intake past USD 10bn for the first time in five years. High-value LNG carriers and FLNG orders continue, bringing the yard close to its full-year target.","kImp":"삼성중공업이 연간 수주 100억달러를 조기 달성하며 조선 수주 호조를 재확인했다.","eImp":"Samsung Heavy's early USD 10bn order milestone reaffirms the strength of Korea's shipbuilding order flow.","url":"https://www.ddaily.co.kr/page/view/2026070810474299972"}]},{"code":"INS","type":"news","kTitle":"Section 12. 해상보험 (H&M)","eTitle":"Section 12. Marine Insurance (H&M)","items":[{"code":"INS","title":"호르무즈 전쟁위험 선체보험료, 선가의 3~10%까지 급등","src":"gCaptain","date":"2026-07-24","kSum":"미국-이란 양해각서(MoU) 붕괴로 호르무즈 해협 긴장이 재격화되면서, 위기 이전 선가의 1% 미만이던 전쟁위험 선체(hull war) 보험료가 3~10%까지 치솟았다. 1억 달러 유조선 기준 단일 통항 보험료가 약 25만 달러에서 최대 1,000만 달러로 뛰었다.","eSum":"As the US-Iran memorandum of understanding unraveled and Strait of Hormuz tensions reignited, war-risk hull premiums surged from a nominal fraction of one percent to between three and ten percent of a vessel's insured value. For a $100 million tanker that is the difference between roughly $250,000 and as much as $10 million for a single transit.","kImp":"선체 전쟁위험 요율이 유가와 공격 빈도를 따라 롤러코스터처럼 움직이며, H&M 인수기관과 선주 모두 요율 변동성 관리가 최대 현안으로 부상했다. LMA는 보험이 여전히 가용하며 통항 감소는 보험 부재가 아닌 안전 우려 때문이라고 강조했다.","eImp":"Hull war rates are tracking oil prices and the pace of attacks like a roller coaster, making rate volatility the central concern for both H&M underwriters and owners. The LMA stresses cover remains available and that reduced transits reflect crew-safety judgments, not an absence of insurance.","url":"https://gcaptain.com/hormuz-on-a-knife-edge-shipping-pays-the-price-as-the-iran-u-s-ceasefire-unravels/"},{"code":"INS","title":"마시(Marsh) \"호르무즈 전쟁위험 요율 선가의 3~10%\"…IMO-IUMI 공방","src":"The National","date":"2026-07-17","kSum":"마시의 마커스 베이커 글로벌 해상보험 총괄은 호르무즈 전쟁위험 요율이 선가의 3~10% 범위에서 형성되고 있으며, 전쟁 이전(약 0.25%) 대비 극적으로 상승했다고 밝혔다. IMO 사무총장이 고가의 보험료를 비판하자 IUMI는 \"보험은 문제의 일부가 아니라 해법의 일부\"라며 반박했다.","eSum":"Marsh global head of marine Marcus Baker said Hormuz war-risk rates now range between 3% and 10% of hull value, a huge jump from the roughly 0.25% seen before the war. After the IMO secretary-general criticized high premiums, IUMI hit back that marine insurance is \"part of the solution, not part of the problem.\"","kImp":"요율이 북측(이란) 통항이냐 남측(오만) 통항이냐, 미국·영국·이스라엘 연계 선박이냐에 따라 크게 달라지며, 브로커와 인수기관의 리스크 세분화·제재 준수 부담이 커졌다. 선체 전쟁위험 시장의 요율 정합성 부재가 선주 비용 예측을 어렵게 만든다.","eImp":"Pricing hinges on whether a ship takes the northern Iranian or southern Omani passage and whether it has a US/UK/Israeli nexus, sharpening brokers' and underwriters' burden on risk segmentation and sanctions compliance. Inconsistent rating across the hull war market makes owner cost forecasting difficult.","url":"https://www.thenationalnews.com/business/2026/07/17/war-risk-shipping-premium-surges-again-as-tensions-escalate-at-strait-of-hormuz/"},{"code":"INS","title":"후티 공격에 남부 홍해 전쟁위험 보험료 하루 새 두 배로","src":"Insurance Journal","date":"2026-07-23","kSum":"예멘 후티가 사우디 유조선을 공격하자 남부 홍해 통항 전쟁위험 보험료가 화요일 0.75%에서 목요일 선가의 1% 이상으로 하루 만에 두 배가 됐고, 사우디 연계 선박은 최대 3%까지 호가됐다. 사우디에 대한 후티의 해상 봉쇄 선언으로 호르무즈에 이어 두 번째 요충지 리스크가 겹쳤다.","eSum":"After Yemen's Houthis struck Saudi tankers, indicative war-risk premiums for southern Red Sea voyages doubled to over 1% of a ship's value on Thursday from around 0.75% on Tuesday, with Saudi-linked ships quoted as high as 3%. The Houthi naval blockade on Saudi Arabia adds a second chokepoint risk on top of the Strait of Hormuz.","kImp":"선주들이 호르무즈와 바브엘만데브 두 개 요충지 리스크를 동시에 떠안게 되면서, 항로별·선주 국적별로 차등화된 전쟁위험 요율이 H&M 시장 전반의 비용 구조를 재편하고 있다. 짧은 7일 항해에도 수십만 달러의 추가 비용이 발생한다.","eImp":"Owners now face heightened risk through two chokepoints at once, and route- and nationality-differentiated war-risk rates are reshaping cost structures across the wider H&M market. Even small rate moves add hundreds of thousands of dollars to a single seven-day voyage.","url":"https://www.insurancejournal.com/news/international/2026/07/23/878788.htm"},{"code":"INS","title":"로이즈, 처브 주도 호르무즈 전쟁위험 컨소시엄 출범…선체·P&I 각 2억 달러 담보","src":"Reinsurance News","date":"2026-06-19","kSum":"로이즈가 처브(Chubb)를 리드 인수자로 하는 새 해상 전쟁위험 컨소시엄을 출범해 호르무즈 통항 선박·화물에 추가 담보력을 제공한다. 선체와 P&I에 각각 최대 2억 달러, 화물에 별도 2억 달러의 담보력을 원수(primary)로 제공한다.","eSum":"Lloyd's launched a new marine war-risk consortium led by Chubb to provide additional capacity for vessels and cargo transiting the Strait of Hormuz. It issues primary policies with up to $200 million of capacity each for hull and P&I risks, plus a further $200 million dedicated to cargo.","kImp":"지정학 위기 속 담보력 부족 우려에 로이즈 시장이 전문 인수역량을 신속히 결집하는 사례로, 선체 전쟁위험 담보의 시장 접근성과 깊이를 확대한다. 처브는 앞서 미 DFC의 400억 달러 걸프 해상 재보험 기구도 주도한 바 있다.","eImp":"It is a case of the Lloyd's market rapidly mobilizing specialist capacity amid capacity fears during a geopolitical crisis, broadening the depth and accessibility of hull war-risk cover. Chubb also leads the DFC-backed multi-billion-dollar Gulf Maritime Insurance Facility.","url":"https://www.reinsurancene.ws/lloyds-unveils-chubb-led-war-risk-insurance-facility-for-vessels-in-strait-of-hormuz/"},{"code":"INS","title":"갤러거 \"노후 선대·신규 담보력이 선체보험 가격전쟁 지속시켜\"","src":"Insurance Business","date":"2025-12-05","kSum":"갤러거 스페셜티 분석에 따르면 선체·기관(H&M) 시장은 기술적·지정학적 압력에도 여전히 치열한 가격 경쟁 상태다. 2024년 세계 선체보험료는 3.5% 늘어난 96.7억 달러, 선대 가치는 4% 증가한 1.54조 달러였으나 평균 선령이 22년을 넘어섰다.","eSum":"According to Gallagher Specialty, the hull and machinery market remains highly competitive despite mounting technical and geopolitical pressures. Global hull premiums rose 3.5% in 2024 to $9.67 billion and fleet values grew 4% to $1.54 trillion, while the average fleet age now exceeds 22 years.","kImp":"신디케이트 318·K2 루비콘 등 런던發 신규 담보력이 2026년까지 요율 하방 압력을 이어가는 가운데, 철강·인건비·수리비 인플레이션이 전손·손해 심도를 끌어올려 H&M 수익성이 취약하다. 노후 기관 리스크가 구조적 부담으로 부각된다.","eImp":"New London capacity such as Syndicate 318 and K2 Rubicon keeps downward rate pressure into 2026, while steel, labor and repair-cost inflation lifts total-loss and claims severity, leaving H&M profitability fragile. Aging machinery is emerging as a structural concern.","url":"https://www.insurancebusinessmag.com/us/news/marine/aging-fleets-new-capacity-keep-marine-hull-market-locked-in-price-war--gallagher-559134.aspx"},{"code":"INS","title":"IUMI 2025 통계보고서…선체·적하 안정, 해양에너지 8% 감소","src":"Insurance Business","date":"2025-11-04","kSum":"IUMI 2025 통계보고서에 따르면 2024년 세계 해상보험료는 1.5% 증가한 399.2억 달러였고, 선체·적하 부문이 견조한 반면 해양에너지는 7.9% 감소했다. 대양 선체보험료는 3.5% 늘어난 96.7억 달러로 유럽이 53%를 점유하며 시장을 주도했다.","eSum":"IUMI's 2025 Stats Report shows global marine premiums rose 1.5% to $39.92 billion in 2024, with hull and cargo holding firm while offshore energy fell 7.9%. Ocean hull premiums increased 3.5% to $9.67 billion, with Europe dominating at a 53% share.","kImp":"선체·적하의 안정에도 IUMI는 지정학 긴장, 기후 리스크, 환율, 노후 선대를 향후 실적의 역풍으로 지목했다. 개정된 IUMI 선체 인플레이션 지수와 1.74만 건 이상의 주요손해 DB가 인수 규율 강화의 근거로 활용된다.","eImp":"Despite hull and cargo stability, IUMI flags geopolitical tension, climate risk, currency swings and aging fleets as headwinds for future results. Its revised Hull Inflation Index and Major Claims Database of over 17,400 records support tighter underwriting discipline.","url":"https://www.insurancebusinessmag.com/uk/news/marine/iumi-report-hull-and-cargo-insurance-maintain-stability-as-offshore-energy-declines-555242.aspx"},{"code":"INS","title":"LMA \"호르무즈 통항 감소는 보험 부재 아닌 안전 우려 때문\"","src":"Reinsurance News","date":"2026-03-26","kSum":"로이즈 시장협회(LMA)는 호르무즈 통항 감소가 보험 가용성 문제가 아니라 선주·선장의 안전 판단 때문이라고 명확히 했다. 선체 전쟁위험은 평시 명목 수준의 저렴한 보험료를 유지하다 리스크 상승 시 재산정되는 통지(notification) 메커니즘으로 작동한다.","eSum":"The Lloyd's Market Association clarified that reduced Strait of Hormuz traffic stems from crew and vessel safety judgments by owners and masters, not insurance availability. Hull war risk works through a well-understood notification mechanism that keeps premiums near-notional in peacetime and reprices them when risk rises.","kImp":"적하·선체 전쟁위험은 계약상 취소통지 후 대부분 재산정·재개(buyback)되는 구조로, 언론이 보도한 '보험 취소'는 원수 선체와 용선자 책임 담보를 혼동한 것이라는 점을 시장이 명확히 했다. 조사에서 인수기관의 88%가 여전히 국제 선체 전쟁위험 인수 의향을 유지했다.","eImp":"Cargo and hull war cover is typically repriced and reinstated via buyback after a contractual cancellation notice, and the market clarified that reported 'cancellations' conflated primary hull war with charterers' liability extensions. An LMA survey found 88% of participants still had appetite to write international hull war risks.","url":"https://www.reinsurancene.ws/safety-concerns-not-insurance-availability-halting-strait-of-hormuz-lma-clarifies/"},{"code":"INS","title":"이란 분쟁 확산에 해상보험료 최대 1,000% 급등…선체 전쟁시장 즉각 반응","src":"Insurance Journal","date":"2026-03-06","kSum":"걸프 분쟁이 확산되면서 전쟁위험 해상보험료가 일부 항로에서 1,000% 이상 급등하며 호르무즈 통항을 사실상 마비시켰다. 아온(Aon)은 \"집중손해 리스크로 선체 전쟁시장이 가장 즉각적으로 반응했다\"고 평가했고, 마시는 요율이 선가의 1~1.5% 수준을 오간다고 밝혔다.","eSum":"As the Gulf conflict widened, war-risk marine premiums surged by more than 1,000% on some routes, effectively paralyzing Strait of Hormuz traffic. Aon said the hull war market reacted most immediately due to concentrated-loss risk, while Marsh estimated ratings trending around 1% to 1.5% of vessel value.","kImp":"약 1,000척(선체가치 250억 달러 이상)이 걸프 수역에 집중돼 있어 대형 집중손해 우려가 원수 인수기관과 재보험자의 담보·요율 판단을 압박한다. 제프리스는 최소 7척 피해로 산업 손실이 최대 17.5억 달러에 이를 수 있다고 추산했다.","eImp":"With roughly 1,000 vessels worth over $25 billion in hull value concentrated in the Gulf, fears of a large aggregated loss pressure primary underwriters' and reinsurers' capacity and rating decisions. Jefferies estimated potential industry losses of up to $1.75 billion from at least seven damaged vessels.","url":"https://www.insurancejournal.com/news/international/2026/03/06/860842.htm"}]},{"code":"PNI","type":"news","kTitle":"Section 13. P&I 클럽","eTitle":"Section 13. P&I Clubs","items":[{"code":"PNI","title":"NorthStandard, 조나단 오크를 선임 전쟁위험 언더라이터로 영입","src":"NorthStandard (MarineLink)","date":"2026-07-07","kSum":"NorthStandard가 UK War Risks Club 출신의 조나단 오크(Jonathan Oak)를 선임 전쟁위험(War) 언더라이터로 영입해 Hull & War 팀을 강화했다. 오크는 James Sutton 헐·전쟁위험 총괄에게 보고하며 고위험 해역 운항 선주 대상 인수 역량을 확대한다.","eSum":"NorthStandard has appointed Jonathan Oak, formerly of the UK War Risks Club, as Senior War Underwriter to strengthen its Hull & War team. Oak reports to James Sutton, Head of Hull & War, and expands underwriting capacity for owners trading in high-risk areas.","kImp":"홍해·흑해 등 지정학적 긴장이 이어지는 가운데 클럽들의 전쟁위험 인수 역량 강화는 고위험 해역 운항 선주의 담보 확보에 직접적 영향을 준다.","eImp":"With geopolitical tensions persisting in areas like the Red Sea and Black Sea, clubs bolstering war-risk underwriting capacity directly affects cover availability for owners trading high-risk waters.","url":"https://www.marinelink.com/news/jonathan-oak-appointed-senior-war-541044"},{"code":"PNI","title":"American Club, 회람 16/26호로 이사회 선출 및 2025년 연차보고 발표","src":"American Club","date":"2026-07-14","kSum":"American Club은 회람 16/26호를 통해 Robert D. Bondurant를 이사회 의장, John A. Witte Jr.를 부의장으로 선출했다고 발표했다. 또한 2025년 12월 31일 마감 회계연도 연차보고서를 연차총회에서 제출하며 2024년 풀 클레임 대형화 압박에도 개선 흐름을 보였다고 밝혔다.","eSum":"The American Club issued Circular No. 16/26 announcing the election of Robert D. Bondurant as Chair and John A. Witte Jr. as Deputy Chair of the Board. The Annual Report and Accounts for the year ended 31 December 2025 were presented, showing improvement despite pressure from larger 2024 Pool claims.","kImp":"American Club의 지배구조 변화와 재무 방향은 미국계 선주 및 클럽 회원사의 향후 인수정책과 클럽 안정성 판단에 참고가 된다.","eImp":"The American Club's governance changes and financial trajectory inform members and US owners about the club's stability and future underwriting stance.","url":"https://allaboutshipping.co.uk/2026/07/14/american-pi-club-circular-no-16-26/"},{"code":"PNI","title":"West of England, 해상 사이버보험사 Astaara 지분 인수","src":"West of England P&I","date":"2026-06-16","kSum":"West of England P&I는 2026년 6월 16일 런던 소재 신생 해상 사이버보험 제공업체 Astaara Company Limited의 상당한 지분을 인수한다고 밝혔다. 이는 전통 P&I 담보를 넘어 사이버 리스크 영역으로 사업을 확장하려는 전략적 움직임이다.","eSum":"West of England P&I announced on 16 June 2026 that it will acquire a significant stake in Astaara Company Limited, a fledgling London-based marine cyber insurance provider. The move marks a strategic expansion beyond traditional P&I cover into cyber risk.","kImp":"선박 디지털화로 사이버 위협이 커지는 가운데 P&I 클럽의 사이버보험 진출은 회원 선주에게 새로운 담보 옵션을 제시하는 업계 흐름을 보여준다.","eImp":"As vessel digitalization heightens cyber threats, a P&I club moving into cyber insurance signals an industry trend offering members new cover options.","url":"https://www.insurancebusinessmag.com/uk/news/marine/west-of-england-pandi-builds-capital-buffer-575348.aspx"},{"code":"PNI","title":"Steamship Mutual, 2026 경영 하이라이트 발표…재무 견조·회원 중심 강조","src":"Steamship Mutual","date":"2026-06-20","kSum":"Steamship Mutual은 2026 경영 하이라이트를 발표하며 클레임 증가와 지정학적 불확실성 속에서도 회복력과 안정성을 보였다고 밝혔다. 투자자산 15억 달러, 자유준비금 5.78억 달러, S&P A등급, 솔벤시II 자본비율 220%, 합산비율 112%를 기록했다.","eSum":"Steamship Mutual published its 2026 Management Highlights, demonstrating resilience and stability amid heightened claims and geopolitical uncertainty. It reported $1.5bn in invested assets, $578m free reserves, an S&P A rating, a 220% Solvency II ratio and a 112% combined ratio.","kImp":"합산비율 112%는 언더라이팅 손실을 시사하나 강한 준비금과 투자수익이 이를 완충하는 구조로, 회원 선주의 클럽 안정성 평가에 중요하다.","eImp":"A 112% combined ratio implies underwriting loss, but strong reserves and investment returns cushion it, a key data point for members assessing club stability.","url":"https://www.steamshipmutual.com/press-release-steamship-mutual-publishes-2026-management-highlights-demonstrating-strength"},{"code":"PNI","title":"Britannia P&I 아카데미, 신규 런던 사무소에서 2026 프로그램 재개","src":"Britannia P&I","date":"2026-06-16","kSum":"Britannia P&I는 6월 15~19일 신임 CEO Mike Hall 체제 하에 새 런던 사무소에서 첫 아카데미를 개최했다. 전 세계 회원사에서 32명의 대표단이 참석해 언더라이팅, 화물 클레임, 손실예방, 제재, 충돌·구조 등을 다뤘다.","eSum":"Britannia P&I held its Academy from 15-19 June, the first at its new London office under newly appointed CEO Mike Hall. Thirty-two delegates from the global membership covered underwriting, cargo claims, loss prevention, sanctions, collisions and salvage.","kImp":"클럽 주관 회원 교육 프로그램은 선주사 실무자의 P&I 리스크 이해도를 높여 클레임 예방과 클럽-회원 관계 강화에 기여한다.","eImp":"Club-led member training raises owners' staff understanding of P&I risks, aiding claims prevention and strengthening club-member relationships.","url":"https://britanniapandi.com/2026/06/britannia-pi-academy-returns-for-2026-programme-in-new-london-office/"},{"code":"PNI","title":"UK P&I Club, 회람 09/26호로 TT Club과의 합병 진전 발표","src":"UK P&I Club","date":"2026-05-22","kSum":"UK P&I Club은 회람 09/26호에서 두 클럽이 6월 초 합병을 공식 확정하는 기본계약(framework agreement)에 서명할 예정이며 합병은 2027년 2월 20일 완료될 것이라고 밝혔다. 아울러 클럽은 자유준비금이 5.86억 달러로 사상 최고치에 도달하는 등 큰 폭의 흑자를 기록했다.","eSum":"UK P&I Club's Circular 09/26 stated the two clubs intend to sign a framework agreement in early June committing to the merger, expected to conclude on 20 February 2027. The Club also delivered a significant surplus, with free reserves rising to a record $586m.","kImp":"UK P&I와 TT Club의 합병은 International Group 내 대형 재편으로, 회원 선주의 담보 범위·보험료·서비스에 중장기적 영향을 미친다.","eImp":"The UK P&I-TT Club merger is a major International Group restructuring, with medium-to-long-term implications for members' cover scope, premiums and service.","url":"https://www.ukpandi.com/news-and-resources/circulars/article/circular-09/26-update-from-the-board"},{"code":"PNI","title":"Gard, 이란·페르시아만 전쟁위험 재보험 해지 통지 접수","src":"Gard","date":"2026-03-01","kSum":"Gard는 회람 01/2026호를 통해 Gard P&I(Bermuda), Assuranceforeningen Gard 등 관련 법인들이 이란 및 페르시아/아라비아만 전쟁위험과 관련해 재보험사로부터 담보 해지 통지를 받았다고 밝혔다. 이는 해당 해역 전쟁위험 담보 재조정을 예고한다.","eSum":"Gard's Circular 01/2026 stated that Gard P&I (Bermuda), Assuranceforeningen Gard and related entities received Notice of Cancellation from reinsurers regarding war risks in Iran and the Persian/Arabian Gulf. This signals a repricing or restructuring of war-risk cover in the region.","kImp":"페르시아만 운항 선주는 전쟁위험 담보 조건 변경 및 추가 보험료 가능성에 대비해야 하며, 지정학 리스크가 담보에 직접 반영되는 사례다.","eImp":"Owners trading the Persian Gulf must prepare for altered war-risk terms and possible additional premiums, a clear case of geopolitical risk feeding into cover.","url":"https://gard.no/en/circulars/notice-of-cancellation-for-war-risks/"},{"code":"PNI","title":"Japan P&I Club, 2026 정책연도 규칙 개정 시행","src":"Japan P&I Club","date":"2026-02-04","kSum":"Japan P&I Club은 회람 25-021호(2026년 2월 4일)로 2026 규칙(Rules 2026) 개정 내용을 발표했으며 개정은 2026년 2월 20일 정오(GMT)부터 발효됐다. 러시아·우크라이나·벨라루스 인근 해역 운항 선박의 초과 전쟁담보 한도가 1억 달러에서 1.25억 달러로 상향됐다.","eSum":"Japan P&I Club announced its Rules 2026 amendments via Circular No. 25-021 dated 4 February 2026, effective from noon GMT on 20 February 2026. The Excess War cover limit for vessels navigating around Russia, Ukraine and Belarus was raised from US$100m to US$125m.","kImp":"전쟁담보 한도 상향은 흑해·발트해 운항 선주의 담보 안전망을 확대하며, 규칙 개정은 회원사의 담보 조건 재확인을 요한다.","eImp":"Raising the war-cover limit widens the safety net for owners trading the Black and Baltic Seas, and the rule change requires members to review their cover terms.","url":"https://www.piclub.or.jp/en/news/43532"}]},{"code":"VET","type":"news","kTitle":"Section 14. 베팅·검사","eTitle":"Section 14. Vetting & Inspection","items":[{"code":"VET","title":"OCIMF 2026 연차보고서 발간 – SIRE 2.0 시행 1년, 차세대 베팅체계와 인적요소 강조","src":"MaritimeCyprus","date":"2026-06-07","kSum":"OCIMF가 2026 연차보고서 'Charting Safe Seas'를 발간하며 SIRE 2.0 도입 1년의 성과와 문화적 전환을 조명했다. 디지털 혁신과 인적요소(human element)의 결합을 중심으로 차세대 베팅 프레임워크를 통한 운영 회복력 강화를 강조했다.","eSum":"OCIMF released its 2026 Annual Report 'Charting Safe Seas', reflecting on the first year of SIRE 2.0 as a significant milestone signalling a culture shift. It centres on the intersection of digital innovation and the irreplaceable human element, advocating next-generation vetting frameworks to fortify operational resilience.","kImp":"SIRE 2.0가 안정적으로 정착했음을 공식 확인한 것으로, 탱커 선사는 인적요소 중심 평가와 디지털 베팅 강화 기조에 맞춰 승무원 역량 관리와 절차를 준비해야 한다.","eImp":"It confirms SIRE 2.0 has bedded in without major disruption, signalling tanker operators must align crew-competency management and procedures with an increasingly human-element-focused, digitalised vetting regime.","url":"https://maritimecyprus.com/2026/06/07/ocimf-annual-report-2026-charting-safe-seas/"},{"code":"VET","title":"탱커 화물탱크 청결도 검증 종합 가이드 – 베팅·용선 검사의 핵심 절차","src":"MaritimeCyprus","date":"2026-05-31","kSum":"West P&I 손실예방 자료를 인용해 탱커 화물탱크 청결도 검증(물리적 탱크검사, 월워시테스트 WWT, 세척수분석 WWA) 절차를 정리했다. 검사는 선측·용선주·화주 대표가 공동으로 수행하며 코팅 상태, 히팅코일, 펌프 석션웰 등 세부 점검항목을 제시했다.","eSum":"Citing a West P&I loss-prevention bulletin, the guide details tank-cleanliness verification for tankers via physical inspection, wall wash tests (WWT) and wash water analysis (WWA). Inspections are conducted jointly with vessel, charterer and cargo-owner representatives, covering coating condition, heating coils and pump suction wells.","kImp":"탱크 청결도 검사는 용선 수락 여부를 좌우하는 실질적 베팅 관문으로, 결함 기록과 사전 점검이 화물작업 중 사고와 클레임을 예방하는 데 직결된다.","eImp":"Tank inspection is a practical vetting gate that can decide charter acceptance; documenting defects beforehand directly reduces the risk of incidents and claims during cargo operations.","url":"https://maritimecyprus.com/2026/05/31/tank-cleanliness-verification-for-tankers-a-comprehensive-overview/"},{"code":"VET","title":"INTERCARGO, 벌크선 STS 이송 가이드라인 발간 – 2026년 업계 이정표","src":"MaritimeCyprus","date":"2026-05-17","kSum":"INTERCARGO가 벌크선 선박간(STS) 화물이송을 위한 가이드라인을 발간했다. 계획·위험평가·장비·소통 등 STS 작업 전 과정의 모범관행을 표준화해 벌크 부문 검사·베팅 요구에 대응한다.","eSum":"INTERCARGO published guidelines for ship-to-ship (STS) transfer operations on bulk carriers, described as a 2026 industry milestone. They standardise best practice across planning, risk assessment, equipment and communication for STS operations in the dry-bulk sector.","kImp":"RISQ 3.2에 STS 운영 섹션이 신설된 상황과 맞물려, 벌크선 STS 관련 검사·베팅 항목 대비의 기준 문서로 활용된다.","eImp":"Coming as RISQ 3.2 adds a dedicated STS section, the guidelines serve as a reference for preparing bulk carriers for STS-related inspection and vetting items.","url":"https://maritimecyprus.com/2026/05/17/intercargo-sts-transfer-guidelines-for-bulk-carriers-a-2026-industry-milestone/"},{"code":"VET","title":"INTERCARGO, 2026 벌크선 사고보고서 발간 – 검사·안전 우선순위 제시","src":"MaritimeCyprus","date":"2026-06-11","kSum":"INTERCARGO가 2026년 벌크선 사상사고 보고서를 발간해 최근 10년간 벌크선 전손·인명피해 원인을 분석했다. 화물 액상화, 침수, 구조결함 등 주요 손실 유형과 재발방지 권고를 담았다.","eSum":"INTERCARGO published its 2026 Bulk Carrier Casualty Report, analysing causes of total losses and fatalities over the past decade. It highlights key loss categories such as cargo liquefaction, flooding and structural failure, with recommendations to prevent recurrence.","kImp":"벌크선 사고 데이터는 RightShip의 선령별 검사 강화와 RISQ 항목 설계의 근거가 되며, 선주가 베팅 대비 취약점을 선제 점검하는 기준이 된다.","eImp":"Bulk casualty data underpins RightShip's age-based inspection tightening and RISQ item design, giving owners a basis to pre-empt vulnerabilities ahead of vetting.","url":"https://maritimecyprus.com/2026/06/11/intercargo-bulk-carrier-casualty-accident-report-2026/"}]},{"code":"CLASS","type":"news","kTitle":"Section 15. 선급","eTitle":"Section 15. Classification Societies","items":[{"code":"CLASS","title":"한국원자력연·삼성중공업 SMR 추진 컨테이너선, ABS 기본승인(AiP) 획득","src":"에너지데일리","date":"2026-07-16","kSum":"한국원자력연구원(KAERI)이 KRISO·삼성중공업과 공동개발한 용융염원자로(MSR) 적용 1만5000TEU급 컨테이너선 개념설계가 미국선급협회(ABS)로부터 기본승인(AiP)을 획득했다. 무탄소 원자력 추진 상선 상용화의 첫 관문을 통과한 것이다.","eSum":"KAERI, together with KRISO and Samsung Heavy Industries, obtained an ABS Approval in Principle for the concept design of a 15,000 TEU containership powered by a molten salt reactor (MSR). It marks the first regulatory milestone toward commercial carbon-free nuclear-powered merchant ships.","kImp":"원자력 추진 상선이 주요 선급의 개념 검증을 통과하면서 SMR 해양 적용 규정화 논의가 가속된다. 향후 IMO·IAEA 규정 정비와 연동돼 차세대 무탄소 선박 경쟁의 판도를 좌우할 수 있다.","eImp":"With a nuclear merchant ship passing class concept review, rule-making for marine SMR application will accelerate. Tied to future IMO/IAEA frameworks, it could reshape the next-generation zero-carbon vessel race.","url":"https://www.energydaily.co.kr/news/articleView.html?idxno=201469"},{"code":"CLASS","title":"삼성중공업 선박 OS 'SAS', DNV·ClassNK 형식승인 획득","src":"FETV","date":"2026-07-20","kSum":"삼성중공업의 선박 데이터 플랫폼 'SAS'가 노르웨이선급(DNV)의 D-INF(S) 형식승인과 일본해사협회(ClassNK) 형식승인을 획득했다. 선박 데이터 인프라가 국제표준에 부합함을 복수 선급이 검증한 것이다.","eSum":"Samsung Heavy Industries' onboard data platform 'SAS' received DNV's D-INF(S) type approval and ClassNK type approval. The certifications verify that the ship's data infrastructure meets international standards.","kImp":"디지털 선박 데이터 인프라에 대한 복수 선급의 형식승인은 스마트십·자율운항 데이터 신뢰성의 기준점이 된다. 조선사 자체 선박 OS 경쟁이 선급 인증을 축으로 본격화되고 있다.","eImp":"Multi-class type approval of digital ship-data infrastructure sets a benchmark for smart-ship and autonomous data reliability. Shipbuilders' rival onboard operating systems are now competing around class certification.","url":"https://www.fetv.co.kr/news/articleView.html?idxno=306637"},{"code":"CLASS","title":"이글루코퍼레이션, ABS로부터 IACS UR E27 해사 사이버보안 인증 추가 획득","src":"한스경제","date":"2026-07-23","kSum":"이글루코퍼레이션이 한국선급(KR)·프랑스선급(BV)에 이어 미국선급(ABS)으로부터 IACS 통일규칙 UR E27 인증을 추가 획득했다. 앞서 UR E26 기본승인(AiP) 레벨2 증서도 취득하며 토털 해사 보안 체계를 입증했다.","eSum":"Igloo Corporation added an ABS certification under IACS Unified Requirement UR E27, following earlier approvals from Korean Register (KR) and Bureau Veritas (BV). It had also obtained a UR E26 AiP Level 2 certificate, demonstrating an end-to-end maritime cyber-security framework.","kImp":"2024년 발효된 IACS UR E26/E27이 신조선 사이버보안 의무 기준으로 자리잡으며 관련 인증 수요가 급증하고 있다. 복수 선급 인증 확보는 국내 보안기업의 글로벌 해사시장 진입 관문이 된다.","eImp":"With IACS UR E26/E27 becoming mandatory cyber-security baselines for newbuildings, demand for such certification is surging. Securing multiple class approvals is a gateway for Korean security firms into the global maritime market.","url":"http://www.hansbiz.co.kr/news/articleView.html?idxno=851879"},{"code":"CLASS","title":"중견 조선사 VLGC 개념설계, 로이드선급(LR)·한국선급(KR) 기본인증 획득","src":"시사저널e","date":"2026-07-06","kSum":"국내 중견 조선사가 초대형 LPG운반선(VLGC) 개념설계에 대해 영국 로이드선급(LR)과 한국선급(KR)으로부터 기본인증(AiP)을 획득했다. 대형사가 LNG선에 집중하는 사이 성장성이 큰 VLGC를 신시장으로 공략하는 발판을 마련했다.","eSum":"A mid-tier Korean shipbuilder obtained Approval in Principle from Lloyd's Register (LR) and Korean Register (KR) for a very large gas carrier (VLGC) concept design. It provides a foothold in the high-growth VLGC segment while majors focus on LNG carriers.","kImp":"선급 AiP는 신선형 수주 영업의 필수 기술 자격으로, 중견 조선사의 제품 다각화 전략을 뒷받침한다. VLGC 수요 확대 국면에서 설계 경쟁력 확보가 수주 성패를 가른다.","eImp":"A class AiP is an essential technical credential in marketing new ship types, underpinning mid-tier yards' product-diversification strategy. As VLGC demand grows, design competitiveness will decide order wins.","url":"https://www.sisajournal-e.com/news/articleView.html?idxno=422229"},{"code":"CLASS","title":"한화오션, 로이드선급(LR)으로부터 KDDX 기본설계 설계인증(AiP) 획득","src":"에너지경제","date":"2026-07-02","kSum":"한화오션이 자체 기본설계를 수행한 한국형 차기 구축함(KDDX)에 대해 영국 로이드선급(LR)으로부터 설계인증(AiP)을 획득했다. 총사업비 7조8000억원 규모 KDDX 사업의 우선협상대상자 선정과 맞물린 성과다.","eSum":"Hanwha Ocean received a design Approval in Principle from Lloyd's Register (LR) for the Korea Destroyer Next Generation (KDDX), whose basic design it developed in-house. It comes alongside its selection as preferred bidder for the 7.8 trillion won program.","kImp":"방산 함정에 대한 국제 선급 설계인증은 수출형 함정의 규격 신뢰성과 대외 경쟁력을 높인다. 상선 중심이던 선급 서비스가 방산·특수선 영역으로 확장되는 흐름을 보여준다.","eImp":"An international class design approval for a naval combatant boosts the credibility and export competitiveness of the platform. It illustrates class services expanding from merchant ships into defense and specialized vessels.","url":"https://www.ekn.kr/web/view.php?key=20260702025048553"},{"code":"CLASS","title":"DNV 한국대표 \"멀티연료 시대 본격화…선급·조선소 역할 커진다\"","src":"조선비즈","date":"2026-07-08","kSum":"'조선업의 맥킨지'로 불리는 DNV 한국대표가 인터뷰에서 LNG를 넘어 메탄올·암모니아가 공존하는 멀티연료 시대의 도래를 강조했다. 탈탄소와 AX(AI 전환) 전략 속에서 선급과 조선소의 역할이 커지고 있다고 진단했다.","eSum":"DNV's Korea head, in an interview, stressed the onset of a multi-fuel era in which methanol and ammonia coexist with LNG. He argued that class societies and shipyards face expanding roles amid decarbonization and AI-transformation strategies.","kImp":"세계 최대 선급 중 하나인 DNV의 시장 진단은 한국 조선소의 연료·기술 로드맵에 직접적 영향을 준다. 멀티연료 대응 역량이 향후 고부가 수주 경쟁의 핵심 변수로 부상하고 있다.","eImp":"Market reads from DNV, one of the world's largest class societies, directly shape Korean yards' fuel and technology roadmaps. Multi-fuel readiness is emerging as a key variable in the competition for high-value orders.","url":"https://biz.chosun.com/industry/business-venture/2026/07/08/E6L5UIEQMFEMFPY46TIJZ57JRE/"},{"code":"CLASS","title":"\"해양 SMR 국제 규정 선점이 경쟁력\"…한국선급, IACS·IAEA 활동 강화","src":"전기신문","date":"2026-07-01","kSum":"해양 소형모듈원전(SMR) 상용화를 위한 국제 규정 선점이 글로벌 경쟁력을 좌우한다는 진단이 나왔다. 한국선급(KR)은 IMO 규정 개정 지원과 함께 IAEA·국제선급연합회(IACS)·NEMO 활동에 참여하며 인증체계 마련에 나서고 있다.","eSum":"Experts argue that pre-empting international rules for marine small modular reactors (SMR) will determine global competitiveness. Korean Register (KR) is engaging in IMO rule-revision support and IAEA, IACS and NEMO activities to help build the certification framework.","kImp":"규정 공백 상태인 해양 원자력 분야에서 선급의 규정 참여는 자국 산업의 국제 표준 주도권 확보와 직결된다. KR의 선제적 참여는 한국 조선·원자력 융합 기술의 상용화 속도를 높일 수 있다.","eImp":"In the unregulated marine-nuclear field, class participation in rule-making is directly tied to securing standards leadership for domestic industry. KR's proactive engagement could speed commercialization of Korea's shipbuilding-nuclear convergence tech.","url":"https://www.electimes.com/news/articleView.html?idxno=369750"},{"code":"CLASS","title":"한화오션, 미국선급(ABS)으로부터 암모니아 방출저감시스템(ARMS) 기본승인 획득","src":"파이낸셜투데이","date":"2026-07-20","kSum":"한화오션이 미국선급(ABS)으로부터 암모니아 연료 적용 핵심 장비인 ARMS(Ammonia Release Mitigation System)에 대한 기본승인(AiP)을 획득했다. 암모니아 추진선의 독성 누출 리스크를 완화하는 안전 설계를 인증받은 것이다.","eSum":"Hanwha Ocean obtained an ABS Approval in Principle for its Ammonia Release Mitigation System (ARMS), a key component for ammonia-fueled ships. The certification validates a safety design that mitigates the toxic-leak risk of ammonia propulsion.","kImp":"암모니아 추진선 상용화의 최대 걸림돌인 독성·안전 문제를 겨냥한 인증으로 무탄소 연료 전환의 실효성을 높인다. 안전 기자재의 선급 승인 확보는 암모니아선 발주 확대의 전제 조건이 된다.","eImp":"Targeting toxicity and safety, the biggest hurdle to commercial ammonia ships, the approval strengthens the viability of the zero-carbon fuel transition. Class approval of safety equipment is a precondition for expanding ammonia-ship orders.","url":"http://www.ftoday.co.kr/news/articleView.html?idxno=362321"}]},{"code":"COMM","type":"news","kTitle":"Section 16. 상업·용선시장","eTitle":"Section 16. Commercial & Chartering","items":[{"code":"COMM","title":"중국, 자동차운반선(PCTC) 부족에 올해 컨테이너선으로 사상 최대 200만대 수출 전망","src":"Splash247","date":"2026-07-21","kSum":"올해 전 세계에서 전용 자동차운반선(PCTC)이 아닌 컨테이너선 등 일반 선박으로 운송되는 자동차가 사상 최대 약 200만대에 이를 것으로 전망된다. 중국의 자동차 수출이 급증하는 가운데 PCTC 선복이 이를 따라가지 못하면서 컨테이너선 물동량에 상당한 보탬이 되고 있다.","eSum":"A record of roughly two million cars are expected to move this year on vessels other than dedicated car carriers, notably containerships. Chinese vehicle exports are outpacing PCTC fleet capacity, handing container shipping a meaningful cargo boost.","kImp":"PCTC 선복 부족이 구조화되면 자동차운반선 용선료 강세가 이어지고 완성차 물류가 컨테이너로 이전되는 흐름이 커진다. 현대글로비스·유코카캐리어스 등 국내 PCTC 사업자와 화주 모두에 직접적인 시황 신호다.","eImp":"A structural PCTC shortage keeps car-carrier charter rates firm while pushing finished-vehicle logistics toward boxes. It is a direct market signal for Korea's car-carrier operators and their shippers.","url":"https://splash247.com/record-2m-cars-tipped-to-move-in-containers-as-china-outgrows-car-carrier-fleet/"},{"code":"COMM","title":"다이애나쉬핑, 파나막스 벌커를 스톤쉬핑과 더 높은 용선료로 재성약","src":"Splash247","date":"2026-07-23","kSum":"다이애나쉬핑이 파나막스 벌크선 한 척을 스톤쉬핑과 더 높은 일일 용선료 조건의 신규 용선으로 전환했다. 앞선 울트라막스 인상에 이어 중형 벌크 시황의 상승 흐름을 재확인한다.","eSum":"Diana Shipping rolled one of its panamax bulkers into a stronger new fixture with Stone Shipping at an improved daily rate. It follows the owner's recent ultramax uplift and reinforces a firming mid-size dry bulk market.","kImp":"동일 선주가 연이어 상향 성약을 내놓는 것은 일시적 반등이 아닌 추세적 강세 가능성을 시사한다. 파나막스 스팟·기간용선 지표 개선은 벌크 선주 전반의 현금흐름에 우호적이다.","eImp":"Successive up-fixtures from the same owner suggest a trend rather than a one-off bounce. Stronger panamax rates support cash flows across the dry bulk owner base.","url":"https://splash247.com/diana-rolls-panamax-bulker-into-stronger-stone-shipping-fixture/"},{"code":"COMM","title":"퍼포먼스쉬핑, 아프라막스 'Blue Moon' MISC(AET)와 2년 연장 용선으로 수익 개선","src":"Splash247","date":"2026-07-14","kSum":"나스닥 상장 그리스 선주 퍼포먼스쉬핑이 아프라막스 유조선 'Blue Moon'의 용선을 MISC 그룹 유조선 자회사 AET와 2년 연장했다. 이번 연장으로 선박의 기간 수익이 상향됐다.","eSum":"Nasdaq-listed Greek owner Performance Shipping extended the charter of its aframax tanker Blue Moon with MISC Group's tanker arm AET for two years. The extension lifts the vessel's period earnings.","kImp":"우량 용선주와의 다년 기간용선 연장은 유조선 선주에게 시황 변동성 속 안정적 수익 가시성을 제공한다. 아프라막스 기간용선 수준 상향은 중형 원유선 시장 강세를 뒷받침한다.","eImp":"A multi-year extension with a blue-chip charterer gives a tanker owner stable earnings visibility amid volatility. A higher aframax period rate underpins strength in the mid-size crude market.","url":"https://splash247.com/performance-shipping-lifts-aframax-earnings-in-two-year-aet-extension/"},{"code":"COMM","title":"DHT 홀딩스, VLCC 1척 3년 기간용선 확보","src":"Splash247","date":"2026-07-14","kSum":"뉴욕 상장 VLCC 선주 DHT 홀딩스가 보유 선박 한 척을 3년 기간용선으로 성약하며 계약 커버리지를 확대했다. 스팟 노출을 줄이고 장기 수익 기반을 다지는 행보다.","eSum":"New York-listed VLCC owner DHT Holdings fixed one of its ships on a three-year time charter, adding contract cover. The move reduces spot exposure and locks in longer-term earnings.","kImp":"대형 원유선 선주가 3년 장기 용선을 택한 것은 향후 시황에 대한 헤지 수요와 용선주의 선복 확보 의지를 동시에 보여준다. VLCC 기간용선 성약은 원유 운임 시장의 방향성 지표로 주목된다.","eImp":"A VLCC owner opting for three-year cover reflects both hedging appetite and charterer demand to secure tonnage. VLCC period fixtures are watched as a directional signal for the crude freight market.","url":"https://splash247.com/dht-adds-three-year-vlcc-cover/"},{"code":"COMM","title":"양밍, 한화오션에 최대 12.2억달러 규모 컨테이너선 6척 신조 발주","src":"Splash247","date":"2026-07-21","kSum":"대만 선사 양밍해운이 한화오션을 최대 12억2,000만달러 규모의 6척 컨테이너선 신조 프로그램 건조사로 선정했다. 노후 선대 교체와 선복 확충을 겨냥한 발주다.","eSum":"Taiwanese carrier Yang Ming Marine Transport selected Hanwha Ocean for a six-ship containership newbuilding programme worth up to $1.22bn. The order targets fleet renewal and added capacity.","kImp":"대형 컨테이너선 신조 발주는 한국 조선소 수주잔량과 컨테이너 선복 증가 전망에 직접 영향을 준다. 향후 인도 물량은 정기선 운임과 선복 수급 균형에 변수로 작용한다.","eImp":"A large boxship order feeds directly into Korean yard backlogs and the container capacity outlook. Future deliveries will be a swing factor for liner freight rates and supply-demand balance.","url":"https://splash247.com/yang-ming-picks-hanwha-ocean-for-1-2bn-boxship-series/"},{"code":"COMM","title":"차이나머천츠에너지, 최대 7.28억달러 규모 초대형 광석운반선(VLOC) 6척 발주 추진","src":"Splash247","date":"2026-07-20","kSum":"상하이 상장 차이나머천츠에너지쉬핑이 계열 거래를 통해 최대 7억2,800만달러 규모의 초대형 광석운반선(VLOC) 6척을 발주할 계획이다. 철광석 장기 물동량을 겨냥한 대형 벌크 선복 확충이다.","eSum":"Shanghai-listed China Merchants Energy Shipping has lined up six very large ore carriers in a related-party deal worth up to $728m. The order expands large dry bulk tonnage aimed at long-haul iron ore trades.","kImp":"VLOC 대량 발주는 케이프사이즈·대형 벌크 선복 증가로 이어져 중장기 운임에 하방 압력을 줄 수 있다. 동시에 중국의 철광석 수입 물류 내재화 전략을 보여준다.","eImp":"A big VLOC order adds to cape and large-bulk supply, potentially pressuring longer-term rates. It also signals China's push to internalise iron ore import logistics.","url":"https://splash247.com/china-merchants-maps-out-728m-vloc-order/"},{"code":"COMM","title":"기니-중국 철광석 항로에 신형 선박(Wontara) 투입해 운송 속도 개선","src":"Splash247","date":"2026-07-21","kSum":"서아프리카 기니에서 중국으로 이어지는 철광석 항로에 하역 속도를 높이는 신형 선박 유형이 등장했다. 시만두 광산 등 신규 물량의 대중국 운송 효율을 겨냥한 것이다.","eSum":"A new vessel type has emerged on the West Africa-to-China iron ore route to speed up deliveries. It targets more efficient movement of fresh volumes, such as from the Simandou project, to China.","kImp":"장거리 철광석 물동량 확대는 톤마일 수요를 늘려 케이프사이즈 시황에 우호적이다. 신형 선형은 하역 회전율을 높여 실질 선복 공급과 운임 구조에 영향을 준다.","eImp":"Growing long-haul iron ore volumes lift tonne-mile demand, a positive for the capesize market. New ship designs that raise turnaround can reshape effective supply and freight structure.","url":"https://splash247.com/new-vessel-type-to-speed-guinea-china-iron-ore-trade/"},{"code":"COMM","title":"회그 오토라이너스(Höegh Autoliners), 아시아 완성차업체와 3억 달러 규모 수송계약 연장","src":"Splash247","date":"2026-07-10","kSum":"오슬로 상장 자동차운반선사 회그 오토라이너스가 주요 아시아 완성차 제조사와의 기존 계약을 2029년 12월까지 연장하며 약 3억 달러의 추가 매출을 확보했다. 이번 계약은 물량 확대와 시장 요율을 반영한 상향된 상업 조건을 포함하며 중국 남부 샤오모(Xiaomo)항이 서비스에 추가됐다.","eSum":"Oslo-listed car carrier operator Höegh Autoliners extended an existing contract with a major Asian carmaker until December 2029, adding about $300m in revenue. The deal includes higher committed volumes and updated commercial terms in line with market rates, and adds Xiaomo port in southern China to its Asia offering.","kImp":"선복이 타이트한 가운데 주요 화주와의 장기계약 백로그를 늘려 수익 가시성을 강화하는 업계 흐름을 잘 보여준다.","eImp":"It illustrates carriers locking in long-term volume cover from major carmakers to boost earnings visibility while fleet supply stays tight.","url":"https://splash247.com/hoegh-autoliners-adds-300m-to-asian-carmaker-deal/"},{"code":"COMM","title":"2000년 건조 4,310CEU PCTC '창성훙(Chang Sheng Hong)', 경매서 4,200만 달러 낙찰","src":"Splash247","date":"2026-07-22","kSum":"2000년 크로아티아 울랴니크 조선소에서 건조된 26년 된 중형 PCTC '창성훙'(4,310CEU)이 화요일 경매에서 약 4,200만 달러에 낙찰됐다. 상하이연합자산거래소의 예정가 9,500만 위안(1,400만 달러)의 약 3배에 달하는 이례적 고가다.","eSum":"The 26-year-old midsize PCTC Chang Sheng Hong (4,310 ceu), built in 2000 at Croatia's Uljanik, sold at auction on Tuesday for around $42m. That is roughly three times the Shanghai United Assets and Equity Exchange's RMB95m ($14m) reserve, an exceptionally high price.","kImp":"노후 중형선까지 초고가에 팔릴 만큼 타이트한 시장을 방증하며, 자동차운반선 자산가치 강세를 뚜렷이 보여준다.","eImp":"Even an aged midsize vessel fetching such a premium underscores how tight the market is and how firm car-carrier asset values have become.","url":"https://splash247.com/2000-built-car-carrier-fetches-42m-at-auction/"}]},{"code":"GEO","type":"news","kTitle":"Section 17. 지정학","eTitle":"Section 17. Geopolitics","items":[{"code":"GEO","title":"후티 반군, 홍해서 사우디 유조선 2척 타격…홍해 항로 안전 우려 재점화","src":"세계일보","date":"2026-07-23","kSum":"예멘 후티 반군이 홍해에서 사우디 소유 유조선 2척을 공격하면서 그동안 소강 상태였던 홍해 항로 봉쇄 위기가 다시 부각됐다. 같은 날 호르무즈 해협에서도 유조선 폭발 사고가 발생해 중동 양대 원유 수송로가 동시에 위협받게 됐다.","eSum":"Yemen's Houthis struck two Saudi-owned tankers in the Red Sea, reviving fears of a renewed blockade of the corridor after a period of relative calm. A tanker also exploded in the Strait of Hormuz the same day, putting both of the Middle East's main crude routes under simultaneous threat.","kImp":"홍해와 호르무즈가 동시에 흔들리면 수에즈 우회로 인한 항해 거리 증가, 전쟁위험할증보험 급등, 유조선 운임 급등이 겹쳐 글로벌 해상 공급망 비용이 전방위로 상승한다.","eImp":"Simultaneous disruption of the Red Sea and Hormuz stacks longer Suez-diversion voyages, surging war-risk premiums and spiking tanker rates on top of one another, pushing up global seaborne supply-chain costs across the board.","url":"https://www.segye.com/newsView/20260723519960?OutUrl=naver"},{"code":"GEO","title":"이란 혁명수비대 \"호르무즈 기뢰 부설 항로 통과 유조선 1척 폭발·화재\"","src":"뉴스1","date":"2026-07-23","kSum":"이란 이슬람혁명수비대(IRGC)는 호르무즈 해협 남쪽 기뢰 부설 항로를 통과하려던 유조선 3척 중 1척이 폭발해 화재가 났고 나머지 2척은 회항했다고 밝혔다. 이란은 해당 수역을 통제하고 있다며 사실상 해협 통항 봉쇄를 재확인했다.","eSum":"Iran's IRGC said one of three tankers attempting to pass a mined channel in the southern Strait of Hormuz exploded and caught fire while the other two turned back. Tehran said it controls the waters, effectively reaffirming a blockade of the strait.","kImp":"호르무즈는 세계 해상 원유의 약 5분의 1이 통과하는 요충지로, 기뢰 위협과 통항 차단은 유조선 운항 회피와 보험료 급등, 국제유가 상승을 즉각 촉발한다.","eImp":"Roughly a fifth of the world's seaborne oil passes through Hormuz, so mine threats and passage denial immediately trigger tanker avoidance, soaring insurance premiums and higher oil prices.","url":"https://www.news1.kr/world/middleeast-africa/6236378"},{"code":"GEO","title":"러시아 '그림자 함대' 유조선, 오만 해양보호구역서 기름 유출 정황","src":"YTN","date":"2026-07-18","kSum":"러시아산 원유를 수송한 혐의로 서방 제재 대상에 오른 그림자 함대 유조선이 오만 연안 해양보호구역에서 기름을 유출한 정황이 포착됐다. 유출 원인이 선박 결함인지 우크라이나의 표적 공격인지는 확인되지 않았다.","eSum":"A sanctioned Russian shadow-fleet tanker suspected of carrying Russian crude appears to have leaked oil in a marine protected area off Oman. It remains unclear whether the spill stemmed from the vessel's own defects or a Ukrainian targeting strike.","kImp":"노후·무보험 그림자 함대의 사고 위험이 현실화되면서 주요 항로 인근 환경 재난과 배상 공백, 제재 회피 선단에 대한 국제 감독 강화 압력이 커지고 있다.","eImp":"The accident highlights the environmental disaster and liability-gap risks of aging, uninsured shadow-fleet tankers near key routes, intensifying pressure for tighter international oversight of the sanctions-evading fleet.","url":"https://www.ytn.co.kr/_ln/0104_202607180838039753"},{"code":"GEO","title":"우크라 드론, 흑해서 러 '그림자 함대' 유조선 타격…해상물류 마비·밀값 급등","src":"연합뉴스","date":"2026-07-20","kSum":"우크라이나가 국제 제재를 회피해 흑해를 오가는 러시아 그림자 선단 유조선을 드론으로 잇달아 타격하면서 흑해 해상 물류가 마비 조짐을 보이고 있다. 젤렌스키 대통령은 흑해에서 러시아 그림자 함대 유조선 여러 척에 직격탄을 명중시켰다고 밝혔다.","eSum":"Ukraine's repeated drone strikes on Russian shadow-fleet tankers plying the Black Sea to evade sanctions are paralyzing regional maritime logistics. President Zelensky said several Russian shadow-fleet tankers took direct hits in the Black Sea.","kImp":"흑해 곡물·에너지 수송로가 전장으로 변하면서 밀 등 곡물 가격이 급등하고, 러시아 원유 수출망과 우회 선단 전반의 운항 리스크가 커지고 있다.","eImp":"As Black Sea grain and energy corridors turn into a battlefield, wheat and other grain prices are spiking while operational risks rise across Russia's crude export network and its evasion fleet.","url":"https://www.yna.co.kr/view/AKR20260720156000109?input=1195m"},{"code":"GEO","title":"파나마운하청, 가툰호 수위 하락에 25일부터 하루 통항 선박 34척으로 축소","src":"한국경제","date":"2026-07-22","kSum":"파나마운하 관리청은 가툰호 수위 하락과 강력한 엘니뇨 발생 가능성에 대비해 25일부터 일부 선박 예약 경매를 중단하고 하루 통항 가능 선박 수를 36척에서 34척으로 줄이기로 했다. 갈수기에는 통과 가능 선박이 20척 초반까지 떨어지고 급행료 부담도 커진다.","eSum":"The Panama Canal Authority will suspend some slot auctions from the 25th and cut daily transits from 36 to 34 vessels to prepare for falling Gatun Lake levels and a possible strong El Nino. In dry season, transit capacity can drop to the low 20s while premium-slot fees climb.","kImp":"파나마운하 통항 제한은 미주 동안 항로의 리드타임과 급행료 부담을 키워, 컨테이너·LPG·자동차운반선 등이 희망봉·수에즈 우회를 검토하게 만드는 구조적 병목 요인이다.","eImp":"Canal restrictions lengthen lead times and raise premium-slot costs on US East Coast routes, a structural bottleneck that pushes container, LPG and car carriers to weigh longer Cape or Suez diversions.","url":"https://magazine.hankyung.com/business/article/202607228414b"},{"code":"GEO","title":"미 의회, 중국 조선 패권 대응 위해 한·일과 'G7 방식' 조선 협력 논의","src":"VOA 코리아","date":"2026-07-22","kSum":"미국 의회 청문회에서 중국의 글로벌 조선 지배력에 맞서 한국·일본 등과 표준 선박 설계 공유 및 동맹 차원의 공동 대응 체계를 구축하자는 제안이 나왔다. 전문가들은 파나마운하 인근 항만 운영권을 둘러싼 최근 미·중 갈등도 함께 지적했다.","eSum":"At a US congressional hearing, experts proposed a G7-style bloc with allies such as South Korea and Japan to counter China's dominance in global shipbuilding, including shared standard vessel designs and a joint response to Chinese retaliation. They also flagged recent US-China friction over port operations near the Panama Canal.","kImp":"미국의 조선·항만 공급망 탈중국 움직임은 한국 조선업에 기회이자, 무역법 301조 대중 추가관세 등 미·중 해운 갈등이 글로벌 물동량과 항로 재편으로 번질 수 있음을 시사한다.","eImp":"Washington's push to de-risk shipbuilding and ports from China offers opportunities for Korean yards while signaling that US-China maritime friction, including Section 301 tariffs, could spill into global trade volumes and route realignment.","url":"https://www.voakorea.com/a/hearing-charting-a-new-course-countering-china-s-dominance-in-global-shipbuilding-20260722/8174895.html"},{"code":"GEO","title":"국제유가, 홍해·호르무즈 이중 봉쇄 위기에 두 달 만에 100달러 돌파","src":"뉴스핌","date":"2026-07-23","kSum":"홍해에서 후티의 유조선 공격과 호르무즈 해협 유조선 폭발이 겹치며 브렌트유 가격이 두 달 만에 배럴당 100달러를 넘어섰다. 중동 양대 원유 수송로가 동시에 봉쇄 위기에 놓이면서 에너지·해운 시장 전반의 불안이 확산됐다.","eSum":"Brent crude topped $100 a barrel for the first time in two months as Houthi tanker attacks in the Red Sea coincided with a tanker explosion in the Strait of Hormuz. With both key Middle East crude routes facing blockade risk at once, anxiety spread across energy and shipping markets.","kImp":"유가 급등은 벙커유 등 선박 연료비를 밀어 올리고 전쟁위험할증과 우회 항해까지 겹쳐, 정기선·유조선 운임과 인플레이션 전반에 파급되는 대표적 지정학 리스크다.","eImp":"Surging oil prices raise bunker fuel costs and, combined with war-risk premiums and rerouting, feed through to liner and tanker rates and broader inflation, a textbook geopolitical shock for shipping.","url":"https://www.newspim.com/news/view/20260723001325"},{"code":"GEO","title":"호르무즈 긴장에 엇갈린 해운 희비…유조선 운임 급등, 컨테이너·벌크는 부담","src":"에너지경제","date":"2026-07-21","kSum":"호르무즈 해협·오만 해역에서 이어진 선박 피격으로 유조선 운임이 급등한 반면, 파나마운하·희망봉·수에즈 우회에 따른 긴 항해거리와 항만 혼잡으로 컨테이너·벌크선은 부담이 커지고 있다. 중동발 긴장 고조가 선종별로 해운업 희비를 엇갈리게 하고 있다.","eSum":"Vessel strikes in the Strait of Hormuz and off Oman have sent tanker freight rates soaring, while container and bulk carriers face heavier costs from longer Panama, Cape and Suez diversions and port congestion. Rising Middle East tensions are splitting shipping fortunes by segment.","kImp":"지정학 리스크가 유조선에는 운임 상승 호재로, 컨테이너·벌크에는 우회·혼잡 비용 증가로 작용하는 구조로, 선사별 노선·선종 전략 재편이 불가피하다.","eImp":"Geopolitical risk lifts tanker earnings but burdens container and bulk operators with detour and congestion costs, forcing carriers to rethink route and segment strategies.","url":"https://www.ekn.kr/web/view.php?key=20260721026214477"}]},{"code":"TW","type":"news","kTitle":"Section 18. TradeWinds 선박관리","eTitle":"Section 18. TradeWinds Ship Management","items":[{"code":"TW","title":"미 상장 해운주, 중동 분쟁 확대 속 강세","src":"TradeWinds","date":"2026-07-24","kSum":"트레이드윈즈(TradeWinds)는 중동 분쟁 확대에도 미국 상장 해운주가 강세를 보이고 있다고 전한다. 지정학 리스크가 운임·심리에 오히려 호재로 작용하는 모습이다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports US-listed shipping stocks are thriving as the Middle East conflict expands. Geopolitical risk is buoying rates and sentiment rather than depressing them. (Paywalled — headline-based.)","kImp":"지정학 불안이 해운주 투자심리에 미치는 영향을 보여준다.","eImp":"Illustrates how geopolitics is lifting shipping equities.","url":"https://www.tradewindsnews.com/finance/us-listed-shipping-stocks-thriving-as-middle-east-conflict-expands/2-1-2020381"},{"code":"TW","title":"웨스트 오브 잉글랜드, 부실 선복 정리 후 S&P 'A' 등급 회복","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈는 P&I 클럽 웨스트 오브 잉글랜드(West of England)가 손실이 큰 선복을 정리한 뒤 S&P로부터 'A' 등급을 회복했다고 보도했다. 재무 건전성 개선이 인정받은 결과다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports P&I club West of England has won back its 'A' rating from S&P after clearing out costly tonnage. The upgrade reflects improved financial health. (Paywalled — headline-based.)","kImp":"P&I 클럽 재무건전성과 언더라이팅 규율의 중요성을 보여준다.","eImp":"Highlights the value of P&I underwriting discipline.","url":"https://www.tradewindsnews.com/insurance/west-wins-back-a-rating-from-s-p-after-clearing-out-costly-tonnage/2-1-2019972"},{"code":"TW","title":"노르딕 아메리칸 탱커스, '유례없는' 지정학에 호황 전망","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈에 따르면 노르딕 아메리칸 탱커스(Nordic American Tankers)의 한손(Hansson) 회장은 '유례없는' 지정학 환경이 회사에 호황을 가져올 것이라고 밝혔다. 탱커 운임 강세 기대가 배경이다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports Nordic American Tankers' Hansson says 'unprecedented' geopolitics means good times ahead for the company. The view rests on expectations of firm tanker rates. (Paywalled — headline-based.)","kImp":"지정학 불안이 탱커 시장 강세 기대를 키운다.","eImp":"Geopolitics is fuelling bullish tanker-market expectations.","url":"https://www.tradewindsnews.com/tankers/-unprecedented-geopolitics-means-good-times-ahead-for-nordic-american-tankers-hansson-says/2-1-2020175"},{"code":"TW","title":"탑 십스(Top Ships), 메가요트 매각 후 탱커 확장에 집중","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈는 탑 십스(Top Ships)가 창업주 피스티올리스(Pistiolis)로부터 사들였던 메가요트를 매각한 뒤 탱커 사업 확장에 집중하고 있다고 전했다. 자산 재편을 통한 핵심 사업 강화 움직임이다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports Top Ships is focusing on tanker expansion after selling a megayacht bought from boss Pistiolis. The move refocuses the company on its core fleet. (Paywalled — headline-based.)","kImp":"소형 상장선사의 자산 재편·확장 전략을 보여준다.","eImp":"Shows a small listed owner refocusing on core tanker growth.","url":"https://www.tradewindsnews.com/tankers/top-ships-focuses-on-tanker-expansion-after-selling-megayacht-bought-from-boss-pistiolis/2-1-2020009"},{"code":"TW","title":"DP월드, 호르무즈 우회 신규 UAE 항만 확인","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈는 DP월드(DP World)가 호르무즈 해협을 우회할 수 있는 신규 UAE 항만 계획을 확인했다고 보도했다. 해협 리스크에 대응한 대체 물류 인프라 구상이다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports DP World has confirmed new UAE ports designed to bypass the Strait of Hormuz. The plan offers alternative logistics infrastructure against chokepoint risk. (Paywalled — headline-based.)","kImp":"호르무즈 리스크에 대한 물류 대체경로 구축을 보여준다.","eImp":"Shows infrastructure hedging against Hormuz chokepoint risk.","url":"https://www.tradewindsnews.com/ports/new-uae-ports-to-bypass-strait-of-hormuz-dp-world-confirms/2-1-2020157"},{"code":"TW","title":"머스크·CMA CGM, 홍해 불확실성 속 초대형 컨선 발주 저울질","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈에 따르면 머스크(Maersk)와 CMA CGM이 홍해 불확실성 속에서 초대형 컨테이너선 발주를 검토하고 있다. 항로 재편 장기화 가능성에 대비한 선대 전략이 배경이다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports Maersk and CMA CGM are weighing mega-boxship orders amid Red Sea uncertainty. The move reflects fleet planning for prolonged rerouting. (Paywalled — headline-based.)","kImp":"홍해 리스크가 컨테이너 선대 발주 결정에 영향을 준다.","eImp":"Red Sea risk is shaping boxship ordering decisions.","url":"https://www.tradewindsnews.com/containers/maersk-and-cma-cgm-weigh-mega-boxship-orders-amid-red-sea-uncertainty/2-1-2019332"},{"code":"TW","title":"주요 선주, 호르무즈·홍해 '통행금지' 속 새 VLCC 항로 모색","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈는 주요 선주들이 호르무즈 해협과 홍해가 '통행금지 구역(no-go zones)'이 되면서 새로운 VLCC 항로를 찾고 있다고 전했다. 원유 운송 경로의 구조적 재편 조짐이다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports major owners are finding new VLCC trade routes as the Strait of Hormuz and Red Sea become 'no-go zones'. It signals a structural reshaping of crude routings. (Paywalled — headline-based.)","kImp":"원유 운송 항로의 구조적 변화 가능성을 보여준다.","eImp":"Points to structural change in crude tanker routings.","url":"https://www.tradewindsnews.com/tankers/major-owners-find-new-vlcc-trade-routes-as-strait-of-hormuz-and-red-sea-become-no-go-zones-/2-1-2019998"},{"code":"TW","title":"존 프레드릭센, 선대 재편 속 CSV 2척 DOF에 매각","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈는 존 프레드릭센(John Fredriksen)이 선대 재편의 일환으로 건설지원선(CSV) 2척을 DOF에 매각했다고 보도했다. 오프쇼어 자산 조정 움직임이다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports John Fredriksen has sold two construction support vessels to DOF amid a fleet reshuffle. The deal reflects offshore asset rebalancing. (Paywalled — headline-based.)","kImp":"오프쇼어 선대 자산 거래 동향을 보여준다.","eImp":"Reflects offshore fleet asset-trading activity.","url":"https://www.tradewindsnews.com/offshore/john-fredriksen-sells-two-construction-support-vessels-to-dof-amid-fleet-reshuffle/2-1-2019962"},{"code":"TW","title":"카자흐스탄, 흑해 탱커 수출 피격에 손해배상 추진","src":"TradeWinds","date":"2026-07-23","kSum":"트레이드윈즈는 카자흐스탄이 흑해를 통한 탱커 원유 수출이 공격을 받자 손해배상을 요구하고 나섰다고 전했다. 흑해 수출 물류의 안보 리스크가 부각된다. (유료 매체·헤드라인 기반)","eSum":"TradeWinds reports Kazakhstan is seeking damages as its Black Sea tanker exports come under attack. It underscores security risk to Black Sea export logistics. (Paywalled — headline-based.)","kImp":"흑해 원유 수출 경로의 안보 리스크를 부각한다.","eImp":"Highlights security risk to Black Sea crude export routes.","url":"https://www.tradewindsnews.com/tankers/kazakhstan-seeks-damages-as-black-sea-tanker-exports-come-under-attack/2-1-2020119"}]},{"code":"HOT","type":"news","kTitle":"Section 19. 핫이슈: 호르무즈 해협","eTitle":"Section 19. Hot Topic: Strait of Hormuz","items":[{"code":"HOT","title":"이란혁명수비대, 호르무즈 남쪽 기뢰 항로서 유조선 화재 주장…2척 회항","src":"글로벌이코노믹","date":"2026-07-24","kSum":"이란혁명수비대는 호르무즈해협 남쪽 기뢰가 설치된 항로를 통과하려던 유조선에서 화재가 발생했다고 주장했다. 추가로 유조선 2척이 항로를 되돌렸으며 이란 당국은 해당 수역을 통제하고 있다고 밝혔다.","eSum":"Iran's Revolutionary Guard claimed a tanker caught fire in a mined channel south of the Strait of Hormuz, with two more tankers reversing course. Tehran said it controls the waters as US airstrikes on Iran continued for a 12th day.","kImp":"이란이 호르무즈에 실제 기뢰를 부설하고 항로를 통제한다는 주장은 세계 최대 원유 수송로의 물리적 차단이 현실화됐음을 시사한다. 유조선 회항과 화재는 통항 리스크를 급격히 끌어올린다.","eImp":"Iran's claim of laying mines and controlling passage signals a physical closure of the world's top oil chokepoint is materializing. Tanker fires and turnbacks sharply raise transit risk for all shipping.","url":"https://www.g-enews.com/view.php?ud=2026072321321384199a1f309431_1"},{"code":"HOT","title":"미 12일째 이란 공습…대형 상선 호르무즈 통과 기피, 유가 20달러 급등","src":"VOA 코리아","date":"2026-07-23","kSum":"호르무즈 봉쇄 여파로 국제 유가는 교전 재개 이후 배럴당 약 20달러 급등해 브렌트유가 95달러 선에서 거래됐다. 해운업계는 대형 국제 상선들이 해협 통과를 사실상 기피하고 있다고 밝혔다.","eSum":"Brent crude jumped about $20 a barrel to around $95 since fighting resumed, driven by the Hormuz blockade. Shipping firms say large international merchant vessels are effectively avoiding the strait.","kImp":"루비오 국무장관은 이란이 호르무즈를 통제하고 통행료를 요구하는 선례가 만들어지면 전 세계 다른 병목에도 악영향을 줄 것이라고 경고했다. 상선 기피는 공급망 전반의 지연과 비용 급증으로 이어진다.","eImp":"Secretary Rubio warned that if Iran sets a precedent of controlling Hormuz and demanding tolls, other global chokepoints would be endangered. Merchant vessel avoidance means broad supply-chain delays and cost spikes.","url":"https://www.voakorea.com/a/u-s-launches-airstrikes-against-iran-for-12th-consecutive-day-072326/8175221.html"},{"code":"HOT","title":"홍해 통과 선박 전쟁보험료 0.3%→0.75%로 두 배 급등","src":"브릿지경제(viva100)","date":"2026-07-23","kSum":"후티의 사우디 해상봉쇄 선언 이후 홍해 통과 선박의 전쟁보험료가 선박가액의 0.3%에서 0.75% 안팎으로 두 배 이상 뛰었다. 이는 중동 전쟁으로 호르무즈 해협이 막힌 상태에서 추가로 불거진 위기다.","eSum":"War-risk premiums for vessels transiting the Red Sea more than doubled from about 0.3% to 0.75% of hull value after the Houthis declared a blockade of Saudi shipping. The spike compounds an already-closed Strait of Hormuz.","kImp":"전쟁보험료 급등은 유조선 운임·용선료 상승과 맞물려 아시아 정유사의 원유 도입 원가를 직접 끌어올린다. 호르무즈와 홍해 동시 리스크로 보험료 상승은 장기화될 소지가 크다.","eImp":"Soaring war-risk premiums, combined with rising tanker freight and charter rates, directly raise crude import costs for Asian refiners. With Hormuz and the Red Sea both at risk, premium hikes are likely to persist.","url":"https://www.viva100.com/article/20260723500831"},{"code":"HOT","title":"홍해서 유조선 줄줄이 회항…호르무즈 대체 우회로도 흔들","src":"이투데이","date":"2026-07-22","kSum":"후티 반군이 사우디 항만 이용 선박을 공격하겠다고 경고하자 사우디산 원유를 실은 유조선들이 홍해에서 잇달아 항로를 변경했다. 호르무즈를 피해 확보한 마지막 우회로마저 흔들리고 있다.","eSum":"After the Houthis threatened to attack ships using Saudi ports, tankers carrying Saudi crude reversed course one after another in the Red Sea. The last remaining detour route bypassing Hormuz is now under threat.","kImp":"호르무즈 봉쇄 이후 사우디의 대체 수출로였던 홍해까지 위협받으면서 유조선은 아프리카 희망봉 우회를 강요받는다. 우회 장기화 시 운항일수·운임·보험료가 동시에 상승한다.","eImp":"With the Red Sea, Saudi Arabia's alternative export route after Hormuz's closure, now threatened, tankers face forced detours around the Cape of Good Hope. Prolonged rerouting drives up voyage days, freight and insurance together.","url":"https://www.etoday.co.kr/news/view/2606309"},{"code":"HOT","title":"美 요청에 K-해군 호르무즈 파병 검토…기뢰제거 우선","src":"서울신문","date":"2026-07-23","kSum":"미국이 한국의 호르무즈 해협 참여를 요청한 가운데 한국 해군의 기뢰제거 임무가 우선 검토되고 있다. 좁은 해협에 기뢰 설치 가능성만 제기돼도 민간 선박 통항이 위축되고 보험료와 운임이 급등하기 때문이다.","eSum":"With Washington requesting South Korea's participation in the Strait of Hormuz, mine-clearing missions by the ROK Navy are being considered first. Even the mere possibility of mines in the narrow strait chills civilian transits and spikes premiums.","kImp":"다국적 해군의 호르무즈 투입 논의는 통항 안전 확보를 위한 국제적 개입이 본격화되고 있음을 보여준다. 기뢰 위협이 통항 위축의 핵심 변수로 부상했다.","eImp":"Discussions of multinational naval deployment to Hormuz show international intervention to secure passage is intensifying. The mine threat has emerged as the key variable suppressing transit.","url":"https://www.seoul.co.kr/news/international/2026/07/23/20260723500289"},{"code":"HOT","title":"교보증권 \"두 해협 동시 봉쇄 시 유가 배럴당 160달러\" 경고","src":"뉴스투데이","date":"2026-07-23","kSum":"교보증권은 호르무즈에 이어 바브엘만데브 해협까지 동시에 막힐 경우 국제유가가 배럴당 160달러까지 치솟는 '2차 충격'이 올 수 있다고 경고했다. 홍해는 전쟁 기간 사우디가 호르무즈를 피해 활용해 온 핵심 우회로다.","eSum":"Kyobo Securities warned that a simultaneous blockade of Hormuz and Bab el-Mandeb could trigger a 'second shock' pushing oil to $160 a barrel. The Red Sea has been Saudi Arabia's key detour around Hormuz during the war.","kImp":"양대 수송로 동시 마비 시나리오는 유가 급등뿐 아니라 운항일수 증가로 전쟁보험료를 포함한 운임을 폭등시켜 국내 정유사 도입원가에 직접 전가된다. 에너지 안보 리스크가 극단으로 치닫고 있다.","eImp":"A dual-chokepoint scenario would spike not just oil prices but also freight, including war-risk premiums, from longer voyages, feeding straight into refiners' import costs. Energy-security risk is heading toward an extreme.","url":"https://www.news2day.co.kr/article/20260723500082"},{"code":"HOT","title":"호르무즈 사실상 재봉쇄…UKMTO, 홍해 유조선 피격 확인","src":"조선비즈","date":"2026-07-23","kSum":"국제 유가가 배럴당 100달러를 돌파한 배경에는 호르무즈 해협의 사실상 재봉쇄와 새로운 무력 충돌이 있다. 영국해사무역기구(UKMTO)는 사우디 남서쪽 홍해 해역에서 유조선이 공격받았다고 확인했다.","eSum":"Oil topped $100 a barrel amid the de facto re-closure of the Strait of Hormuz and fresh armed clashes. The UK Maritime Trade Operations (UKMTO) confirmed a tanker was attacked in the Red Sea southwest of Saudi Arabia.","kImp":"UKMTO의 공식 확인은 해상 위협이 실제 공격으로 현실화됐음을 뒷받침한다. 호르무즈 재봉쇄로 유가가 100달러를 돌파하면서 미 국채금리도 18개월 만에 최고치로 뛰어 금융시장까지 파장이 번졌다.","eImp":"UKMTO's confirmation validates that maritime threats have turned into actual attacks. With Hormuz re-closed and oil above $100, US Treasury yields hit an 18-month high, spreading the shock into financial markets.","url":"https://biz.chosun.com/international/international_economy/2026/07/23/24SOCJA5Y5G3HL5RK7UJJMTDSU/"},{"code":"HOT","title":"호르무즈 하루 130척→10여 척으로 급감…통항 사실상 마비","src":"울산신문","date":"2026-07-23","kSum":"전쟁 이전 하루 130척 넘게 오가던 호르무즈 통항 선박이 봉쇄 뒤 10여 척으로 급감했다. 우회 시 항해 거리는 수천 킬로미터, 운항 일수는 열흘 이상 늘어나고 해상운임과 전쟁보험료가 걷잡을 수 없이 오르고 있다.","eSum":"Vessels transiting Hormuz plunged from over 130 a day before the war to around ten after the blockade. Detours add thousands of kilometers and more than ten days at sea, sending freight and war-risk premiums soaring.","kImp":"통항 선박의 90% 이상 급감은 호르무즈 봉쇄가 통계로 확인된 실질적 마비 상태임을 보여준다. 통항 붕괴는 원유·LNG뿐 아니라 나프타 등 핵심 산업 원료 공급까지 위협한다.","eImp":"A drop of over 90% in transiting vessels shows the Hormuz blockade is a statistically confirmed, effective paralysis. The collapse threatens supplies not only of crude and LNG but also naphtha and other key industrial feedstocks.","url":"https://www.ulsanpress.net/news/articleView.html?idxno=579707"}]},{"code":"SYS","type":"news","kTitle":"Section 20. 시스템·앱","eTitle":"Section 20. System & App","items":[{"code":"SYS","title":"한국, 항만용 '피지컬 AI(Physical AI)' 전략 발표","src":"Smart Maritime Network","date":"2026-07-23","kSum":"한국 정부가 항만 자동화·로봇·물류에 인공지능을 결합하는 '피지컬 AI' 전략을 공개했다. 항만 운영의 지능화를 국가 차원에서 추진하겠다는 구상이다.","eSum":"Korea has unveiled a national 'Physical AI' strategy applying artificial intelligence to port robotics, automation and logistics. The plan positions smart port operations as a state-level priority.","kImp":"항만 디지털·자동화 투자 흐름이 국가 정책으로 뒷받침된다.","eImp":"Signals state backing for port automation and digital investment.","url":"https://smartmaritimenetwork.com/2026/07/23/korea-unveils-physical-ai-strategy-for-ports/"},{"code":"SYS","title":"페트로나스(PETRONAS), 용선 LNG 선단에 GTT 마린 기술 도입 합의","src":"Smart Maritime Network","date":"2026-07-23","kSum":"말레이시아 페트로나스(PETRONAS)가 용선 중인 LNG 운반선 선단에 GTT의 마린 기술 솔루션을 적용하기로 합의했다. 화물 관리·성능 모니터링 디지털화가 핵심이다.","eSum":"PETRONAS has agreed to deploy GTT's marine tech solutions across its chartered LNG carrier fleet. The deal centres on digitalising cargo handling and performance monitoring.","kImp":"LNG 선대 디지털 성능관리 채택이 확대되고 있다.","eImp":"Shows growing uptake of digital performance tools on LNG fleets.","url":"https://smartmaritimenetwork.com/2026/07/23/petronas-agrees-gtt-marine-tech-deal-for-chartered-lng-fleet/"},{"code":"SYS","title":"데이비(Davie), 캐나다에 자율운항 선박 회사 설립","src":"Smart Maritime Network","date":"2026-07-23","kSum":"조선그룹 데이비(Davie)가 캐나다에 자율운항 선박 전문 회사를 신설했다. 자율·무인 선박 기술 상용화를 겨냥한 조직이다.","eSum":"Shipbuilding group Davie has established a dedicated autonomous vessel company in Canada. The unit targets commercialisation of autonomous and uncrewed ship technology.","kImp":"주요 조선사도 자율운항 시장에 본격 진입하고 있다.","eImp":"Major shipbuilders are moving into the autonomy market.","url":"https://smartmaritimenetwork.com/2026/07/23/davie-establishes-autonomous-vessel-company-in-canada/"},{"code":"SYS","title":"GT마리타임(GTMaritime), AI 이메일 관리 도구 출시","src":"Smart Maritime Network","date":"2026-07-23","kSum":"선박 통신 전문업체 GT마리타임(GTMaritime)이 인공지능 기반 이메일 관리 도구를 출시했다. 저대역폭 해상 환경에서 이메일 처리·보안을 자동화한다.","eSum":"Maritime communications firm GTMaritime has launched an AI-powered email management tool. It automates email handling and security in low-bandwidth shipboard environments.","kImp":"선내 업무용 AI 적용이 실무 도구 단계로 확산된다.","eImp":"AI is reaching practical shipboard workflow tools.","url":"https://smartmaritimenetwork.com/2026/07/23/gtmaritime-launches-ai-email-management-tool/"},{"code":"SYS","title":"민트라(Mintra), 해운업계용 'AI법(AI Act)' 교육과정 출시","src":"Smart Maritime Network","date":"2026-07-23","kSum":"해양 교육 전문업체 민트라(Mintra)가 EU AI법(AI Act) 대응 교육과정을 해운업계에 선보였다. AI 규제 준수 역량 강화를 목표로 한다.","eSum":"Maritime training provider Mintra has launched AI Act training courses for the shipping sector. The programme aims to build compliance capability for AI regulation.","kImp":"AI 규제 준수가 선원·사무직 교육 의제로 부상했다.","eImp":"AI regulatory compliance is now a training agenda item.","url":"https://smartmaritimenetwork.com/2026/07/23/mintra-launches-ai-act-training-courses-for-maritime-sector/"},{"code":"SYS","title":"메이지해운(Meiji Shipping), 선원 통신 플랫폼 도입","src":"Smart Maritime Network","date":"2026-07-23","kSum":"일본 메이지해운그룹(Meiji Shipping Group)이 선원 통신 플랫폼을 선대에 도입한다. 선내 복지·연결성 개선을 위한 조치다.","eSum":"Japan's Meiji Shipping Group is to deploy a crew communications platform across its fleet. The move aims to improve onboard connectivity and welfare.","kImp":"선원 연결성이 관리사·선주의 투자 우선순위가 됐다.","eImp":"Crew connectivity is a rising owner investment priority.","url":"https://smartmaritimenetwork.com/2026/07/23/meiji-shipping-group-to-deploy-crew-communications-platform/"},{"code":"SYS","title":"영국 RNLI, 구조정 선단에 디지털 항법시스템 도입","src":"Smart Maritime Network","date":"2026-07-23","kSum":"영국 왕립구명정협회(RNLI)가 구조정 선단에 디지털 항법시스템을 업그레이드한다. 구조 작전의 항법 정밀도와 안전성을 높이기 위한 것이다.","eSum":"The UK's RNLI is to upgrade its lifeboat fleet with digital navigation systems. The upgrade seeks to improve navigational precision and safety in rescue operations.","kImp":"디지털 항법이 소형·특수선 영역까지 확산된다.","eImp":"Digital navigation is spreading to small and specialised craft.","url":"https://smartmaritimenetwork.com/2026/07/23/rnli-to-upgrade-lifeboat-fleet-with-digital-navigation-systems/"},{"code":"SYS","title":"양밍(Yang Ming)·PSA, 탈탄소 협력 추진","src":"Smart Maritime Network","date":"2026-07-22","kSum":"대만 선사 양밍(Yang Ming)과 싱가포르 터미널 운영사 PSA가 탈탄소 협력에 나선다. 선사-터미널 간 데이터·운영 최적화를 통한 배출 저감이 목표다.","eSum":"Taiwan's Yang Ming and Singapore terminal operator PSA are to cooperate on decarbonisation. The partnership targets emissions cuts through carrier-terminal data and operational optimisation.","kImp":"선사·터미널 데이터 연계가 탈탄소 수단으로 부상한다.","eImp":"Carrier-terminal data integration emerges as a decarbonisation lever.","url":"https://smartmaritimenetwork.com/2026/07/22/yang-ming-and-psa-to-work-together-on-decarb/"},{"code":"SYS","title":"발렌시아항, 5G 디지털화 프로젝트 완료","src":"Smart Maritime Network","date":"2026-07-22","kSum":"스페인 발렌시아항이 5G 기반 디지털화 프로젝트를 완료했다. 항만 전역의 실시간 데이터·자동화 인프라를 구축했다.","eSum":"Spain's Port of Valencia has completed a 5G digitalisation project. It establishes real-time data and automation infrastructure across the port.","kImp":"5G가 스마트항만의 표준 인프라로 자리잡고 있다.","eImp":"5G is becoming standard smart-port infrastructure.","url":"https://smartmaritimenetwork.com/2026/07/22/port-of-valencia-completes-5g-digitalisation-project/"},{"code":"SYS","title":"인텔리안(Intellian), 최신 이리듐 GMDSS 단말기 출시","src":"Smart Maritime Network","date":"2026-07-21","kSum":"위성통신 업체 인텔리안(Intellian)이 최신 이리듐(Iridium) GMDSS 단말기를 출시했다. 세계해상조난안전시스템 통신 성능을 강화했다.","eSum":"Satellite communications firm Intellian has launched its latest Iridium GMDSS terminal. The unit enhances Global Maritime Distress and Safety System connectivity.","kImp":"GMDSS 위성통신 선택지가 이리듐 기반으로 넓어진다.","eImp":"Iridium-based GMDSS options are expanding.","url":"https://smartmaritimenetwork.com/2026/07/21/intellian-launches-latest-iridium-gmdss-terminal/"},{"code":"SYS","title":"J-오션중공업, 유캐스트(Ucast)와 스마트 조선소 협약","src":"Smart Maritime Network","date":"2026-07-21","kSum":"J-오션중공업(J-Ocean Heavy Industries)이 유캐스트(Ucast)와 스마트 조선소 구축 협약을 맺었다. 조선소 공정 디지털화가 핵심이다.","eSum":"J-Ocean Heavy Industries has signed a smart shipyard deal with Ucast. The agreement centres on digitalising shipyard production processes.","kImp":"조선소 디지털 전환 수요가 계속 확대된다.","eImp":"Demand for shipyard digital transformation keeps growing.","url":"https://smartmaritimenetwork.com/2026/07/21/j-ocean-heavy-industries-in-smart-shipyard-deal-with-ucast/"},{"code":"SYS","title":"한국 로봇, HMM 선박서 자율 선상작업 시험 완료","src":"Smart Maritime Network","date":"2026-07-17","kSum":"한국이 개발한 로봇이 HMM 선박에서 자율 선상작업 시험을 완료했다. 선내 반복·위험 작업의 로봇 자동화 가능성을 입증했다.","eSum":"A Korean-developed robot has completed autonomous shipboard operations tests on an HMM vessel. The trial demonstrates potential to automate repetitive and hazardous onboard tasks.","kImp":"선내 작업 로봇화가 실선 검증 단계에 진입했다.","eImp":"Onboard task robotics has reached live-vessel validation.","url":"https://smartmaritimenetwork.com/2026/07/17/korean-robot-completes-autonomous-shipboard-operations-test-on-hmm-vessel/"},{"code":"SYS","title":"로이드리스트 인텔리전스, 해양정보 전담조직 출범","src":"Smart Maritime Network","date":"2026-07-17","kSum":"로이드리스트 인텔리전스(Lloyd's List Intelligence)가 해양정보 전담조직(Maritime Intelligence Unit)을 출범했다. 리스크·제재·선박 데이터 분석 역량을 강화한다.","eSum":"Lloyd's List Intelligence has launched a dedicated Maritime Intelligence Unit. It strengthens analysis of risk, sanctions and vessel data.","kImp":"제재·리스크 데이터 분석 수요가 커지고 있다.","eImp":"Demand for sanctions and risk data analytics is rising.","url":"https://smartmaritimenetwork.com/2026/07/17/lloyds-list-intelligence-launches-maritime-intelligence-unit/"},{"code":"SYS","title":"한화오션(Hanwha Ocean), 라쿠텐 심포니와 사이버 협약","src":"Smart Maritime Network","date":"2026-07-09","kSum":"조선사 한화오션(Hanwha Ocean)이 라쿠텐 심포니(Rakuten Symphony)와 사이버보안 협약을 체결했다. 선박·조선소 OT 보안 강화를 겨냥한다.","eSum":"Shipbuilder Hanwha Ocean has agreed a cyber deal with Rakuten Symphony. The tie-up targets stronger OT security for vessels and shipyards.","kImp":"조선·해운 OT 사이버보안 협력이 활발해진다.","eImp":"OT cyber-security partnerships are accelerating in shipbuilding.","url":"https://smartmaritimenetwork.com/2026/07/09/shipbuilder-hanwha-ocean-agrees-cyber-deal-with-rakuten-symphony/"},{"code":"SYS","title":"하파그로이드(Hapag-Lloyd), 전 선대에 인마샛 넥서스웨이브 도입","src":"Smart Maritime Network","date":"2026-07-07","kSum":"컨테이너 선사 하파그로이드(Hapag-Lloyd)가 전 선대에 인마샛(Inmarsat) 넥서스웨이브(NexusWave) 통신을 도입하기로 했다. 고속·다중경로 해상 연결성을 확보한다.","eSum":"Container line Hapag-Lloyd has committed to a fleetwide roll-out of Inmarsat NexusWave. The service provides high-speed, multi-path maritime connectivity.","kImp":"대형 선사 중심으로 고대역 위성통신 채택이 확산된다.","eImp":"High-bandwidth satcom adoption is spreading among big carriers.","url":"https://smartmaritimenetwork.com/2026/07/07/hapag-lloyd-commits-to-fleetwide-inmarsat-nexuswave-roll-out/"}]},{"code":"SMGR","type":"news","kTitle":"Section 21. 선박관리사","eTitle":"Section 21. Ship Managers","items":[{"code":"SMGR","title":"앵글로이스턴(Anglo-Eastern), 제1회 기술 서밋 개최로 선단 기술표준 강화","src":"Anglo-Eastern","date":"2026-06-11","kSum":"앵글로이스턴이 조직 전반의 고위 리더와 기술 전문가들이 모인 첫 '기술 서밋(Technical Summit)'을 개최했다. 지식 공유를 통해 선박관리 기술표준을 한층 강화하는 자리였다.","eSum":"Anglo-Eastern held its inaugural Technical Summit, bringing together senior leaders and technical experts from across the organisation. The event focused on shared learning to raise technical standards across the managed fleet.","kImp":"세계 최대 독립 선박관리사의 기술역량 내재화 노력은 관리 품질과 안전 표준 향상으로 이어진다.","eImp":"A drive to internalise technical expertise at the largest independent manager supports higher management quality and safety standards.","url":"https://www.angloeastern.com/news-and-insights/anglo-eastern-technical-summit-2026-shared-learning-stronger-standards/"},{"code":"SMGR","title":"앵글로이스턴(Anglo-Eastern), 인턴 첫 승선 프로그램으로 차세대 해기인력 육성","src":"Anglo-Eastern","date":"2026-07-21","kSum":"앵글로이스턴이 미래 해양 전문인력 육성을 위해 인턴에게 첫 승선 경험을 제공하는 프로그램을 소개했다. 교실에서 배운 이론을 실제 선박 현장에서 체득하도록 지원한다.","eSum":"Anglo-Eastern highlighted a programme giving interns their first onboard experience as part of its commitment to developing future maritime professionals. It helps bridge classroom learning with real shipboard practice.","kImp":"선원 부족 시대에 조기 실무경험 제공은 인재 유치·유지에 유리하다.","eImp":"Early hands-on exposure helps attract and retain talent amid a tight seafarer labour market.","url":"https://www.angloeastern.com/news-and-insights/from-classroom-to-vessel-an-interns-first-onboard-experience/"},{"code":"SMGR","title":"앵글로이스턴(Anglo-Eastern), 고프로(GoPro) 활용해 선체 검사 방식 혁신","src":"Anglo-Eastern","date":"2026-06-02","kSum":"앵글로이스턴이 고프로(GoPro) 카메라를 활용해 선체 수중 검사 방식을 개선하고 있다고 밝혔다. 눈에 잘 보이지 않는 부분까지 시각적으로 점검해 유지보수 판단을 돕는다.","eSum":"Anglo-Eastern described how GoPro cameras are changing the way it conducts hull inspections. The approach improves visibility of hard-to-see areas to support maintenance decisions.","kImp":"저비용 디지털 도구의 현장 적용은 검사 효율과 선체 관리 품질을 높인다.","eImp":"Applying low-cost digital tools improves inspection efficiency and hull-management quality.","url":"https://www.angloeastern.com/news-and-insights/seeing-below-the-surface-how-gopro-is-changing-hull-inspections/"},{"code":"SMGR","title":"베른하르트슐테(BSM), 엘레나 판타지두 신임 최고인사책임자(CPO) 선임","src":"BSM","date":"2026-06-05","kSum":"베른하르트슐테십매니지먼트(BSM)가 엘레나 판타지두(Elena Pantazidou)를 신임 최고인사책임자(CPO)로 선임하는 등 인사 부문 리더십을 개편했다. 인적자원 기능 강화를 통해 선원·육상 인력 관리를 고도화한다.","eSum":"Bernhard Schulte Shipmanagement (BSM) appointed Elena Pantazidou as Chief People Officer as part of leadership changes across its people functions. The move strengthens its human-resources capabilities.","kImp":"670척 이상을 관리하는 대형 선박관리사의 인사 리더십 강화는 선원 확보·복지 경쟁력과 직결된다.","eImp":"Stronger people leadership at a manager of 670+ vessels is central to crew sourcing and welfare competitiveness.","url":"https://www.bs-shipmanagement.com/media-centre/article/481/leadership-changes-across-bsms-people-functions/"},{"code":"SMGR","title":"컬럼비아(Columbia), ZSFL 아프라막스 신조선 3척 관리 수임","src":"Columbia Group","date":"2026-05-18","kSum":"컬럼비아그룹이 ZSFL과의 선임장(appointment letter)에 따라 아프라막스급 신조선 3척의 관리를 맡게 됐다. 양사 전략적 협력의 다음 단계를 여는 계약이다.","eSum":"Columbia Group has taken on management of three AFRAMAX newbuildings following an appointment letter with ZSFL. It marks the next step in the strategic collaboration between the two companies.","kImp":"신조 탱커 선단 확대는 관리사 매출 기반과 기술관리 포트폴리오를 넓힌다.","eImp":"Winning newbuild tanker tonnage broadens the manager's revenue base and technical portfolio.","url":"https://columbiagroup.org/columbia-group-takes-on-management-of-three-aframax-newbuildings-following-appointment-letter-with-zsfl-marking-next-step-in-strategic-collaboration/"},{"code":"SMGR","title":"컬럼비아(Columbia), 2025 ESG 보고서 발간","src":"Columbia Group","date":"2026-06-29","kSum":"컬럼비아그룹이 2025년 ESG 보고서를 발간하며 지속가능성 성과와 목표를 공개했다. 환경·사회·거버넌스 전반의 진전을 투명하게 보고했다.","eSum":"Columbia Group published its 2025 ESG Report, disclosing its sustainability performance and targets. It transparently reports progress across environmental, social and governance areas.","kImp":"ESG 공시 강화는 화주·금융권의 요구에 부응하며 관리사 신뢰도를 높인다.","eImp":"Stronger ESG disclosure meets charterer and financier expectations and boosts manager credibility.","url":"https://columbiagroup.org/columbia-group-2025-esg-report/"},{"code":"SMGR","title":"컬럼비아(Columbia), '올해의 생도(Cadet of the Year)' 시상으로 해기사 육성 조명","src":"Columbia Group","date":"2026-06-10","kSum":"컬럼비아그룹이 '올해의 생도(Cadet of the Year)'를 선정해 아카데미에서 승선 근무로 이어지는 성장 여정을 조명했다. 차세대 해기사 양성 프로그램의 성과를 부각했다.","eSum":"Columbia Group's 'Cadet of the Year' celebrated a young officer's journey from academy to life at sea. It highlights the group's cadet-development programme.","kImp":"생도 육성 강화는 장기적 해기사 공급망 안정에 기여한다.","eImp":"Investing in cadets supports a stable long-term officer pipeline.","url":"https://columbiagroup.org/columbia-group-cadet-of-the-year/"},{"code":"SMGR","title":"컬럼비아 크루즈서비스(Columbia), 아도라(Adora) 크루즈와 협력 강화","src":"Columbia Group","date":"2026-05-07","kSum":"컬럼비아 크루즈서비스가 중국 아도라 크루즈(Adora Cruises)와의 전략적 협력을 심화했다. 크루즈 선박관리 분야에서의 파트너십을 확대한다.","eSum":"Columbia cruise services deepened its strategic cooperation with Adora Cruises. The move expands its partnership in cruise ship management.","kImp":"성장하는 아시아 크루즈 시장에서 관리사의 입지를 넓히는 계기다.","eImp":"It strengthens Columbia's position in the growing Asian cruise market.","url":"https://columbiagroup.org/columbia-cruise-services-strategic-cooperation-with-adora-cruises/"},{"code":"SMGR","title":"OSM 톰(OSM Thome), 사관 컨퍼런스서 '협력 리더십' 개발 세션 운영","src":"OSM Thome","date":"2026-07-14","kSum":"OSM 톰이 사관 컨퍼런스에서 '협력 리더십(Collaborative Leadership)'을 주제로 리더십 개발 세션을 진행했다. 선내 안전 운항에 기여하는 행동양식을 강화하는 것을 목표로 했다.","eSum":"OSM Thome ran a Leadership Development Session themed 'Collaborative Leadership' at its Officers Conference. It aimed to reinforce behaviours that contribute to safer operations onboard.","kImp":"선상 리더십 강화는 안전문화 정착과 사고 예방에 직접 기여한다.","eImp":"Building shipboard leadership directly supports safety culture and incident prevention.","url":"https://osmthome.com/strengthening-collaborative-leadership-at-sea/"},{"code":"SMGR","title":"브이그룹(V.Group), MOL LNG선 관리 수임…MOL, V.Ships France 지분 25% 인수","src":"V.Group","date":"2026-03-11","kSum":"브이그룹이 MOL의 최신 신조 LNG선 2척에 대한 완전 기술관리를 맡는다고 발표했다. MOL은 자회사를 통해 V.Ships France 지분 25%를 인수하며 장기 파트너십을 공고히 했다.","eSum":"V.Group announced it will assume full technical management of two of MOL's newbuild LNG carriers. MOL will cement the partnership by acquiring a 25% stake in V.Ships France.","kImp":"선주의 관리사 지분 투자는 신뢰와 LNG 선단 관리 물량 확대를 동시에 의미한다.","eImp":"An owner taking an equity stake signals deep trust and expands the LNG fleet under management.","url":"https://vgrouplimited.com/mol-acquires-stake-in-v-ships-france-expands-lng-fleet-under-management/"},{"code":"SMGR","title":"시너지마린(Synergy), 양밍(Yang Ming) LNG 이중연료 신조선 2척 기술관리 수임","src":"Synergy Marine","date":"2026-02-11","kSum":"시너지마린그룹이 양밍(Yang Ming)의 15,500 TEU급 LNG 이중연료 컨테이너 신조선 'YM WILLPOWER'와 'YM WORTHINESS' 2척의 기술관리를 맡았다. 양밍의 선대 현대화·지속가능성 전략을 지원한다.","eSum":"Synergy Marine Group assumed technical management of Yang Ming's two 15,500 TEU LNG dual-fuel container newbuilds, YM WILLPOWER and YM WORTHINESS. It supports the liner's fleet renewal and sustainability strategy.","kImp":"친환경 이중연료 신조선 관리 확대는 시너지의 대체연료 관리 역량과 포트폴리오를 강화한다.","eImp":"Adding alternative-fuel newbuilds strengthens Synergy's dual-fuel management capability and portfolio.","url":"https://www.synergymarinegroup.com/press-release/synergy-manages-yang-ming-lng-vessels/"}]}]};